INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u4-C1','math',3,2,'u4',2,'묶어서 분수로 나타내기 — 여러 개를 똑같이 묶어 전체 묶음의 수를 분모, 부분 묶음의 수를 분자로 나타내기(낱개 수가 아니라 묶음 수)',ARRAY['4수01-09']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u4-C2','math',3,2,'u4',2,'전체 정하기와 묶는 방법 — 부분끼리가 아니라 전체와 견주어 분수로 나타내고, 묶는 방법이 달라지면 같은 수라도 분수가 달라짐을 알기',ARRAY['4수01-09']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u4-C3','math',3,2,'u4',3,'전체의 분수만큼(개수) — 전체를 분모만큼 똑같이 묶어 단위분수만큼을 구하고, 분자만큼의 묶음을 세어 분수만큼이 몇 개인지 구하기(분자만 보고 답하지 않기)',ARRAY['4수01-09']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u4-C4','math',3,2,'u4',4,'길이·시간의 분수만큼 — 길이·시간을 분모만큼 똑같이 나누어 단위분수만큼을 구하고 분자만큼 모으기(하루 24시간, 1시간 60분, m·cm·km)',ARRAY['4수01-09']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u4-C5','math',3,2,'u4',5,'진분수와 가분수 — 분자가 분모보다 작으면 진분수, 분자가 분모와 같거나 크면 가분수임을 알고 단위분수 개수가 분자임을 알기',ARRAY['4수01-10']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u4-C6','math',3,2,'u4',5,'자연수를 분수로 — 단위분수가 분모만큼 모이면 1(⟨3/3⟩ = 1)이고, 자연수를 분모가 같은 가분수로 나타내며 수직선에서 자리 찾기',ARRAY['4수01-10']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u4-C7','math',3,2,'u4',6,'대분수와 가분수 바꾸기 — 자연수와 진분수로 이루어진 대분수를 알고 읽으며, 대분수 → 가분수는 단위분수가 모두 몇 개인지, 가분수 → 대분수는 통째로 모을 수 있는 만큼을 자연수로 나타내기',ARRAY['4수01-10']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u4-C8','math',3,2,'u4',7,'분모가 같은 분수의 크기 비교 — 가분수끼리는 분자로, 대분수끼리는 자연수 부분부터, 가분수와 대분수는 한쪽으로 바꾸어 단위분수 개수로 견주기',ARRAY['4수01-11']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u4-C9','math',3,2,'u4',8,'1보다 큰 소수 — 4 cm 7 mm = 4.7 cm처럼 1보다 큰 소수를 쓰고 「사 점 칠」로 읽으며, 소수를 0.1이 몇 개인지로 세고 cm·mm로 바꾸기',ARRAY['4수01-12']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u4-C10','math',3,2,'u4',9,'소수의 크기 비교 — 자연수 부분부터 견주고 같으면 소수점 오른쪽 수를 견주며, 0.1의 개수·수직선으로 확인하고 생활 기록(걸린 시간)을 견주기',ARRAY['4수01-14']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u4-C11','math',3,2,'u4',10,'분수와 소수의 크기 비교 — 분모가 10인 분수 ↔ 소수로 한쪽으로 바꾸어 견주고, 크기 비교에 알맞은 수를 하나씩 넣어 찾기',ARRAY['4수01-11']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X01','math',3,'u4',ARRAY['M3-2-u4-C1','M3-2-u4-C2']::text[],'부분 묶음을 나머지 묶음과 견주어 분모로 쓴다(검은 돌 3개·흰 돌 4개 → ⟨3/4⟩)','부분은 전체와 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X02','math',3,'u4',ARRAY['M3-2-u4-C1','M3-2-u4-C2']::text[],'묶음 수 대신 낱개 수로 분수를 쓴다(12를 2씩 묶어 8은 → ⟨8/12⟩)','묶음이 몇 개인지 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X03','math',3,'u4',ARRAY['M3-2-u4-C1','M3-2-u4-C5','M3-2-u4-C6','M3-2-u4-C7']::text[],'분모와 분자를 바꾸어 쓴다(6묶음 중 4묶음 → ⟨6/4⟩)','아래 분모·위 분자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X04','math',3,'u4',ARRAY['M3-2-u4-C3','M3-2-u4-C4']::text[],'분수만큼을 구할 때 분자만 보고 답한다(12의 ⟨3/4⟩ → 3)','분모만큼 묶고 분자만큼 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X05','math',3,'u4',ARRAY['M3-2-u4-C3','M3-2-u4-C4']::text[],'단위분수만큼(한 묶음)에서 멈춘다(12의 ⟨2/3⟩ → 4)','분자만큼 모으기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X06','math',3,'u4',ARRAY['M3-2-u4-C3','M3-2-u4-C4']::text[],'분수만큼에서 분모와 분자의 역할을 바꾼다(12의 ⟨3/4⟩ → 12를 3묶음으로 나눈 것 중 4묶음)','분모만큼 똑같이 나누기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X07','math',3,'u4',ARRAY['M3-2-u4-C1','M3-2-u4-C3']::text[],'묶음 수와 한 묶음 안의 개수를 헷갈린다(몇 묶음인지 물었는데 한 묶음의 개수를 답한다)','묶음 수 ↔ 한 묶음 개수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X08','math',3,'u4',ARRAY['M3-2-u4-C5','M3-2-u4-C7']::text[],'진분수·가분수·대분수의 뜻을 헷갈린다(⟨4/4⟩을 진분수로, 분모가 큰 분수를 가분수로)','분자와 분모를 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X09','math',3,'u4',ARRAY['M3-2-u4-C6']::text[],'자연수를 분수로 나타낼 때 자연수를 그대로 분자에 쓴다(2 = ⟨2/8⟩)','1 = ⟨8/8⟩, 2 = ⟨16/8⟩') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X10','math',3,'u4',ARRAY['M3-2-u4-C6','M3-2-u4-C7']::text[],'대분수를 가분수로 바꿀 때 자연수 부분을 단위분수 개수로 바꾸지 않는다(⟨2 3/4⟩ → ⟨5/4⟩·⟨8/4⟩)','자연수 1 = 분모만큼') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X11','math',3,'u4',ARRAY['M3-2-u4-C7']::text[],'가분수를 대분수로 바꿀 때 분수 부분을 가분수로 남긴다(⟨5/2⟩ → ⟨1 3/2⟩)','분수 부분은 진분수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X12','math',3,'u4',ARRAY['M3-2-u4-C7']::text[],'대분수의 자연수 부분(통째)을 빼먹거나 잘못 센다(⟨13/8⟩ → ⟨5/8⟩·⟨2 5/8⟩)','통째로 몇 번 모이는지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X13','math',3,'u4',ARRAY['M3-2-u4-C8']::text[],'분모가 같은 분수에서 분자가 작을수록 크다고 하거나, 대분수를 분수 부분만 보고 견준다(⟨1 4/5⟩ > ⟨2 1/5⟩)','자연수 부분부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X14','math',3,'u4',ARRAY['M3-2-u4-C8','M3-2-u4-C11']::text[],'가분수와 대분수(분수와 소수)를 바꾸지 않고 겉으로 보이는 수만 견준다(⟨32/15⟩은 32라서 크다)','한쪽으로 바꾸어 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X15','math',3,'u4',ARRAY['M3-2-u4-C9','M3-2-u4-C10']::text[],'소수를 0.1의 개수로 셀 때 자연수 부분을 빼먹는다(2.9 → 0.1이 9개)','1 = 0.1이 10개') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X16','math',3,'u4',ARRAY['M3-2-u4-C9','M3-2-u4-C11']::text[],'소수를 쓰거나 읽을 때 소수점 앞뒤를 바꾼다(⟨5 8/10⟩ → 8.5, 9.3 → 삼 점 구)','자연수 . 십분의 몇') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X17','math',3,'u4',ARRAY['M3-2-u4-C9']::text[],'소수와 cm·mm·0.1 개수를 바꿀 때 자리를 잘못 쓴다(0.1이 35개 → 35·0.35, 4 cm 7 mm → 4.07 cm)','0.1이 10개 = 1') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X18','math',3,'u4',ARRAY['M3-2-u4-C10','M3-2-u4-C11']::text[],'소수의 크기를 소수점 오른쪽 수만 보고 견준다(1.8 > 2.3)','자연수 부분부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X19','math',3,'u4',ARRAY['M3-2-u4-C10']::text[],'기록(걸린 시간)은 짧을수록 빠른데 큰 수를 빠르다고 한다','걸린 시간이 짧을수록 빠름') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X20','math',3,'u4',ARRAY['M3-2-u4-C1','M3-2-u4-C2','M3-2-u4-C3','M3-2-u4-C4','M3-2-u4-C5','M3-2-u4-C6','M3-2-u4-C7','M3-2-u4-C8','M3-2-u4-C9','M3-2-u4-C10','M3-2-u4-C11']::text[],'묻는 말을 거꾸로 읽는다 — 큰↔작은, 진분수↔가분수, 먹은↔남은, 색칠한↔색칠 안 한','물음의 핵심 말에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X21','math',3,'u4',ARRAY['M3-2-u4-C1','M3-2-u4-C3','M3-2-u4-C4','M3-2-u4-C6','M3-2-u4-C7','M3-2-u4-C8','M3-2-u4-C10','M3-2-u4-C11']::text[],'개수를 세거나 셈하는 데서 하나 많거나 적게 답한다(경계의 수를 넣거나 빼기 포함)','하나씩 넣어 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X22','math',3,'u4',ARRAY['M3-2-u4-C2','M3-2-u4-C3','M3-2-u4-C8','M3-2-u4-C10','M3-2-u4-C11']::text[],'크기를 견줄 수 있는데도 「알 수 없다」·「같다」고 하거나 분수와 소수는 견줄 수 없다고 한다','단위분수·0.1 개수로 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X23','math',3,'u4',ARRAY['M3-2-u4-C1','M3-2-u4-C2','M3-2-u4-C3','M3-2-u4-C4']::text[],'분모를 묶음(부분)의 수가 아니라 한 묶음의 개수(한 부분의 크기)로 여긴다 — 「똑같이 2묶음」을 「2개씩」으로 묶거나, 8의 ⟨1/4⟩을 4개씩 묶어 4라 하고, 12의 ⟨1/3⟩을 3이라고 한다','분모는 「몇 묶음으로 나누는지」 — 몇 개씩이 아니라 몇 묶음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X24','math',3,'u4',ARRAY['M3-2-u4-C5','M3-2-u4-C6']::text[],'자연수와 크기가 같은 가분수(⟨4/4⟩·⟨8/8⟩·⟨8/4⟩)를 가분수가 아니라 자연수라고 분류한다','⟨4/4⟩는 1과 크기가 같은 가분수 — 자연수는 1, 2, 3처럼 쓴 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X25','math',3,'u4',ARRAY['M3-2-u4-C4','M3-2-u4-C8']::text[],'전체의 분수만큼(6 m의 ⟨1/3⟩만큼 = 2 m)과 길이 자체인 분수(⟨1/3⟩ m)를 헷갈린다','「6 m의 ⟨1/3⟩만큼」은 6 m를 3부분으로 나눈 1부분 — 2 m') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u4-X26','math',3,'u4',ARRAY['M3-2-u4-C1','M3-2-u4-C2']::text[],'여러 개를 하나의 전체로 보지 않고 낱개 하나하나를 똑같이 나눈다(와플 4개를 하나씩 반으로 잘라 ⟨1/2⟩을 만든다)','여러 개가 모여 하나의 전체 — 한 묶음에 같은 수가 들어가게 묶기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L02_basic#1','math',3,2,'u4','L02','tb_g3_2_math_u4_L02_basic','lesson_basic','M3-2-u4-C1',1,'mc','auto','은비는 학습 발표회를 준비하는 친구들에게 줄 와플 4개를 똑같이 2묶음으로 나누어 포장했어요. 와플 1묶음은 전체의 얼마인가요?',ARRAY['M3-2-u4-X02','M3-2-u4-X03']::text[],true,'{"seq":1,"concept":"M3-2-u4-C1","difficulty":1,"kind":"mc","stem":"은비는 학습 발표회를 준비하는 친구들에게 줄 와플 4개를 똑같이 2묶음으로 나누어 포장했어요. 와플 1묶음은 전체의 얼마인가요?","options":[{"t":"⟨1/2⟩","correct":true},{"t":"⟨1/4⟩","mis":"M3-2-u4-X02"},{"t":"⟨4/2⟩","mis":"M3-2-u4-X03"}],"explanation":["전체는 와플 4개 — 똑같이 2묶음으로 나누었어요.","부분 와플 1묶음은 전체를 똑같이 2묶음으로 나눈 것 중의 1묶음이에요.","그래서 와플 1묶음은 전체의 ⟨1/2⟩ — 낱개 4개 중 1개로 보지 않아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]]},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]}],"u":30},"variant_rule":{"alt":[{"stem":"「익힘」 은비는 와플 6개를 똑같이 3묶음으로 나누어 포장했어요. 와플 1묶음은 전체의 얼마인가요?","options":[{"t":"⟨1/3⟩","correct":true},{"t":"⟨1/6⟩","mis":"M3-2-u4-X02"},{"t":"⟨6/3⟩","mis":"M3-2-u4-X03"}],"explanation":["전체는 와플 6개 — 똑같이 3묶음으로 나누었어요.","부분 와플 1묶음은 3묶음 중의 1묶음이에요.","그래서 와플 1묶음은 전체의 ⟨1/3⟩이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]]},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]]},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]]}],"u":30}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L02_basic#2','math',3,2,'u4','L02','tb_g3_2_math_u4_L02_basic','lesson_basic','M3-2-u4-C1',1,'sa','auto','8을 2씩 묶으면 모두 몇 묶음이 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u4-C1","difficulty":1,"kind":"sa","stem":"8을 2씩 묶으면 모두 몇 묶음이 되나요? 숫자로 쓰세요.","answer":["4"],"explanation":["8을 2씩 묶어요.","2, 4, 6, 8 — 2씩 4번이에요.","8을 2씩 묶으면 4묶음이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]]},{"p":[[1,0],[2,0],[2,1],[1,1]]},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]]},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]]},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]]},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]]},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]]}],"u":29},"variant_rule":{"alt":[{"stem":"「익힘」 18을 3씩 묶으면 모두 몇 묶음이 되나요? 숫자로 쓰세요.","answer":["6"],"explanation":["18을 3씩 묶어요.","3, 6, 9, 12, 15, 18 — 3씩 6번이에요.","18을 3씩 묶으면 6묶음이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]]},{"p":[[1,0],[2,0],[2,1],[1,1]]},{"p":[[2,0],[3,0],[3,1],[2,1]]},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]},{"p":[[4.7,0],[5.7,0],[5.7,1],[4.7,1]]},{"p":[[5.7,0],[6.7,0],[6.7,1],[5.7,1]]},{"p":[[7.4,0],[8.4,0],[8.4,1],[7.4,1]]},{"p":[[8.4,0],[9.4,0],[9.4,1],[8.4,1]]},{"p":[[9.4,0],[10.4,0],[10.4,1],[9.4,1]]},{"p":[[11.1,0],[12.1,0],[12.1,1],[11.1,1]]},{"p":[[12.1,0],[13.1,0],[13.1,1],[12.1,1]]},{"p":[[13.1,0],[14.1,0],[14.1,1],[13.1,1]]},{"p":[[14.8,0],[15.8,0],[15.8,1],[14.8,1]]},{"p":[[15.8,0],[16.8,0],[16.8,1],[15.8,1]]},{"p":[[16.8,0],[17.8,0],[17.8,1],[16.8,1]]},{"p":[[18.5,0],[19.5,0],[19.5,1],[18.5,1]]},{"p":[[19.5,0],[20.5,0],[20.5,1],[19.5,1]]},{"p":[[20.5,0],[21.5,0],[21.5,1],[20.5,1]]}],"u":13}},{"stem":"8을 1씩 묶으면 모두 몇 묶음이 되나요? 숫자로 쓰세요.","answer":["8"],"explanation":["8을 1씩 묶어요.","한 묶음에 1개씩 — 8개면 8묶음이에요.","8을 1씩 묶으면 8묶음이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]]},{"p":[[1.7,0],[2.7,0],[2.7,1],[1.7,1]]},{"p":[[3.4,0],[4.4,0],[4.4,1],[3.4,1]]},{"p":[[5.1,0],[6.1,0],[6.1,1],[5.1,1]]},{"p":[[6.8,0],[7.8,0],[7.8,1],[6.8,1]]},{"p":[[8.5,0],[9.5,0],[9.5,1],[8.5,1]]},{"p":[[10.2,0],[11.2,0],[11.2,1],[10.2,1]]},{"p":[[11.9,0],[12.9,0],[12.9,1],[11.9,1]]}],"u":23}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L02_basic#3','math',3,2,'u4','L02','tb_g3_2_math_u4_L02_basic','lesson_basic','M3-2-u4-C1',1,'mc','auto','8을 2씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?',ARRAY['M3-2-u4-X01','M3-2-u4-X03','M3-2-u4-X02']::text[],true,'{"seq":3,"concept":"M3-2-u4-C1","difficulty":1,"kind":"mc","stem":"8을 2씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?","options":[{"t":"⟨2/4⟩","correct":true},{"t":"⟨2/2⟩","mis":"M3-2-u4-X01"},{"t":"⟨4/2⟩","mis":"M3-2-u4-X03"},{"t":"⟨4/4⟩","mis":"M3-2-u4-X02"}],"explanation":["8을 2씩 묶으면 4묶음 — 전체 묶음의 수 4가 분모예요.","부분은 그중 2묶음 — 부분 묶음의 수 2가 분자예요.","4는 8의 ⟨2/4⟩ — 낱개의 수가 아니라 묶음의 수로 나타내요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]]},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]]},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]]},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]]}],"u":29},"variant_rule":{"alt":[{"stem":"8을 1씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?","options":[{"t":"⟨6/8⟩","correct":true},{"t":"⟨6/2⟩","mis":"M3-2-u4-X01"},{"t":"⟨8/6⟩","mis":"M3-2-u4-X03"},{"t":"⟨2/8⟩","mis":"M3-2-u4-X20"}],"explanation":["8을 1씩 묶으면 8묶음 — 전체 묶음의 수 8이 분모예요.","부분은 그중 6묶음 — 부분 묶음의 수 6이 분자예요.","6은 8의 ⟨6/8⟩ — 낱개의 수가 아니라 묶음의 수로 나타내요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1.7,0],[2.7,0],[2.7,1],[1.7,1]],"hi":true},{"p":[[3.4,0],[4.4,0],[4.4,1],[3.4,1]],"hi":true},{"p":[[5.1,0],[6.1,0],[6.1,1],[5.1,1]],"hi":true},{"p":[[6.8,0],[7.8,0],[7.8,1],[6.8,1]],"hi":true},{"p":[[8.5,0],[9.5,0],[9.5,1],[8.5,1]],"hi":true},{"p":[[10.2,0],[11.2,0],[11.2,1],[10.2,1]]},{"p":[[11.9,0],[12.9,0],[12.9,1],[11.9,1]]}],"u":23}},{"stem":"15를 3씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?","options":[{"t":"⟨3/5⟩","correct":true},{"t":"⟨3/2⟩","mis":"M3-2-u4-X01"},{"t":"⟨5/3⟩","mis":"M3-2-u4-X03"},{"t":"⟨9/5⟩","mis":"M3-2-u4-X02"}],"explanation":["15를 3씩 묶으면 5묶음 — 전체 묶음의 수 5가 분모예요.","부분은 그중 3묶음 — 부분 묶음의 수 3이 분자예요.","9는 15의 ⟨3/5⟩ — 낱개의 수가 아니라 묶음의 수로 나타내요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[4.7,0],[5.7,0],[5.7,1],[4.7,1]],"hi":true},{"p":[[5.7,0],[6.7,0],[6.7,1],[5.7,1]],"hi":true},{"p":[[7.4,0],[8.4,0],[8.4,1],[7.4,1]],"hi":true},{"p":[[8.4,0],[9.4,0],[9.4,1],[8.4,1]],"hi":true},{"p":[[9.4,0],[10.4,0],[10.4,1],[9.4,1]],"hi":true},{"p":[[11.1,0],[12.1,0],[12.1,1],[11.1,1]]},{"p":[[12.1,0],[13.1,0],[13.1,1],[12.1,1]]},{"p":[[13.1,0],[14.1,0],[14.1,1],[13.1,1]]},{"p":[[14.8,0],[15.8,0],[15.8,1],[14.8,1]]},{"p":[[15.8,0],[16.8,0],[16.8,1],[15.8,1]]},{"p":[[16.8,0],[17.8,0],[17.8,1],[16.8,1]]}],"u":16}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L02_basic#4','math',3,2,'u4','L02','tb_g3_2_math_u4_L02_basic','lesson_basic','M3-2-u4-C1',1,'mc','auto','「확인 문제」 하트 14개를 2개씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?',ARRAY['M3-2-u4-X01','M3-2-u4-X03','M3-2-u4-X02']::text[],true,'{"seq":4,"concept":"M3-2-u4-C1","difficulty":1,"kind":"mc","stem":"「확인 문제」 하트 14개를 2개씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?","options":[{"t":"⟨3/7⟩","correct":true},{"t":"⟨3/4⟩","mis":"M3-2-u4-X01"},{"t":"⟨7/3⟩","mis":"M3-2-u4-X03"},{"t":"⟨6/7⟩","mis":"M3-2-u4-X02"}],"explanation":["14를 2씩 묶으면 7묶음 — 전체 묶음의 수 7이 분모예요.","부분은 그중 3묶음 — 부분 묶음의 수 3이 분자예요.","6은 14의 ⟨3/7⟩ — 낱개의 수가 아니라 묶음의 수로 나타내요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]],"hi":true},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]],"hi":true},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]]},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]]},{"p":[[10.8,0],[11.8,0],[11.8,1],[10.8,1]]},{"p":[[11.8,0],[12.8,0],[12.8,1],[11.8,1]]},{"p":[[13.5,0],[14.5,0],[14.5,1],[13.5,1]]},{"p":[[14.5,0],[15.5,0],[15.5,1],[14.5,1]]},{"p":[[16.2,0],[17.2,0],[17.2,1],[16.2,1]]},{"p":[[17.2,0],[18.2,0],[18.2,1],[17.2,1]]}],"u":16},"variant_rule":{"alt":[{"stem":"하트 6개를 2개씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨3/2⟩","mis":"M3-2-u4-X03"},{"t":"⟨4/3⟩","mis":"M3-2-u4-X02"},{"t":"⟨2/6⟩","mis":"M3-2-u4-X02"}],"explanation":["6을 2씩 묶으면 3묶음 — 전체 묶음의 수 3이 분모예요.","부분은 그중 2묶음 — 부분 묶음의 수 2가 분자예요.","4는 6의 ⟨2/3⟩ — 낱개의 수가 아니라 묶음의 수로 나타내요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]]},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]]}],"u":30}},{"stem":"별 8개를 4개씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?","options":[{"t":"⟨1/2⟩","correct":true},{"t":"⟨4/2⟩","mis":"M3-2-u4-X02"},{"t":"⟨1/8⟩","mis":"M3-2-u4-X02"},{"t":"⟨1/4⟩","mis":"M3-2-u4-X23"}],"explanation":["8을 4씩 묶으면 2묶음 — 전체 묶음의 수 2가 분모예요.","부분은 그중 1묶음 — 부분 묶음의 수 1이 분자예요.","4는 8의 ⟨1/2⟩ — 낱개의 수가 아니라 묶음의 수로 나타내요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]],"hi":true},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]]},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]},{"p":[[2.7,1],[3.7,1],[3.7,2],[2.7,2]]},{"p":[[3.7,1],[4.7,1],[4.7,2],[3.7,2]]}],"u":30}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L02_basic#5','math',3,2,'u4','L02','tb_g3_2_math_u4_L02_basic','lesson_basic','M3-2-u4-C1',2,'mc','auto','15를 3씩 묶었어요. 9는 15의 얼마인가요?',ARRAY['M3-2-u4-X01','M3-2-u4-X03','M3-2-u4-X02']::text[],true,'{"seq":5,"concept":"M3-2-u4-C1","difficulty":2,"kind":"mc","stem":"15를 3씩 묶었어요. 9는 15의 얼마인가요?","options":[{"t":"⟨3/5⟩","correct":true},{"t":"⟨3/2⟩","mis":"M3-2-u4-X01"},{"t":"⟨5/3⟩","mis":"M3-2-u4-X03"},{"t":"⟨9/5⟩","mis":"M3-2-u4-X02"}],"explanation":["15를 3씩 묶으면 5묶음 — 전체 묶음의 수 5가 분모예요.","부분은 그중 3묶음 — 부분 묶음의 수 3이 분자예요.","9는 15의 ⟨3/5⟩ — 낱개의 수가 아니라 묶음의 수로 나타내요."],"variant_rule":{"alt":[{"stem":"「익힘」 18을 3씩 묶었어요. 9는 18의 얼마인가요?","options":[{"t":"⟨3/6⟩","correct":true},{"t":"⟨3/3⟩","mis":"M3-2-u4-X01"},{"t":"⟨6/3⟩","mis":"M3-2-u4-X03"},{"t":"⟨9/6⟩","mis":"M3-2-u4-X02"}],"explanation":["18을 3씩 묶으면 6묶음 — 전체 묶음의 수 6이 분모예요.","부분은 그중 3묶음 — 부분 묶음의 수 3이 분자예요.","9는 18의 ⟨3/6⟩ — 낱개의 수가 아니라 묶음의 수로 나타내요."]},{"stem":"「익힘」 12를 2씩 묶었어요. 8은 12의 얼마인가요?","options":[{"t":"⟨4/6⟩","correct":true},{"t":"⟨4/2⟩","mis":"M3-2-u4-X01"},{"t":"⟨6/4⟩","mis":"M3-2-u4-X03"},{"t":"⟨8/6⟩","mis":"M3-2-u4-X02"}],"explanation":["12를 2씩 묶으면 6묶음 — 전체 묶음의 수 6이 분모예요.","부분은 그중 4묶음 — 부분 묶음의 수 4가 분자예요.","8은 12의 ⟨4/6⟩ — 낱개의 수가 아니라 묶음의 수로 나타내요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L02_basic#6','math',3,2,'u4','L02','tb_g3_2_math_u4_L02_basic','lesson_basic','M3-2-u4-C2',2,'mc','auto','검은 바둑돌 3개와 흰 바둑돌 4개가 있어요. 검은 바둑돌은 전체 바둑돌의 얼마인가요?',ARRAY['M3-2-u4-X01','M3-2-u4-X03','M3-2-u4-X20']::text[],false,'{"seq":6,"concept":"M3-2-u4-C2","difficulty":2,"kind":"mc","stem":"검은 바둑돌 3개와 흰 바둑돌 4개가 있어요. 검은 바둑돌은 전체 바둑돌의 얼마인가요?","options":[{"t":"⟨3/7⟩","correct":true},{"t":"⟨3/4⟩","mis":"M3-2-u4-X01"},{"t":"⟨7/3⟩","mis":"M3-2-u4-X03"},{"t":"⟨4/7⟩","mis":"M3-2-u4-X20"}],"explanation":["먼저 전체를 정해요 — 바둑돌은 모두 3 + 4 = 7개예요.","검은 바둑돌은 흰 바둑돌과 견주는 것이 아니라 전체 7개와 견주어요.","검은 바둑돌은 전체의 ⟨3/7⟩ — ⟨3/4⟩은 부분끼리 견준 것이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[4,0],[5,0],[5,1],[4,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[1,1],[2,1],[2,2],[1,2]]}],"u":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L02_basic#7','math',3,2,'u4','L02','tb_g3_2_math_u4_L02_basic','lesson_basic','M3-2-u4-C2',2,'mc','auto','와플 4개를 똑같이 2묶음으로 나누었을 때 와플 2개를 1보다 작은 분수 ⟨1/2⟩로 나타낼 수 있는 까닭은 무엇인가요?',ARRAY['M3-2-u4-X26','M3-2-u4-X23','M3-2-u4-X07']::text[],false,'{"seq":7,"concept":"M3-2-u4-C2","difficulty":2,"kind":"mc","stem":"와플 4개를 똑같이 2묶음으로 나누었을 때 와플 2개를 1보다 작은 분수 ⟨1/2⟩로 나타낼 수 있는 까닭은 무엇인가요?","options":[{"t":"전체가 와플 4개이기 때문에","correct":true},{"t":"와플 1개를 반으로 자른 것과 같아서","mis":"M3-2-u4-X26"},{"t":"한 묶음에 와플이 2개씩이라서","mis":"M3-2-u4-X23"},{"t":"묶음이 2개뿐이라서","mis":"M3-2-u4-X07"}],"explanation":["분수는 전체와 부분의 관계를 나타내는 수예요.","전체가 와플 4개이고, 와플 2개는 그중 1묶음이에요.","전체 4개에 비해 부분 2개가 적으니 1보다 작은 ⟨1/2⟩로 나타내요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]]},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]}],"u":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L02_basic#8','math',3,2,'u4','L02','tb_g3_2_math_u4_L02_basic','lesson_basic','M3-2-u4-C1',2,'mc','auto','「익힘」 색칠한 부분이 전체의 ⟨2/4⟩가 아닌 것은 어느 것인가요?',ARRAY['M3-2-u4-X20','M3-2-u4-X23','M3-2-u4-X02']::text[],false,'{"seq":8,"concept":"M3-2-u4-C1","difficulty":2,"kind":"mc","stem":"「익힘」 색칠한 부분이 전체의 ⟨2/4⟩가 아닌 것은 어느 것인가요?","options":[{"t":"구슬 12개를 4개씩 묶은 것 중 2묶음을 색칠한 것","correct":true},{"t":"원을 똑같이 4로 나눈 것 중 2를 색칠한 것","mis":"M3-2-u4-X20"},{"t":"구슬 12개를 3개씩 묶은 것 중 2묶음을 색칠한 것","mis":"M3-2-u4-X23"},{"t":"구슬 8개를 2개씩 묶은 것 중 2묶음을 색칠한 것","mis":"M3-2-u4-X02"}],"explanation":["12개를 4개씩 묶으면 3묶음 — 2묶음은 전체의 ⟨2/3⟩예요.","12개를 3개씩 묶으면 4묶음, 8개를 2개씩 묶으면 4묶음 — 2묶음은 ⟨2/4⟩예요.","전체가 달라도 4묶음 중 2묶음이면 ⟨2/4⟩ — 한 묶음의 개수가 분모가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L02_basic#9','math',3,2,'u4','L02','tb_g3_2_math_u4_L02_basic','lesson_basic','M3-2-u4-C1',2,'ox','auto','「익힘」 동그라미 6개를 똑같이 3묶음으로 나누었어요. 도윤이는 「3묶음으로 나눈 것 중의 2개를 색칠했으니까 색칠한 부분은 전체의 ⟨2/3⟩야.」라고 했어요. 도윤이의 말이 옳은가요?',ARRAY['M3-2-u4-X02']::text[],false,'{"seq":9,"concept":"M3-2-u4-C1","difficulty":2,"kind":"ox","stem":"「익힘」 동그라미 6개를 똑같이 3묶음으로 나누었어요. 도윤이는 「3묶음으로 나눈 것 중의 2개를 색칠했으니까 색칠한 부분은 전체의 ⟨2/3⟩야.」라고 했어요. 도윤이의 말이 옳은가요?","answer":"X","reason_options":[{"t":"전체의 ⟨2/3⟩가 되려면 3묶음 중 2묶음을 색칠해야 해서","correct":true},{"t":"3묶음 중 2개를 색칠했으니까","mis":"M3-2-u4-X02"}],"mis":"M3-2-u4-X02","explanation":["전체 6개를 똑같이 3묶음으로 나누면 한 묶음에 2개예요.","⟨2/3⟩는 3묶음 중 2묶음 — 4개를 색칠해야 해요.","도윤이는 2묶음이 아니라 2개만 색칠했어요 — 옳지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L02_basic#10','math',3,2,'u4','L02','tb_g3_2_math_u4_L02_basic','lesson_basic','M3-2-u4-C2',3,'mc','auto','8을 2씩 묶으면 4는 8의 ⟨2/4⟩이고, 8을 4씩 묶으면 4는 8의 ⟨1/2⟩이에요. 같은 4인데 분수가 다르게 나온 까닭은 무엇인가요?',ARRAY['M3-2-u4-X02','M3-2-u4-X22','M3-2-u4-X20']::text[],false,'{"seq":10,"concept":"M3-2-u4-C2","difficulty":3,"kind":"mc","stem":"8을 2씩 묶으면 4는 8의 ⟨2/4⟩이고, 8을 4씩 묶으면 4는 8의 ⟨1/2⟩이에요. 같은 4인데 분수가 다르게 나온 까닭은 무엇인가요?","options":[{"t":"묶는 방법이 달라 전체 묶음의 수가 달라져서","correct":true},{"t":"전체의 개수가 달라져서","mis":"M3-2-u4-X02"},{"t":"둘 중 하나는 잘못 나타낸 것이라서","mis":"M3-2-u4-X22"},{"t":"4는 8의 절반이 아니라서","mis":"M3-2-u4-X20"}],"explanation":["전체는 똑같이 8이에요.","2씩 묶으면 4묶음 중 2묶음, 4씩 묶으면 2묶음 중 1묶음이에요.","묶는 방법이 달라지면 분모와 분자가 달라져요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]],"hi":true},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]]},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]},{"p":[[2.7,1],[3.7,1],[3.7,2],[2.7,2]]},{"p":[[3.7,1],[4.7,1],[4.7,2],[3.7,2]]}],"u":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L02_challenge#1','math',3,2,'u4','L02','tb_g3_2_math_u4_L02_challenge','lesson_challenge','M3-2-u4-C1',2,'sa','auto','「익힘」 사과 12개를 2개씩 묶었어요. 8은 12의 ⟨□/6⟩일 때 □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u4-C1","difficulty":2,"kind":"sa","stem":"「익힘」 사과 12개를 2개씩 묶었어요. 8은 12의 ⟨□/6⟩일 때 □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["12를 2씩 묶으면 6묶음 — 분모 6이에요.","8은 2씩 4묶음이에요.","8은 12의 ⟨4/6⟩ — □는 4예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]],"hi":true},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]],"hi":true},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]],"hi":true},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]],"hi":true},{"p":[[10.8,0],[11.8,0],[11.8,1],[10.8,1]]},{"p":[[11.8,0],[12.8,0],[12.8,1],[11.8,1]]},{"p":[[13.5,0],[14.5,0],[14.5,1],[13.5,1]]},{"p":[[14.5,0],[15.5,0],[15.5,1],[14.5,1]]}],"u":19},"variant_rule":{"alt":[{"stem":"「익힘」 18을 3씩 묶었어요. 9는 18의 ⟨□/6⟩일 때 □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["18을 3씩 묶으면 6묶음 — 분모 6이에요.","9는 3씩 3묶음이에요.","9는 18의 ⟨3/6⟩ — □는 3이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[4.7,0],[5.7,0],[5.7,1],[4.7,1]],"hi":true},{"p":[[5.7,0],[6.7,0],[6.7,1],[5.7,1]],"hi":true},{"p":[[7.4,0],[8.4,0],[8.4,1],[7.4,1]],"hi":true},{"p":[[8.4,0],[9.4,0],[9.4,1],[8.4,1]],"hi":true},{"p":[[9.4,0],[10.4,0],[10.4,1],[9.4,1]],"hi":true},{"p":[[11.1,0],[12.1,0],[12.1,1],[11.1,1]]},{"p":[[12.1,0],[13.1,0],[13.1,1],[12.1,1]]},{"p":[[13.1,0],[14.1,0],[14.1,1],[13.1,1]]},{"p":[[14.8,0],[15.8,0],[15.8,1],[14.8,1]]},{"p":[[15.8,0],[16.8,0],[16.8,1],[15.8,1]]},{"p":[[16.8,0],[17.8,0],[17.8,1],[16.8,1]]},{"p":[[18.5,0],[19.5,0],[19.5,1],[18.5,1]]},{"p":[[19.5,0],[20.5,0],[20.5,1],[19.5,1]]},{"p":[[20.5,0],[21.5,0],[21.5,1],[20.5,1]]}],"u":13}},{"stem":"「확인 문제」 딸기 16개를 4개씩 묶었어요. 12는 16의 ⟨□/4⟩일 때 □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["16을 4씩 묶으면 4묶음 — 분모 4예요.","12는 4씩 3묶음이에요.","12는 16의 ⟨3/4⟩ — □는 3이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]],"hi":true},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[2.7,1],[3.7,1],[3.7,2],[2.7,2]],"hi":true},{"p":[[3.7,1],[4.7,1],[4.7,2],[3.7,2]],"hi":true},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]],"hi":true},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]],"hi":true},{"p":[[5.4,1],[6.4,1],[6.4,2],[5.4,2]],"hi":true},{"p":[[6.4,1],[7.4,1],[7.4,2],[6.4,2]],"hi":true},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]]},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]]},{"p":[[8.1,1],[9.1,1],[9.1,2],[8.1,2]]},{"p":[[9.1,1],[10.1,1],[10.1,2],[9.1,2]]}],"u":29}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L02_challenge#2','math',3,2,'u4','L02','tb_g3_2_math_u4_L02_challenge','lesson_challenge','M3-2-u4-C1',2,'mc','auto','「익힘」 네모 10개를 똑같이 5묶음으로 나누었어요. 전체의 ⟨3/5⟩만큼 색칠하려면 네모를 몇 개 색칠해야 하나요?',ARRAY['M3-2-u4-X04','M3-2-u4-X05','M3-2-u4-X06']::text[],false,'{"seq":2,"concept":"M3-2-u4-C1","difficulty":2,"kind":"mc","stem":"「익힘」 네모 10개를 똑같이 5묶음으로 나누었어요. 전체의 ⟨3/5⟩만큼 색칠하려면 네모를 몇 개 색칠해야 하나요?","options":[{"t":"6개","correct":true},{"t":"3개","mis":"M3-2-u4-X04"},{"t":"2개","mis":"M3-2-u4-X05"},{"t":"5개","mis":"M3-2-u4-X06"}],"explanation":["10개를 똑같이 5묶음으로 나누면 한 묶음에 2개예요.","⟨3/5⟩은 5묶음 중 3묶음이에요.","2개씩 3묶음 — 6개를 색칠해요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]]},{"p":[[1,0],[2,0],[2,1],[1,1]]},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]]},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]]},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]]},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]]},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]]},{"p":[[10.8,0],[11.8,0],[11.8,1],[10.8,1]]},{"p":[[11.8,0],[12.8,0],[12.8,1],[11.8,1]]}],"u":23}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L02_challenge#3','math',3,2,'u4','L02','tb_g3_2_math_u4_L02_challenge','lesson_challenge','M3-2-u4-C2',3,'error','auto','삼각형 4개 중 1개를 색칠한 그림을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u4-X01','M3-2-u4-X20']::text[],true,'{"seq":3,"concept":"M3-2-u4-C2","difficulty":3,"kind":"error","stem":"삼각형 4개 중 1개를 색칠한 그림을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"건우 — 「색칠한 것 1개와 색칠하지 않은 것 3개를 견주어 ⟨1/3⟩이야」","correct":true,"mis_target":"M3-2-u4-X01"},{"t":"채원 — 「전체 4개를 똑같이 4묶음으로 나눈 것 중 1묶음이야」","mis":"M3-2-u4-X20"},{"t":"지유 — 「색칠한 부분은 전체의 ⟨1/4⟩이야」","mis":"M3-2-u4-X20"}],"explanation":["전체는 삼각형 4개 — 1개씩 묶으면 4묶음이에요.","색칠한 부분은 4묶음 중 1묶음이라 전체의 ⟨1/4⟩이에요.","건우는 전체가 아니라 색칠하지 않은 부분과 견주었어요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1.7,0],[2.7,0],[2.7,1],[1.7,1]]},{"p":[[3.4,0],[4.4,0],[4.4,1],[3.4,1]]},{"p":[[5.1,0],[6.1,0],[6.1,1],[5.1,1]]}],"u":30},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 삼각형 4개 중 1개를 색칠한 그림을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「분모와 분자를 거꾸로 써서 ⟨4/1⟩야」","correct":true,"mis_target":"M3-2-u4-X03"},{"t":"서준 — 「전체 묶음의 수 4가 분모야」","mis":"M3-2-u4-X20"},{"t":"은비 — 「색칠한 부분 묶음의 수 1이 분자야」","mis":"M3-2-u4-X20"}],"explanation":["전체 묶음의 수가 분모, 색칠한 부분 묶음의 수가 분자예요.","분모 4, 분자 1 — 전체의 ⟨1/4⟩이에요.","도윤이는 분모와 분자를 바꾸어 썼어요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1.7,0],[2.7,0],[2.7,1],[1.7,1]]},{"p":[[3.4,0],[4.4,0],[4.4,1],[3.4,1]]},{"p":[[5.1,0],[6.1,0],[6.1,1],[5.1,1]]}],"u":30}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L02_challenge#4','math',3,2,'u4','L02','tb_g3_2_math_u4_L02_challenge','lesson_challenge','M3-2-u4-C1',3,'mc','auto','「확인 문제」 딸기 16개를 4개씩 묶었더니 색칠한 딸기가 12개였어요. 12는 16의 얼마인가요?',ARRAY['M3-2-u4-X03','M3-2-u4-X02']::text[],false,'{"seq":4,"concept":"M3-2-u4-C1","difficulty":3,"kind":"mc","stem":"「확인 문제」 딸기 16개를 4개씩 묶었더니 색칠한 딸기가 12개였어요. 12는 16의 얼마인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨4/3⟩","mis":"M3-2-u4-X03"},{"t":"⟨12/4⟩","mis":"M3-2-u4-X02"},{"t":"⟨3/16⟩","mis":"M3-2-u4-X02"}],"explanation":["16을 4씩 묶으면 4묶음 — 전체 묶음의 수 4가 분모예요.","부분은 그중 3묶음 — 부분 묶음의 수 3이 분자예요.","12는 16의 ⟨3/4⟩ — 낱개의 수가 아니라 묶음의 수로 나타내요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]],"hi":true},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[2.7,1],[3.7,1],[3.7,2],[2.7,2]],"hi":true},{"p":[[3.7,1],[4.7,1],[4.7,2],[3.7,2]],"hi":true},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]],"hi":true},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]],"hi":true},{"p":[[5.4,1],[6.4,1],[6.4,2],[5.4,2]],"hi":true},{"p":[[6.4,1],[7.4,1],[7.4,2],[6.4,2]],"hi":true},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]]},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]]},{"p":[[8.1,1],[9.1,1],[9.1,2],[8.1,2]]},{"p":[[9.1,1],[10.1,1],[10.1,2],[9.1,2]]}],"u":29}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L02_challenge#5','math',3,2,'u4','L02','tb_g3_2_math_u4_L02_challenge','lesson_challenge','M3-2-u4-C2',3,'mc','auto','8개를 똑같이 2묶음으로 나누는 바른 방법은 무엇인가요?',ARRAY['M3-2-u4-X23','M3-2-u4-X26','M3-2-u4-X21']::text[],false,'{"seq":5,"concept":"M3-2-u4-C2","difficulty":3,"kind":"mc","stem":"8개를 똑같이 2묶음으로 나누는 바른 방법은 무엇인가요?","options":[{"t":"한 묶음에 4개씩 2묶음으로 나눈다","correct":true},{"t":"한 묶음에 2개씩 4묶음으로 나눈다","mis":"M3-2-u4-X23"},{"t":"8개를 하나씩 똑같이 반으로 자른다","mis":"M3-2-u4-X26"},{"t":"한 묶음에 2개씩 2묶음만 만든다","mis":"M3-2-u4-X21"}],"explanation":["「똑같이 2묶음」은 묶음의 수가 2개라는 뜻이에요.","8개를 2묶음에 똑같이 나누면 한 묶음에 4개예요.","2개씩 묶으면 4묶음이 되어 「2묶음으로 나누기」가 아니에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]]},{"p":[[1,0],[2,0],[2,1],[1,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[1,1],[2,1],[2,2],[1,2]]},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]]},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]},{"p":[[2.7,1],[3.7,1],[3.7,2],[2.7,2]]},{"p":[[3.7,1],[4.7,1],[4.7,2],[3.7,2]]}],"u":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L02_challenge#6','math',3,2,'u4','L02','tb_g3_2_math_u4_L02_challenge','lesson_challenge','M3-2-u4-C2',3,'mc','auto','공 12개를 똑같이 4묶음으로 나누었어요. 한 묶음에 공은 몇 개이고, 2묶음은 전체의 얼마인가요?',ARRAY['M3-2-u4-X23','M3-2-u4-X01','M3-2-u4-X03']::text[],false,'{"seq":6,"concept":"M3-2-u4-C2","difficulty":3,"kind":"mc","stem":"공 12개를 똑같이 4묶음으로 나누었어요. 한 묶음에 공은 몇 개이고, 2묶음은 전체의 얼마인가요?","options":[{"t":"3개, ⟨2/4⟩","correct":true},{"t":"4개, ⟨2/3⟩","mis":"M3-2-u4-X23"},{"t":"3개, ⟨2/2⟩","mis":"M3-2-u4-X01"},{"t":"3개, ⟨4/2⟩","mis":"M3-2-u4-X03"}],"explanation":["12개를 4묶음으로 똑같이 나누면 한 묶음에 3개예요 — 12 ÷ 4 = 3.","1묶음은 전체의 ⟨1/4⟩, 2묶음은 전체의 ⟨2/4⟩예요.","4개씩 묶으면 3묶음이 되어 다른 분수가 돼요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[4.7,0],[5.7,0],[5.7,1],[4.7,1]],"hi":true},{"p":[[5.7,0],[6.7,0],[6.7,1],[5.7,1]],"hi":true},{"p":[[7.4,0],[8.4,0],[8.4,1],[7.4,1]]},{"p":[[8.4,0],[9.4,0],[9.4,1],[8.4,1]]},{"p":[[9.4,0],[10.4,0],[10.4,1],[9.4,1]]},{"p":[[11.1,0],[12.1,0],[12.1,1],[11.1,1]]},{"p":[[12.1,0],[13.1,0],[13.1,1],[12.1,1]]},{"p":[[13.1,0],[14.1,0],[14.1,1],[13.1,1]]}],"u":21}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L02_challenge#7','math',3,2,'u4','L02','tb_g3_2_math_u4_L02_challenge','lesson_challenge','M3-2-u4-C1',3,'sa','auto','「익힘」 12를 몇씩 묶었더니 2는 12의 ⟨1/6⟩이었어요. 몇씩 묶었나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u4-C1","difficulty":3,"kind":"sa","stem":"「익힘」 12를 몇씩 묶었더니 2는 12의 ⟨1/6⟩이었어요. 몇씩 묶었나요? 숫자로 쓰세요.","answer":["2"],"explanation":["분모 6 — 12를 6묶음으로 나누었어요.","한 묶음은 12 ÷ 6 = 2예요.","2는 1묶음 — 2씩 묶었어요."],"variant_rule":{"alt":[{"stem":"15를 몇씩 묶었더니 9는 15의 ⟨3/5⟩이었어요. 몇씩 묶었나요? 숫자로 쓰세요.","answer":["3"],"explanation":["분모 5 — 15를 5묶음으로 나누었어요.","한 묶음은 15 ÷ 5 = 3이에요.","9는 3씩 3묶음 — 3씩 묶었어요."]},{"stem":"8을 몇씩 묶었더니 6은 8의 ⟨6/8⟩이었어요. 몇씩 묶었나요? 숫자로 쓰세요.","answer":["1"],"explanation":["분모 8 — 8을 8묶음으로 나누었어요.","한 묶음은 8 ÷ 8 = 1이에요.","6은 1씩 6묶음 — 1씩 묶었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L02_challenge#8','math',3,2,'u4','L02','tb_g3_2_math_u4_L02_challenge','lesson_challenge','M3-2-u4-C2',4,'essay','teacher','검은 바둑돌 3개와 흰 바둑돌 4개가 있어요. 친구가 「검은 바둑돌은 ⟨3/4⟩이야.」라고 했어요. 검은 바둑돌은 전체의 얼마인지 쓰고, 친구의 생각에서 무엇이 잘못되었는지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u4-C2","difficulty":4,"kind":"essay","stem":"검은 바둑돌 3개와 흰 바둑돌 4개가 있어요. 친구가 「검은 바둑돌은 ⟨3/4⟩이야.」라고 했어요. 검은 바둑돌은 전체의 얼마인지 쓰고, 친구의 생각에서 무엇이 잘못되었는지 설명해 보세요.","answer_guide":{"answer":"예: 검은 바둑돌은 전체 7개 중 3개이므로 전체의 ⟨3/7⟩이다. 친구는 전체가 아니라 흰 바둑돌과 견주었다. 분수로 나타낼 때는 먼저 전체가 무엇인지 정하고 부분을 전체와 견주어야 한다.","scoring_points":["⟨3/7⟩이라고 답했는가","흰 바둑돌과 견준 것이 잘못이라고 썼는가","전체를 먼저 정해 전체와 견주어야 한다고 썼는가"]},"explanation":["바둑돌은 모두 7개예요.","검은 바둑돌 3개 → 전체의 ⟨3/7⟩이에요.","부분끼리 견주지 않아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[4,0],[5,0],[5,1],[4,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[1,1],[2,1],[2,2],[1,2]]}],"u":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L02_challenge#9','math',3,2,'u4','L02','tb_g3_2_math_u4_L02_challenge','lesson_challenge','M3-2-u4-C2',4,'essay','teacher','8을 2씩 묶을 때와 4씩 묶을 때, 4는 각각 8의 얼마인지 분수로 쓰고 왜 분수가 다르게 나오는지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u4-C2","difficulty":4,"kind":"essay","stem":"8을 2씩 묶을 때와 4씩 묶을 때, 4는 각각 8의 얼마인지 분수로 쓰고 왜 분수가 다르게 나오는지 설명해 보세요.","answer_guide":{"answer":"예: 2씩 묶으면 4묶음 중 2묶음이라 4는 8의 ⟨2/4⟩이고, 4씩 묶으면 2묶음 중 1묶음이라 4는 8의 ⟨1/2⟩이다. 같은 4라도 묶는 방법이 달라지면 전체 묶음의 수(분모)와 부분 묶음의 수(분자)가 달라지기 때문이다.","scoring_points":["2씩 묶을 때 ⟨2/4⟩를 썼는가","4씩 묶을 때 ⟨1/2⟩을 썼는가","묶는 방법에 따라 묶음의 수가 달라진다고 설명했는가"]},"explanation":["2씩 → 4묶음 중 2묶음이에요.","4씩 → 2묶음 중 1묶음이에요.","묶는 방법이 다르면 분수도 달라요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]]},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]]},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]]},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]]}],"u":29}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L02_challenge#10','math',3,2,'u4','L02','tb_g3_2_math_u4_L02_challenge','lesson_challenge','M3-2-u4-C1',4,'sa','auto','어떤 수를 3씩 묶었더니 9는 전체의 ⟨3/5⟩이었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-2-u4-C1","difficulty":4,"kind":"sa","stem":"어떤 수를 3씩 묶었더니 9는 전체의 ⟨3/5⟩이었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["9는 3씩 3묶음 — 분자 3이에요.","분모 5 — 전체는 5묶음이에요.","3씩 5묶음 = 3 × 5 = 15예요."],"variant_rule":{"alt":[{"stem":"어떤 수를 3씩 묶었더니 9는 전체의 ⟨3/6⟩이었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["9는 3씩 3묶음 — 분자 3이에요.","분모 6 — 전체는 6묶음이에요.","3씩 6묶음 = 3 × 6 = 18이에요."]},{"stem":"어떤 수를 4씩 묶었더니 12는 전체의 ⟨3/4⟩이었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["12는 4씩 3묶음 — 분자 3이에요.","분모 4 — 전체는 4묶음이에요.","4씩 4묶음 = 4 × 4 = 16이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L03_basic#1','math',3,2,'u4','L03','tb_g3_2_math_u4_L03_basic','lesson_basic','M3-2-u4-C3',1,'sa','auto','지유와 도윤이가 교실에 풍선 8개를 붙여 꾸미려고 해요. 풍선 8개의 ⟨1/2⟩만큼을 분홍색 풍선으로 꾸민다면 분홍색 풍선은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u4-C3","difficulty":1,"kind":"sa","stem":"지유와 도윤이가 교실에 풍선 8개를 붙여 꾸미려고 해요. 풍선 8개의 ⟨1/2⟩만큼을 분홍색 풍선으로 꾸민다면 분홍색 풍선은 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["8을 똑같이 2묶음으로 나누면 한 묶음이 4예요 — 8 ÷ 2 = 4.","⟨1/2⟩은 그중 1묶음이에요.","8의 ⟨1/2⟩만큼은 4예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]],"hi":true},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]]},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]},{"p":[[2.7,1],[3.7,1],[3.7,2],[2.7,2]]},{"p":[[3.7,1],[4.7,1],[4.7,2],[3.7,2]]}],"u":30},"variant_rule":{"alt":[{"stem":"「익힘」 풍선 6개의 ⟨1/2⟩만큼은 노란색 풍선으로 꾸몄어요. 노란색 풍선은 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["6을 똑같이 2묶음으로 나누면 한 묶음이 3이에요 — 6 ÷ 2 = 3.","⟨1/2⟩은 그중 1묶음이에요.","6의 ⟨1/2⟩만큼은 3이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]},{"p":[[4.7,0],[5.7,0],[5.7,1],[4.7,1]]},{"p":[[5.7,0],[6.7,0],[6.7,1],[5.7,1]]}],"u":30}},{"stem":"「익힘」 지우개 9개를 똑같이 3묶음으로 나누었어요. 9의 ⟨1/3⟩은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["9를 똑같이 3묶음으로 나누면 한 묶음이 3이에요 — 9 ÷ 3 = 3.","⟨1/3⟩은 그중 1묶음이에요.","9의 ⟨1/3⟩만큼은 3이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]},{"p":[[4.7,0],[5.7,0],[5.7,1],[4.7,1]]},{"p":[[5.7,0],[6.7,0],[6.7,1],[5.7,1]]},{"p":[[7.4,0],[8.4,0],[8.4,1],[7.4,1]]},{"p":[[8.4,0],[9.4,0],[9.4,1],[8.4,1]]},{"p":[[9.4,0],[10.4,0],[10.4,1],[9.4,1]]}],"u":28}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L03_basic#2','math',3,2,'u4','L03','tb_g3_2_math_u4_L03_basic','lesson_basic','M3-2-u4-C3',1,'sa','auto','10을 똑같이 5묶음으로 나누었어요. 10의 ⟨1/5⟩은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u4-C3","difficulty":1,"kind":"sa","stem":"10을 똑같이 5묶음으로 나누었어요. 10의 ⟨1/5⟩은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["10을 똑같이 5묶음으로 나누면 한 묶음이 2예요 — 10 ÷ 5 = 2.","⟨1/5⟩은 그중 1묶음이에요.","10의 ⟨1/5⟩만큼은 2예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]]},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]]},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]]},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]]},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]]},{"p":[[10.8,0],[11.8,0],[11.8,1],[10.8,1]]},{"p":[[11.8,0],[12.8,0],[12.8,1],[11.8,1]]}],"u":23},"variant_rule":{"alt":[{"stem":"쿠키 6개를 똑같이 6묶음으로 나누었어요. 6의 ⟨1/6⟩은 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["6을 똑같이 6묶음으로 나누면 한 묶음이 1이에요 — 6 ÷ 6 = 1.","⟨1/6⟩은 그중 1묶음이에요.","6의 ⟨1/6⟩만큼은 1이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1.7,0],[2.7,0],[2.7,1],[1.7,1]]},{"p":[[3.4,0],[4.4,0],[4.4,1],[3.4,1]]},{"p":[[5.1,0],[6.1,0],[6.1,1],[5.1,1]]},{"p":[[6.8,0],[7.8,0],[7.8,1],[6.8,1]]},{"p":[[8.5,0],[9.5,0],[9.5,1],[8.5,1]]}],"u":30}},{"stem":"사탕 12개를 똑같이 3묶음으로 나누었어요. 12의 ⟨1/3⟩은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["12를 똑같이 3묶음으로 나누면 한 묶음이 4예요 — 12 ÷ 3 = 4.","⟨1/3⟩은 그중 1묶음이에요.","12의 ⟨1/3⟩만큼은 4예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]],"hi":true},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]]},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]},{"p":[[2.7,1],[3.7,1],[3.7,2],[2.7,2]]},{"p":[[3.7,1],[4.7,1],[4.7,2],[3.7,2]]},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]]},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]]},{"p":[[5.4,1],[6.4,1],[6.4,2],[5.4,2]]},{"p":[[6.4,1],[7.4,1],[7.4,2],[6.4,2]]}],"u":30}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L03_basic#3','math',3,2,'u4','L03','tb_g3_2_math_u4_L03_basic','lesson_basic','M3-2-u4-C3',1,'sa','auto','10의 ⟨1/5⟩이 2인 것을 이용하여 10의 ⟨3/5⟩을 구해 보세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u4-C3","difficulty":1,"kind":"sa","stem":"10의 ⟨1/5⟩이 2인 것을 이용하여 10의 ⟨3/5⟩을 구해 보세요. 숫자로 쓰세요.","answer":["6"],"explanation":["10을 똑같이 5묶음으로 나누면 한 묶음이 2예요 — 10 ÷ 5 = 2.","⟨3/5⟩은 ⟨1/5⟩이 3개 — 3묶음이에요.","10의 ⟨3/5⟩만큼은 6이에요. 분자 3만 보고 답하지 않아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]],"hi":true},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]],"hi":true},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]]},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]]},{"p":[[10.8,0],[11.8,0],[11.8,1],[10.8,1]]},{"p":[[11.8,0],[12.8,0],[12.8,1],[11.8,1]]}],"u":23},"variant_rule":{"alt":[{"stem":"6의 ⟨1/6⟩이 1인 것을 이용하여 6의 ⟨4/6⟩를 구해 보세요. 숫자로 쓰세요.","answer":["4"],"explanation":["6을 똑같이 6묶음으로 나누면 한 묶음이 1이에요 — 6 ÷ 6 = 1.","⟨4/6⟩는 ⟨1/6⟩이 4개 — 4묶음이에요.","6의 ⟨4/6⟩만큼은 4예요. 분자 4만 보고 답하지 않아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1.7,0],[2.7,0],[2.7,1],[1.7,1]],"hi":true},{"p":[[3.4,0],[4.4,0],[4.4,1],[3.4,1]],"hi":true},{"p":[[5.1,0],[6.1,0],[6.1,1],[5.1,1]],"hi":true},{"p":[[6.8,0],[7.8,0],[7.8,1],[6.8,1]]},{"p":[[8.5,0],[9.5,0],[9.5,1],[8.5,1]]}],"u":30}},{"stem":"12의 ⟨1/3⟩이 4인 것을 이용하여 12의 ⟨2/3⟩를 구해 보세요. 숫자로 쓰세요.","answer":["8"],"explanation":["12를 똑같이 3묶음으로 나누면 한 묶음이 4예요 — 12 ÷ 3 = 4.","⟨2/3⟩는 ⟨1/3⟩이 2개 — 2묶음이에요.","12의 ⟨2/3⟩만큼은 8이에요. 분자 2만 보고 답하지 않아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]],"hi":true},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[2.7,1],[3.7,1],[3.7,2],[2.7,2]],"hi":true},{"p":[[3.7,1],[4.7,1],[4.7,2],[3.7,2]],"hi":true},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]]},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]]},{"p":[[5.4,1],[6.4,1],[6.4,2],[5.4,2]]},{"p":[[6.4,1],[7.4,1],[7.4,2],[6.4,2]]}],"u":30}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L03_basic#4','math',3,2,'u4','L03','tb_g3_2_math_u4_L03_basic','lesson_basic','M3-2-u4-C3',1,'blank','auto','「확인 문제」 8의 ⟨1/4⟩은 전체 8개를 똑같이 □묶음으로 나눈 것 중의 1묶음이에요. □에 알맞은 수는 무엇인가요?',ARRAY['M3-2-u4-X23','M3-2-u4-X02','M3-2-u4-X04']::text[],true,'{"seq":4,"concept":"M3-2-u4-C3","difficulty":1,"kind":"blank","stem":"「확인 문제」 8의 ⟨1/4⟩은 전체 8개를 똑같이 □묶음으로 나눈 것 중의 1묶음이에요. □에 알맞은 수는 무엇인가요?","options":[{"t":"4","correct":true},{"t":"2","mis":"M3-2-u4-X23"},{"t":"8","mis":"M3-2-u4-X02"},{"t":"1","mis":"M3-2-u4-X04"}],"explanation":["분모 4는 「똑같이 4묶음으로 나눈다」는 뜻이에요.","8개를 4묶음으로 나누면 한 묶음에 2개예요.","그래서 8의 ⟨1/4⟩은 2 — □는 4예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]]},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]]},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]]},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]]},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]]}],"u":29},"variant_rule":{"alt":[{"stem":"「익힘」 12의 ⟨1/6⟩은 전체 12개를 똑같이 □묶음으로 나눈 것 중의 1묶음이에요. □에 알맞은 수는 무엇인가요?","options":[{"t":"6","correct":true},{"t":"2","mis":"M3-2-u4-X23"},{"t":"12","mis":"M3-2-u4-X02"},{"t":"1","mis":"M3-2-u4-X04"}],"explanation":["분모 6은 「똑같이 6묶음으로 나눈다」는 뜻이에요.","12개를 6묶음으로 나누면 한 묶음에 2개예요.","그래서 12의 ⟨1/6⟩은 2 — □는 6이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]]},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]]},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]]},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]]},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]]},{"p":[[10.8,0],[11.8,0],[11.8,1],[10.8,1]]},{"p":[[11.8,0],[12.8,0],[12.8,1],[11.8,1]]},{"p":[[13.5,0],[14.5,0],[14.5