INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L03_basic#5','math',3,2,'u4','L03','tb_g3_2_math_u4_L03_basic','lesson_basic','M3-2-u4-C3',2,'mc','auto','「익힘」 은비는 약과 12개의 ⟨1/4⟩만큼을 먹었어요. 은비가 먹은 약과는 몇 개인가요?',ARRAY['M3-2-u4-X04','M3-2-u4-X23','M3-2-u4-X20']::text[],true,'{"seq":5,"concept":"M3-2-u4-C3","difficulty":2,"kind":"mc","stem":"「익힘」 은비는 약과 12개의 ⟨1/4⟩만큼을 먹었어요. 은비가 먹은 약과는 몇 개인가요?","options":[{"t":"3개","correct":true},{"t":"1개","mis":"M3-2-u4-X04"},{"t":"4개","mis":"M3-2-u4-X23"},{"t":"9개","mis":"M3-2-u4-X20"}],"explanation":["12개를 똑같이 4묶음으로 나누면 한 묶음이 3개예요 — 12 ÷ 4 = 3.","⟨1/4⟩은 그중 1묶음이에요.","12개의 ⟨1/4⟩만큼은 3개예요."],"variant_rule":{"alt":[{"stem":"「익힘」 건우는 약과 12개의 ⟨2/4⟩만큼을 먹었어요. 건우가 먹은 약과는 몇 개인가요?","options":[{"t":"6개","correct":true},{"t":"2개","mis":"M3-2-u4-X04"},{"t":"3개","mis":"M3-2-u4-X05"},{"t":"8개","mis":"M3-2-u4-X23"}],"explanation":["12개를 똑같이 4묶음으로 나누면 한 묶음이 3개예요 — 12 ÷ 4 = 3.","⟨2/4⟩는 ⟨1/4⟩이 2개 — 2묶음이에요.","12개의 ⟨2/4⟩만큼은 6개예요. 분자 2만 보고 답하지 않아요."]},{"stem":"사탕 12개의 ⟨2/3⟩만큼은 몇 개인가요?","options":[{"t":"8개","correct":true},{"t":"2개","mis":"M3-2-u4-X04"},{"t":"4개","mis":"M3-2-u4-X05"},{"t":"6개","mis":"M3-2-u4-X23"}],"explanation":["12개를 똑같이 3묶음으로 나누면 한 묶음이 4개예요 — 12 ÷ 3 = 4.","⟨2/3⟩는 ⟨1/3⟩이 2개 — 2묶음이에요.","12개의 ⟨2/3⟩만큼은 8개예요. 분자 2만 보고 답하지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L03_basic#6','math',3,2,'u4','L03','tb_g3_2_math_u4_L03_basic','lesson_basic','M3-2-u4-C3',2,'sa','auto','「확인 문제」 18의 ⟨2/3⟩는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u4-C3","difficulty":2,"kind":"sa","stem":"「확인 문제」 18의 ⟨2/3⟩는 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["18을 똑같이 3묶음으로 나누면 한 묶음이 6이에요 — 18 ÷ 3 = 6.","⟨2/3⟩는 ⟨1/3⟩이 2개 — 2묶음이에요.","18의 ⟨2/3⟩만큼은 12예요. 분자 2만 보고 답하지 않아요."],"variant_rule":{"alt":[{"stem":"「익힘」 별 12개를 똑같이 6묶음으로 나누었어요. 12의 ⟨3/6⟩은 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["12를 똑같이 6묶음으로 나누면 한 묶음이 2예요 — 12 ÷ 6 = 2.","⟨3/6⟩은 ⟨1/6⟩이 3개 — 3묶음이에요.","12의 ⟨3/6⟩만큼은 6이에요. 분자 3만 보고 답하지 않아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]],"hi":true},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]],"hi":true},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]]},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]]},{"p":[[10.8,0],[11.8,0],[11.8,1],[10.8,1]]},{"p":[[11.8,0],[12.8,0],[12.8,1],[11.8,1]]},{"p":[[13.5,0],[14.5,0],[14.5,1],[13.5,1]]},{"p":[[14.5,0],[15.5,0],[15.5,1],[14.5,1]]}],"u":19}},{"stem":"「확인 문제」 18의 ⟨1/3⟩은 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["18을 똑같이 3묶음으로 나누면 한 묶음이 6이에요 — 18 ÷ 3 = 6.","⟨1/3⟩은 그중 1묶음이에요.","18의 ⟨1/3⟩만큼은 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L03_basic#7','math',3,2,'u4','L03','tb_g3_2_math_u4_L03_basic','lesson_basic','M3-2-u4-C3',2,'ox','auto','도윤이는 「12의 ⟨1/3⟩은 3이고, 12의 ⟨2/3⟩는 6이야.」라고 했어요. 도윤이의 말이 옳은가요?',ARRAY['M3-2-u4-X23']::text[],true,'{"seq":7,"concept":"M3-2-u4-C3","difficulty":2,"kind":"ox","stem":"도윤이는 「12의 ⟨1/3⟩은 3이고, 12의 ⟨2/3⟩는 6이야.」라고 했어요. 도윤이의 말이 옳은가요?","answer":"X","reason_options":[{"t":"12를 똑같이 3묶음으로 나누면 한 묶음이 4라서","correct":true},{"t":"분모 3만큼씩 묶으면 되니까","mis":"M3-2-u4-X23"}],"mis":"M3-2-u4-X23","explanation":["12의 ⟨1/3⟩은 12를 똑같이 3묶음으로 나눈 것 중의 1묶음 — 4예요.","12의 ⟨2/3⟩는 4가 2묶음 — 8이에요.","도윤이는 3개씩 묶어 분모를 한 묶음의 개수로 보았어요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]],"hi":true},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]]},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]},{"p":[[2.7,1],[3.7,1],[3.7,2],[2.7,2]]},{"p":[[3.7,1],[4.7,1],[4.7,2],[3.7,2]]},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]]},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]]},{"p":[[5.4,1],[6.4,1],[6.4,2],[5.4,2]]},{"p":[[6.4,1],[7.4,1],[7.4,2],[6.4,2]]}],"u":30},"variant_rule":{"alt":[{"stem":"건우는 「도토리 12개의 ⟨3/4⟩만큼은 3개야.」라고 했어요. 건우의 말이 옳은가요?","answer":"X","reason_options":[{"t":"12를 똑같이 4묶음으로 나누면 3묶음이 9개라서","correct":true},{"t":"분자가 3이니까","mis":"M3-2-u4-X04"}],"explanation":["도토리 12개를 똑같이 4묶음으로 나누면 한 묶음에 3개예요.","⟨3/4⟩은 4묶음 중 3묶음 — 3개씩 3묶음이에요.","도토리 12개의 ⟨3/4⟩만큼은 9개 — 분자만 보고 답하면 안 돼요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[4.7,0],[5.7,0],[5.7,1],[4.7,1]],"hi":true},{"p":[[5.7,0],[6.7,0],[6.7,1],[5.7,1]],"hi":true},{"p":[[7.4,0],[8.4,0],[8.4,1],[7.4,1]],"hi":true},{"p":[[8.4,0],[9.4,0],[9.4,1],[8.4,1]],"hi":true},{"p":[[9.4,0],[10.4,0],[10.4,1],[9.4,1]],"hi":true},{"p":[[11.1,0],[12.1,0],[12.1,1],[11.1,1]]},{"p":[[12.1,0],[13.1,0],[13.1,1],[12.1,1]]},{"p":[[13.1,0],[14.1,0],[14.1,1],[13.1,1]]}],"u":21}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L03_basic#8','math',3,2,'u4','L03','tb_g3_2_math_u4_L03_basic','lesson_basic','M3-2-u4-C3',2,'mc','auto','전체의 분수만큼은 얼마인지 구하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['M3-2-u4-X06','M3-2-u4-X23','M3-2-u4-X04']::text[],false,'{"seq":8,"concept":"M3-2-u4-C3","difficulty":2,"kind":"mc","stem":"전체의 분수만큼은 얼마인지 구하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"전체를 똑같이 분모만큼의 묶음으로 나누고 그중 분자만큼의 묶음에 해당하는 수를 구한다","correct":true},{"t":"전체를 똑같이 분자만큼의 묶음으로 나누고 그중 분모만큼의 묶음을 센다","mis":"M3-2-u4-X06"},{"t":"분모의 수만큼씩 묶어서 분자만큼의 묶음을 센다","mis":"M3-2-u4-X23"},{"t":"분자의 수가 바로 분수만큼의 수이다","mis":"M3-2-u4-X04"}],"explanation":["분모는 전체를 똑같이 몇 묶음으로 나누는지 알려 줘요.","분자는 그중 몇 묶음인지 알려 줘요.","10의 ⟨3/5⟩ — 5묶음으로 나눈 것 중 3묶음, 2 × 3 = 6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L03_basic#9','math',3,2,'u4','L03','tb_g3_2_math_u4_L03_basic','lesson_basic','M3-2-u4-C3',2,'mc','auto','「익힘」 체육 시간에 서윤이와 지아가 각각 농구공을 10개씩 던졌어요. 서윤이는 10개의 ⟨1/2⟩만큼, 지아는 10개의 ⟨4/10⟩만큼을 넣었어요. 농구공을 더 많이 넣은 사람은 누구인가요?',ARRAY['M3-2-u4-X04','M3-2-u4-X22']::text[],false,'{"seq":9,"concept":"M3-2-u4-C3","difficulty":2,"kind":"mc","stem":"「익힘」 체육 시간에 서윤이와 지아가 각각 농구공을 10개씩 던졌어요. 서윤이는 10개의 ⟨1/2⟩만큼, 지아는 10개의 ⟨4/10⟩만큼을 넣었어요. 농구공을 더 많이 넣은 사람은 누구인가요?","options":[{"t":"서윤","correct":true},{"t":"지아","mis":"M3-2-u4-X04"},{"t":"두 사람이 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["10개의 ⟨1/2⟩만큼은 10을 2묶음으로 나눈 1묶음 — 5개예요.","10개의 ⟨4/10⟩만큼은 10을 10묶음으로 나눈 4묶음 — 4개예요.","5 > 4 — 서윤이가 더 많이 넣었어요. 분자 4가 1보다 크다고 더 많은 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L03_basic#10','math',3,2,'u4','L03','tb_g3_2_math_u4_L03_basic','lesson_basic','M3-2-u4-C3',3,'sa','auto','「익힘」 약과 12개 중 은비는 ⟨1/4⟩만큼을, 건우는 ⟨2/4⟩만큼을 먹었어요. 은비와 건우가 먹고 남은 약과는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u4-C3","difficulty":3,"kind":"sa","stem":"「익힘」 약과 12개 중 은비는 ⟨1/4⟩만큼을, 건우는 ⟨2/4⟩만큼을 먹었어요. 은비와 건우가 먹고 남은 약과는 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["12개의 ⟨1/4⟩만큼은 3개, 12개의 ⟨2/4⟩만큼은 6개예요.","두 사람이 먹은 약과는 3 + 6 = 9개예요.","남은 약과는 12 − 3 − 6 = 3개예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]]},{"p":[[1,0],[2,0],[2,1],[1,1]]},{"p":[[2,0],[3,0],[3,1],[2,1]]},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]},{"p":[[4.7,0],[5.7,0],[5.7,1],[4.7,1]]},{"p":[[5.7,0],[6.7,0],[6.7,1],[5.7,1]]},{"p":[[7.4,0],[8.4,0],[8.4,1],[7.4,1]]},{"p":[[8.4,0],[9.4,0],[9.4,1],[8.4,1]]},{"p":[[9.4,0],[10.4,0],[10.4,1],[9.4,1]]},{"p":[[11.1,0],[12.1,0],[12.1,1],[11.1,1]]},{"p":[[12.1,0],[13.1,0],[13.1,1],[12.1,1]]},{"p":[[13.1,0],[14.1,0],[14.1,1],[13.1,1]]}],"u":21}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L03_challenge#1','math',3,2,'u4','L03','tb_g3_2_math_u4_L03_challenge','lesson_challenge','M3-2-u4-C3',2,'sa','auto','사탕 12개를 똑같이 3묶음으로 나누면 한 묶음에 몇 개인지 나눗셈식 12 ÷ 3 = □로 구할 수 있어요. 12의 ⟨1/3⟩은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u4-C3","difficulty":2,"kind":"sa","stem":"사탕 12개를 똑같이 3묶음으로 나누면 한 묶음에 몇 개인지 나눗셈식 12 ÷ 3 = □로 구할 수 있어요. 12의 ⟨1/3⟩은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["12의 ⟨1/3⟩은 12를 똑같이 3묶음으로 나눈 것 중의 1묶음이에요.","나눗셈식으로 12 ÷ 3 = 4예요.","12의 ⟨1/3⟩은 4예요."],"variant_rule":{"alt":[{"stem":"풍선 8개를 똑같이 2묶음으로 나누면 한 묶음에 몇 개인지 나눗셈식 8 ÷ 2 = □로 구할 수 있어요. 8의 ⟨1/2⟩은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["8의 ⟨1/2⟩은 8을 똑같이 2묶음으로 나눈 것 중의 1묶음이에요.","나눗셈식으로 8 ÷ 2 = 4예요.","8의 ⟨1/2⟩은 4예요."]},{"stem":"지우개 9개를 똑같이 3묶음으로 나누면 한 묶음에 몇 개인지 나눗셈식 9 ÷ 3 = □로 구할 수 있어요. 9의 ⟨1/3⟩은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["9의 ⟨1/3⟩은 9를 똑같이 3묶음으로 나눈 것 중의 1묶음이에요.","나눗셈식으로 9 ÷ 3 = 3이에요.","9의 ⟨1/3⟩은 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L03_challenge#2','math',3,2,'u4','L03','tb_g3_2_math_u4_L03_challenge','lesson_challenge','M3-2-u4-C3',2,'mc','auto','「익힘」 공 7개의 ⟨2/7⟩만큼은 파란색으로, ⟨5/7⟩만큼은 빨간색으로 칠하려고 해요. 파란색과 빨간색으로 칠할 공은 각각 몇 개인가요?',ARRAY['M3-2-u4-X20','M3-2-u4-X05','M3-2-u4-X02']::text[],false,'{"seq":2,"concept":"M3-2-u4-C3","difficulty":2,"kind":"mc","stem":"「익힘」 공 7개의 ⟨2/7⟩만큼은 파란색으로, ⟨5/7⟩만큼은 빨간색으로 칠하려고 해요. 파란색과 빨간색으로 칠할 공은 각각 몇 개인가요?","options":[{"t":"파란색 2개, 빨간색 5개","correct":true},{"t":"파란색 5개, 빨간색 2개","mis":"M3-2-u4-X20"},{"t":"파란색 1개, 빨간색 5개","mis":"M3-2-u4-X05"},{"t":"파란색 2개, 빨간색 7개","mis":"M3-2-u4-X02"}],"explanation":["공 7개를 똑같이 7묶음으로 나누면 한 묶음에 1개예요.","7의 ⟨2/7⟩는 2묶음 — 2개, 7의 ⟨5/7⟩는 5묶음 — 5개예요.","파란색 2개, 빨간색 5개 — 모두 7개예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1.7,0],[2.7,0],[2.7,1],[1.7,1]],"hi":true},{"p":[[3.4,0],[4.4,0],[4.4,1],[3.4,1]]},{"p":[[5.1,0],[6.1,0],[6.1,1],[5.1,1]]},{"p":[[6.8,0],[7.8,0],[7.8,1],[6.8,1]]},{"p":[[8.5,0],[9.5,0],[9.5,1],[8.5,1]]},{"p":[[10.2,0],[11.2,0],[11.2,1],[10.2,1]]}],"u":26}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L03_challenge#3','math',3,2,'u4','L03','tb_g3_2_math_u4_L03_challenge','lesson_challenge','M3-2-u4-C3',3,'sa','auto','「확인 문제」 18의 ⟨2/3⟩는 18의 ⟨1/3⟩보다 얼마만큼 더 큰가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u4-C3","difficulty":3,"kind":"sa","stem":"「확인 문제」 18의 ⟨2/3⟩는 18의 ⟨1/3⟩보다 얼마만큼 더 큰가요? 숫자로 쓰세요.","answer":["6"],"explanation":["18을 똑같이 3묶음으로 나누면 한 묶음에 6이에요 — 18의 ⟨1/3⟩은 6이에요.","18의 ⟨2/3⟩는 6이 2묶음 — 12예요.","12 − 6 = 6 — 꼭 한 묶음만큼 더 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L03_challenge#4','math',3,2,'u4','L03','tb_g3_2_math_u4_L03_challenge','lesson_challenge','M3-2-u4-C3',3,'mc','auto','6의 ⟨4/6⟩와 12의 ⟨1/3⟩ 중 더 큰 것은 무엇인가요?',ARRAY['M3-2-u4-X04','M3-2-u4-X02','M3-2-u4-X22']::text[],false,'{"seq":4,"concept":"M3-2-u4-C3","difficulty":3,"kind":"mc","stem":"6의 ⟨4/6⟩와 12의 ⟨1/3⟩ 중 더 큰 것은 무엇인가요?","options":[{"t":"두 수가 같아요","correct":true},{"t":"6의 ⟨4/6⟩","mis":"M3-2-u4-X04"},{"t":"12의 ⟨1/3⟩","mis":"M3-2-u4-X02"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["6의 ⟨4/6⟩는 6을 6묶음으로 나눈 것 중 4묶음 — 4예요.","12의 ⟨1/3⟩은 12를 3묶음으로 나눈 것 중 1묶음 — 4예요.","둘 다 4 — 분자나 전체의 수만 보고 견주지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L03_challenge#5','math',3,2,'u4','L03','tb_g3_2_math_u4_L03_challenge','lesson_challenge','M3-2-u4-C3',3,'error','auto','10의 ⟨3/5⟩을 구하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u4-X06','M3-2-u4-X20']::text[],false,'{"seq":5,"concept":"M3-2-u4-C3","difficulty":3,"kind":"error","stem":"10의 ⟨3/5⟩을 구하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서준 — 「10을 똑같이 3묶음으로 나눈 것 중의 5묶음이야」","correct":true,"mis_target":"M3-2-u4-X06"},{"t":"채원 — 「10의 ⟨1/5⟩은 10을 5묶음으로 나눈 1묶음이라 2야」","mis":"M3-2-u4-X20"},{"t":"지유 — 「⟨3/5⟩은 ⟨1/5⟩이 3개라서 6이야」","mis":"M3-2-u4-X20"}],"explanation":["분모 5만큼 똑같이 5묶음으로 나누어요 — 한 묶음에 2예요.","분자 3만큼 3묶음을 모으면 6이에요.","서준이는 분모와 분자의 역할을 바꾸어 말했어요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]],"hi":true},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]],"hi":true},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]]},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]]},{"p":[[10.8,0],[11.8,0],[11.8,1],[10.8,1]]},{"p":[[11.8,0],[12.8,0],[12.8,1],[11.8,1]]}],"u":23}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L03_challenge#6','math',3,2,'u4','L03','tb_g3_2_math_u4_L03_challenge','lesson_challenge','M3-2-u4-C3',3,'sa','auto','「익힘」 공 7개의 ⟨2/7⟩만큼은 파란색, ⟨5/7⟩만큼은 빨간색으로 칠했어요. 빨간색 공은 파란색 공보다 몇 개 더 많나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M3-2-u4-C3","difficulty":3,"kind":"sa","stem":"「익힘」 공 7개의 ⟨2/7⟩만큼은 파란색, ⟨5/7⟩만큼은 빨간색으로 칠했어요. 빨간색 공은 파란색 공보다 몇 개 더 많나요? 숫자로 쓰세요.","answer":["3"],"explanation":["7의 ⟨2/7⟩는 2 — 파란색 공 2개예요.","7의 ⟨5/7⟩는 5 — 빨간색 공 5개예요.","5 − 2 = 3 — 빨간색 공이 3개 더 많아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1.7,0],[2.7,0],[2.7,1],[1.7,1]],"hi":true},{"p":[[3.4,0],[4.4,0],[4.4,1],[3.4,1]]},{"p":[[5.1,0],[6.1,0],[6.1,1],[5.1,1]]},{"p":[[6.8,0],[7.8,0],[7.8,1],[6.8,1]]},{"p":[[8.5,0],[9.5,0],[9.5,1],[8.5,1]]},{"p":[[10.2,0],[11.2,0],[11.2,1],[10.2,1]]}],"u":26}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L03_challenge#7','math',3,2,'u4','L03','tb_g3_2_math_u4_L03_challenge','lesson_challenge','M3-2-u4-C3',3,'mc','auto','「확인 문제」 8의 ⟨1/4⟩을 구하려고 해요. 바르게 구한 것은 무엇인가요?',ARRAY['M3-2-u4-X23','M3-2-u4-X04','M3-2-u4-X06']::text[],false,'{"seq":7,"concept":"M3-2-u4-C3","difficulty":3,"kind":"mc","stem":"「확인 문제」 8의 ⟨1/4⟩을 구하려고 해요. 바르게 구한 것은 무엇인가요?","options":[{"t":"2개씩 4묶음으로 나누어 그중 1묶음인 2","correct":true},{"t":"4개씩 2묶음으로 나누어 그중 1묶음인 4","mis":"M3-2-u4-X23"},{"t":"8개 중 분자만큼인 1","mis":"M3-2-u4-X04"},{"t":"8개 중 분모만큼인 4","mis":"M3-2-u4-X06"}],"explanation":["분모 4 — 8개를 똑같이 4묶음으로 나누어요.","한 묶음에 2개 — 1묶음은 2예요.","4개씩 묶으면 2묶음이 되어 「4묶음으로 나누기」가 아니에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]]},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]]},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]]},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]]},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]]}],"u":29}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L03_challenge#8','math',3,2,'u4','L03','tb_g3_2_math_u4_L03_challenge','lesson_challenge','M3-2-u4-C3',4,'sa','auto','「익힘」 어떤 수의 ⟨1/4⟩이 3이에요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u4-C3","difficulty":4,"kind":"sa","stem":"「익힘」 어떤 수의 ⟨1/4⟩이 3이에요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["⟨1/4⟩은 똑같이 4묶음으로 나눈 것 중의 1묶음이에요.","1묶음이 3이므로 4묶음은 3 × 4 = 12예요.","어떤 수는 12 — 은비가 먹은 약과 장면과 같아요."],"variant_rule":{"alt":[{"stem":"어떤 수의 ⟨1/2⟩이 4예요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["⟨1/2⟩은 똑같이 2묶음으로 나눈 것 중의 1묶음이에요.","1묶음이 4이므로 2묶음은 4 × 2 = 8이에요.","어떤 수는 8 — 분홍색 풍선 장면과 같아요."]},{"stem":"「익힘」 어떤 수의 ⟨3/6⟩이 6이에요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["⟨3/6⟩은 6묶음으로 나눈 것 중의 3묶음이에요.","3묶음이 6이므로 1묶음은 6 ÷ 3 = 2예요.","6묶음은 2 × 6 = 12 — 어떤 수는 12예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L03_challenge#9','math',3,2,'u4','L03','tb_g3_2_math_u4_L03_challenge','lesson_challenge','M3-2-u4-C3',4,'essay','teacher','12의 ⟨1/3⟩과 12의 ⟨2/3⟩를 구하고, 구한 방법을 묶음으로 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u4-C3","difficulty":4,"kind":"essay","stem":"12의 ⟨1/3⟩과 12의 ⟨2/3⟩를 구하고, 구한 방법을 묶음으로 설명해 보세요.","answer_guide":{"answer":"예: 12를 분모 3만큼 똑같이 3묶음으로 나누면 한 묶음에 4이다. 12의 ⟨1/3⟩은 1묶음이므로 4이고, 12의 ⟨2/3⟩는 2묶음이므로 8이다. 전체를 분모만큼의 묶음으로 나누고 그중 분자만큼의 묶음에 해당하는 수를 구하면 된다.","scoring_points":["12의 ⟨1/3⟩을 4라고 구했는가","12의 ⟨2/3⟩를 8이라고 구했는가","분모만큼 나누고 분자만큼 센다고 설명했는가"]},"explanation":["12 ÷ 3 = 4예요.","12의 ⟨1/3⟩은 4, 12의 ⟨2/3⟩는 8이에요.","3개씩 묶어 3이라 하지 않아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]],"hi":true},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[2.7,1],[3.7,1],[3.7,2],[2.7,2]],"hi":true},{"p":[[3.7,1],[4.7,1],[4.7,2],[3.7,2]],"hi":true},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]]},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]]},{"p":[[5.4,1],[6.4,1],[6.4,2],[5.4,2]]},{"p":[[6.4,1],[7.4,1],[7.4,2],[6.4,2]]}],"u":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L03_challenge#10','math',3,2,'u4','L03','tb_g3_2_math_u4_L03_challenge','lesson_challenge','M3-2-u4-C3',4,'essay','teacher','「익힘」 서윤이는 농구공 10개의 ⟨1/2⟩만큼, 지아는 10개의 ⟨4/10⟩만큼을 넣었어요. 누가 더 많이 넣었는지 쓰고, 그 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u4-C3","difficulty":4,"kind":"essay","stem":"「익힘」 서윤이는 농구공 10개의 ⟨1/2⟩만큼, 지아는 10개의 ⟨4/10⟩만큼을 넣었어요. 누가 더 많이 넣었는지 쓰고, 그 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 서윤이가 더 많이 넣었다. 10개의 ⟨1/2⟩만큼은 10을 2묶음으로 나눈 것 중 1묶음이라 5개이고, 10개의 ⟨4/10⟩만큼은 10묶음으로 나눈 것 중 4묶음이라 4개이다. 5 > 4이므로 서윤이가 더 많이 넣었다.","scoring_points":["서윤이라고 답했는가","5개와 4개를 바르게 구했는가","분자만 보지 않고 분수만큼을 구해 견주었는가"]},"explanation":["10개의 ⟨1/2⟩만큼은 5개예요.","10개의 ⟨4/10⟩만큼은 4개예요.","서윤이가 더 많이 넣었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L04_basic#1','math',3,2,'u4','L04','tb_g3_2_math_u4_L04_basic','lesson_basic','M3-2-u4-C4',1,'sa','auto','서준이네 반 친구들이 연극 무대를 꾸미는 데 색 테이프 6 m의 ⟨1/3⟩만큼을 사용했어요. 사용한 색 테이프는 몇 m인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u4-C4","difficulty":1,"kind":"sa","stem":"서준이네 반 친구들이 연극 무대를 꾸미는 데 색 테이프 6 m의 ⟨1/3⟩만큼을 사용했어요. 사용한 색 테이프는 몇 m인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["6 m를 똑같이 3부분으로 나누면 한 부분이 2 m예요 — 6 ÷ 3 = 2.","⟨1/3⟩은 그중 1부분이에요.","6 m의 ⟨1/3⟩만큼은 2 m예요."],"asset":{"type":"fbar","bars":[{"den":3,"num":1,"label":"색 테이프 6 m"}]},"variant_rule":{"alt":[{"stem":"「익힘」 연극 무대를 꾸미는 데 색 테이프 8 m의 ⟨1/2⟩만큼을 사용했어요. 사용한 색 테이프는 몇 m인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["8 m를 똑같이 2부분으로 나누면 한 부분이 4 m예요 — 8 ÷ 2 = 4.","⟨1/2⟩은 그중 1부분이에요.","8 m의 ⟨1/2⟩만큼은 4 m예요."],"asset":{"type":"fbar","bars":[{"den":2,"num":1,"label":"색 테이프 8 m"}]}},{"stem":"「익힘」 6을 똑같이 3부분으로 나누었어요. 6의 ⟨1/3⟩은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["6을 똑같이 3부분으로 나누면 한 부분이 2예요 — 6 ÷ 3 = 2.","⟨1/3⟩은 그중 1부분이에요.","6의 ⟨1/3⟩만큼은 2예요."],"asset":{"type":"fbar","bars":[{"den":6,"num":2,"grp":2,"label":"0부터 6까지"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L04_basic#2','math',3,2,'u4','L04','tb_g3_2_math_u4_L04_basic','lesson_basic','M3-2-u4-C4',1,'sa','auto','12를 똑같이 4부분으로 나누었어요. 12의 ⟨1/4⟩은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u4-C4","difficulty":1,"kind":"sa","stem":"12를 똑같이 4부분으로 나누었어요. 12의 ⟨1/4⟩은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["12를 똑같이 4부분으로 나누면 한 부분이 3이에요 — 12 ÷ 4 = 3.","⟨1/4⟩은 그중 1부분이에요.","12의 ⟨1/4⟩만큼은 3이에요."],"asset":{"type":"fbar","bars":[{"den":12,"num":3,"grp":3,"label":"0부터 12까지"}]},"variant_rule":{"alt":[{"stem":"25를 똑같이 5부분으로 나누었어요. 25의 ⟨1/5⟩은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["25를 똑같이 5부분으로 나누면 한 부분이 5예요 — 25 ÷ 5 = 5.","⟨1/5⟩은 그중 1부분이에요.","25의 ⟨1/5⟩만큼은 5예요."],"asset":{"type":"fbar","bars":[{"den":5,"num":1,"label":"0부터 25까지"}]}},{"stem":"「익힘」 10을 똑같이 5부분으로 나누었어요. 10의 ⟨1/5⟩은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["10을 똑같이 5부분으로 나누면 한 부분이 2예요 — 10 ÷ 5 = 2.","⟨1/5⟩은 그중 1부분이에요.","10의 ⟨1/5⟩만큼은 2예요."],"asset":{"type":"fbar","bars":[{"den":10,"num":2,"grp":2,"label":"0부터 10까지"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L04_basic#3','math',3,2,'u4','L04','tb_g3_2_math_u4_L04_basic','lesson_basic','M3-2-u4-C4',1,'sa','auto','12의 ⟨1/4⟩이 3인 것을 이용하여 12의 ⟨3/4⟩을 구해 보세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u4-C4","difficulty":1,"kind":"sa","stem":"12의 ⟨1/4⟩이 3인 것을 이용하여 12의 ⟨3/4⟩을 구해 보세요. 숫자로 쓰세요.","answer":["9"],"explanation":["12를 똑같이 4부분으로 나누면 한 부분이 3이에요 — 12 ÷ 4 = 3.","⟨3/4⟩은 ⟨1/4⟩이 3개 — 3부분이에요.","12의 ⟨3/4⟩만큼은 9예요. 분자 3만 보고 답하지 않아요."],"asset":{"type":"fbar","bars":[{"den":12,"num":9,"grp":3,"label":"0부터 12까지"}]},"variant_rule":{"alt":[{"stem":"25의 ⟨1/5⟩이 5인 것을 이용하여 25의 ⟨4/5⟩를 구해 보세요. 숫자로 쓰세요.","answer":["20"],"explanation":["25를 똑같이 5부분으로 나누면 한 부분이 5예요 — 25 ÷ 5 = 5.","⟨4/5⟩는 ⟨1/5⟩이 4개 — 4부분이에요.","25의 ⟨4/5⟩만큼은 20이에요. 분자 4만 보고 답하지 않아요."],"asset":{"type":"fbar","bars":[{"den":5,"num":4,"label":"0부터 25까지"}]}},{"stem":"「익힘」 10의 ⟨1/5⟩이 2인 것을 이용하여 10의 ⟨2/5⟩를 구해 보세요. 숫자로 쓰세요.","answer":["4"],"explanation":["10을 똑같이 5부분으로 나누면 한 부분이 2예요 — 10 ÷ 5 = 2.","⟨2/5⟩는 ⟨1/5⟩이 2개 — 2부분이에요.","10의 ⟨2/5⟩만큼은 4예요. 분자 2만 보고 답하지 않아요."],"asset":{"type":"fbar","bars":[{"den":10,"num":4,"grp":2,"label":"0부터 10까지"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L04_basic#4','math',3,2,'u4','L04','tb_g3_2_math_u4_L04_basic','lesson_basic','M3-2-u4-C4',1,'blank','auto','「확인 문제」 16 m의 ⟨1/8⟩만큼은 전체를 똑같이 □부분으로 나눈 것 중의 1부분이에요. □에 알맞은 수는 무엇인가요?',ARRAY['M3-2-u4-X23','M3-2-u4-X02','M3-2-u4-X04']::text[],true,'{"seq":4,"concept":"M3-2-u4-C4","difficulty":1,"kind":"blank","stem":"「확인 문제」 16 m의 ⟨1/8⟩만큼은 전체를 똑같이 □부분으로 나눈 것 중의 1부분이에요. □에 알맞은 수는 무엇인가요?","options":[{"t":"8","correct":true},{"t":"2","mis":"M3-2-u4-X23"},{"t":"16","mis":"M3-2-u4-X02"},{"t":"1","mis":"M3-2-u4-X04"}],"explanation":["분모 8은 「똑같이 8부분으로 나눈다」는 뜻이에요.","16 m를 8부분으로 나누면 한 부분이 2 m예요.","그래서 16 m의 ⟨1/8⟩만큼은 2 m — □는 8이에요."],"asset":{"type":"fbar","bars":[{"den":8,"num":1,"label":"16 m"}]},"variant_rule":{"alt":[{"stem":"6 m의 ⟨1/3⟩만큼은 전체 6 m를 똑같이 □부분으로 나눈 것 중의 1부분이에요. □에 알맞은 수는 무엇인가요?","options":[{"t":"3","correct":true},{"t":"2","mis":"M3-2-u4-X23"},{"t":"6","mis":"M3-2-u4-X02"},{"t":"1","mis":"M3-2-u4-X04"}],"explanation":["분모 3은 「똑같이 3부분으로 나눈다」는 뜻이에요.","6 m를 3부분으로 나누면 한 부분이 2 m예요.","그래서 6 m의 ⟨1/3⟩만큼은 2 m — □는 3이에요."],"asset":{"type":"fbar","bars":[{"den":3,"num":1,"label":"6 m"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L04_basic#5','math',3,2,'u4','L04','tb_g3_2_math_u4_L04_basic','lesson_basic','M3-2-u4-C4',2,'mc','auto','「익힘」 길이가 80 cm인 띠의 ⟨1/4⟩만큼은 빨간색으로 칠하려고 해요. 빨간색으로 칠할 길이는 몇 cm인가요?',ARRAY['M3-2-u4-X25','M3-2-u4-X23','M3-2-u4-X04']::text[],true,'{"seq":5,"concept":"M3-2-u4-C4","difficulty":2,"kind":"mc","stem":"「익힘」 길이가 80 cm인 띠의 ⟨1/4⟩만큼은 빨간색으로 칠하려고 해요. 빨간색으로 칠할 길이는 몇 cm인가요?","options":[{"t":"20 cm","correct":true},{"t":"⟨1/4⟩ cm","mis":"M3-2-u4-X25"},{"t":"4 cm","mis":"M3-2-u4-X23"},{"t":"1 cm","mis":"M3-2-u4-X04"}],"explanation":["80 cm를 똑같이 4부분으로 나누면 한 부분이 20 cm예요 — 80 ÷ 4 = 20.","⟨1/4⟩은 그중 1부분이에요.","80 cm의 ⟨1/4⟩만큼은 20 cm예요."],"asset":{"type":"fbar","bars":[{"den":4,"num":1,"label":"띠 80 cm"}]},"variant_rule":{"alt":[{"stem":"「익힘」 길이가 80 cm인 띠의 ⟨3/4⟩만큼은 노란색으로 칠하려고 해요. 노란색으로 칠할 길이는 몇 cm인가요?","options":[{"t":"60 cm","correct":true},{"t":"⟨3/4⟩ cm","mis":"M3-2-u4-X25"},{"t":"3 cm","mis":"M3-2-u4-X04"},{"t":"20 cm","mis":"M3-2-u4-X05"}],"explanation":["80 cm를 똑같이 4부분으로 나누면 한 부분이 20 cm예요 — 80 ÷ 4 = 20.","⟨3/4⟩은 ⟨1/4⟩이 3개 — 3부분이에요.","80 cm의 ⟨3/4⟩만큼은 60 cm예요. 분자 3만 보고 답하지 않아요."],"asset":{"type":"fbar","bars":[{"den":4,"num":3,"label":"띠 80 cm"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L04_basic#6','math',3,2,'u4','L04','tb_g3_2_math_u4_L04_basic','lesson_basic','M3-2-u4-C4',2,'sa','auto','「익힘」 은비는 12시간의 ⟨2/3⟩만큼 놀이공원에서 놀았어요. 은비는 놀이공원에서 몇 시간 놀았나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u4-C4","difficulty":2,"kind":"sa","stem":"「익힘」 은비는 12시간의 ⟨2/3⟩만큼 놀이공원에서 놀았어요. 은비는 놀이공원에서 몇 시간 놀았나요? 숫자로 쓰세요.","answer":["8"],"explanation":["12시간을 똑같이 3부분으로 나누면 한 부분이 4시간이에요 — 12 ÷ 3 = 4.","⟨2/3⟩는 ⟨1/3⟩이 2개 — 2부분이에요.","12시간의 ⟨2/3⟩만큼은 8시간이에요. 분자 2만 보고 답하지 않아요."],"asset":{"type":"fbar","bars":[{"den":3,"num":2,"label":"12시간"}]},"variant_rule":{"alt":[{"stem":"「수학 되돌아보기」 서준이는 동시 「사라진 시간」에서 12시간의 ⟨4/12⟩만큼 영화를 보았다고 했어요. 영화를 본 시간은 몇 시간인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["12시간을 똑같이 12부분으로 나누면 한 부분이 1시간이에요 — 12 ÷ 12 = 1.","⟨4/12⟩는 ⟨1/12⟩이 4개 — 4부분이에요.","12시간의 ⟨4/12⟩만큼은 4시간이에요. 분자 4만 보고 답하지 않아요."],"asset":{"type":"fbar","bars":[{"den":12,"num":4,"label":"12시간"}]}},{"stem":"「수학 되돌아보기」 서준이는 12시간의 ⟨6/12⟩만큼 친구와 함께 보냈어요. 친구와 함께한 시간은 몇 시간인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["12시간을 똑같이 12부분으로 나누면 한 부분이 1시간이에요 — 12 ÷ 12 = 1.","⟨6/12⟩은 ⟨1/12⟩이 6개 — 6부분이에요.","12시간의 ⟨6/12⟩만큼은 6시간이에요. 분자 6만 보고 답하지 않아요."],"asset":{"type":"fbar","bars":[{"den":12,"num":6,"label":"12시간"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L04_basic#7','math',3,2,'u4','L04','tb_g3_2_math_u4_L04_basic','lesson_basic','M3-2-u4-C4',2,'mc','auto','색 테이프 6 m의 ⟨1/3⟩만큼을 사용했어요. 사용한 색 테이프의 길이를 바르게 말한 것은 무엇인가요?',ARRAY['M3-2-u4-X25','M3-2-u4-X23','M3-2-u4-X04']::text[],false,'{"seq":7,"concept":"M3-2-u4-C4","difficulty":2,"kind":"mc","stem":"색 테이프 6 m의 ⟨1/3⟩만큼을 사용했어요. 사용한 색 테이프의 길이를 바르게 말한 것은 무엇인가요?","options":[{"t":"2 m","correct":true},{"t":"⟨1/3⟩ m","mis":"M3-2-u4-X25"},{"t":"3 m","mis":"M3-2-u4-X23"},{"t":"1 m","mis":"M3-2-u4-X04"}],"explanation":["「6 m의 ⟨1/3⟩만큼」은 6 m를 똑같이 3부분으로 나눈 것 중의 1부분이에요.","6 m를 3부분으로 나누면 한 부분이 2 m예요.","그래서 사용한 길이는 2 m — ⟨1/3⟩ m와는 다른 길이예요."],"asset":{"type":"fbar","bars":[{"den":3,"num":1,"label":"색 테이프 6 m"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L04_basic#8','math',3,2,'u4','L04','tb_g3_2_math_u4_L04_basic','lesson_basic','M3-2-u4-C4',2,'ox','auto','지유는 「12의 ⟨1/4⟩은 4이고, 12의 ⟨3/4⟩은 12야.」라고 했어요. 지유의 말이 옳은가요?',ARRAY['M3-2-u4-X23']::text[],false,'{"seq":8,"concept":"M3-2-u4-C4","difficulty":2,"kind":"ox","stem":"지유는 「12의 ⟨1/4⟩은 4이고, 12의 ⟨3/4⟩은 12야.」라고 했어요. 지유의 말이 옳은가요?","answer":"X","reason_options":[{"t":"12를 똑같이 4부분으로 나누면 한 부분이 3이라서","correct":true},{"t":"분모 4가 한 부분의 크기라서","mis":"M3-2-u4-X23"}],"mis":"M3-2-u4-X23","explanation":["12의 ⟨1/4⟩은 12를 똑같이 4부분으로 나눈 것 중의 1부분 — 3이에요.","12의 ⟨3/4⟩은 3이 3부분 — 9예요.","지유는 분모 4를 한 부분의 크기로 보았어요 — 옳지 않아요."],"asset":{"type":"fbar","bars":[{"den":12,"num":9,"grp":3,"label":"0부터 12까지"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L04_basic#9','math',3,2,'u4','L04','tb_g3_2_math_u4_L04_basic','lesson_basic','M3-2-u4-C4',2,'sa','auto','「익힘」 채원이는 하루의 ⟨2/24⟩만큼 독서를 했어요. 하루는 24시간이에요. 채원이가 독서를 한 시간은 몇 시간인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u4-C4","difficulty":2,"kind":"sa","stem":"「익힘」 채원이는 하루의 ⟨2/24⟩만큼 독서를 했어요. 하루는 24시간이에요. 채원이가 독서를 한 시간은 몇 시간인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["24시간을 똑같이 24부분으로 나누면 한 부분이 1시간이에요 — 24 ÷ 24 = 1.","⟨2/24⟩는 ⟨1/24⟩이 2개 — 2부분이에요.","24시간의 ⟨2/24⟩만큼은 2시간이에요. 분자 2만 보고 답하지 않아요."],"variant_rule":{"alt":[{"stem":"「익힘」 채원이는 하루의 ⟨1/24⟩만큼 운동을 했어요. 하루는 24시간이에요. 채원이가 운동을 한 시간은 몇 시간인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["24시간을 똑같이 24부분으로 나누면 한 부분이 1시간이에요 — 24 ÷ 24 = 1.","⟨1/24⟩은 그중 1부분이에요.","24시간의 ⟨1/24⟩만큼은 1시간이에요."]},{"stem":"「익힘」 채원이는 하루의 ⟨6/24⟩만큼 학교에 있었어요. 하루는 24시간이에요. 채원이가 학교에 있었던 시간은 몇 시간인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["24시간을 똑같이 24부분으로 나누면 한 부분이 1시간이에요 — 24 ÷ 24 = 1.","⟨6/24⟩은 ⟨1/24⟩이 6개 — 6부분이에요.","24시간의 ⟨6/24⟩만큼은 6시간이에요. 분자 6만 보고 답하지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L04_basic#10','math',3,2,'u4','L04','tb_g3_2_math_u4_L04_basic','lesson_basic','M3-2-u4-C4',3,'sa','auto','「익힘」 건우는 길이가 400 m인 산책로를 오전에는 ⟨1/2⟩만큼, 오후에는 ⟨1/4⟩만큼 달렸어요. 건우가 오전과 오후에 산책로를 달린 거리는 모두 몇 m인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u4-C4","difficulty":3,"kind":"sa","stem":"「익힘」 건우는 길이가 400 m인 산책로를 오전에는 ⟨1/2⟩만큼, 오후에는 ⟨1/4⟩만큼 달렸어요. 건우가 오전과 오후에 산책로를 달린 거리는 모두 몇 m인가요? 숫자로 쓰세요.","answer":["300"],"explanation":["400 m의 ⟨1/2⟩만큼은 400 m를 2부분으로 나눈 1부분 — 200 m예요.","400 m의 ⟨1/4⟩만큼은 400 m를 4부분으로 나눈 1부분 — 100 m예요.","200 + 100 = 300 — 모두 300 m를 달렸어요."],"asset":{"type":"fbar","bars":[{"den":4,"num":3,"label":"산책로 400 m"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L04_challenge#1','math',3,2,'u4','L04','tb_g3_2_math_u4_L04_challenge','lesson_challenge','M3-2-u4-C4',2,'mc','auto','「재미있는 수학」 친구와 띠 색칠하기 놀이를 해요. 뒤집은 카드에 「9 cm의 ⟨1/3⟩만큼 색칠하세요.」라고 적혀 있어요. 몇 cm를 색칠해야 하나요?',ARRAY['M3-2-u4-X25','M3-2-u4-X04','M3-2-u4-X02']::text[],false,'{"seq":1,"concept":"M3-2-u4-C4","difficulty":2,"kind":"mc","stem":"「재미있는 수학」 친구와 띠 색칠하기 놀이를 해요. 뒤집은 카드에 「9 cm의 ⟨1/3⟩만큼 색칠하세요.」라고 적혀 있어요. 몇 cm를 색칠해야 하나요?","options":[{"t":"3 cm","correct":true},{"t":"⟨1/3⟩ cm","mis":"M3-2-u4-X25"},{"t":"1 cm","mis":"M3-2-u4-X04"},{"t":"9 cm","mis":"M3-2-u4-X02"}],"explanation":["9 cm의 ⟨1/3⟩만큼은 9 cm를 똑같이 3부분으로 나눈 것 중의 1부분이에요.","9 ÷ 3 = 3 — 한 부분은 3 cm예요.","그래서 3 cm를 색칠해요 — 띠 10 cm를 다 채우면 놀이가 끝나요."],"asset":{"type":"fbar","bars":[{"den":3,"num":1,"label":"9 cm"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L04_challenge#2','math',3,2,'u4','L04','tb_g3_2_math_u4_L04_challenge','lesson_challenge','M3-2-u4-C4',2,'sa','auto','「확인 문제」 0부터 14까지 똑같이 나눈 수직선이 있어요. 14의 ⟨5/7⟩는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u4-C4","difficulty":2,"kind":"sa","stem":"「확인 문제」 0부터 14까지 똑같이 나눈 수직선이 있어요. 14의 ⟨5/7⟩는 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["14를 똑같이 7부분으로 나누면 한 부분이 2예요 — 14 ÷ 7 = 2.","⟨5/7⟩는 ⟨1/7⟩이 5개 — 5부분이에요.","14의 ⟨5/7⟩만큼은 10이에요. 분자 5만 보고 답하지 않아요."],"asset":{"type":"fbar","bars":[{"den":14,"num":10,"grp":2,"label":"0부터 14까지"}]},"variant_rule":{"alt":[{"stem":"「확인 문제」 14의 ⟨1/7⟩은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["14를 똑같이 7부분으로 나누면 한 부분이 2예요 — 14 ÷ 7 = 2.","⟨1/7⟩은 그중 1부분이에요.","14의 ⟨1/7⟩만큼은 2예요."],"asset":{"type":"fbar","bars":[{"den":14,"num":2,"grp":2,"label":"0부터 14까지"}]}},{"stem":"「확인 문제」 16 m의 ⟨1/8⟩만큼은 몇 m인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["16 m를 똑같이 8부분으로 나누면 한 부분이 2 m예요 — 16 ÷ 8 = 2.","⟨1/8⟩은 그중 1부분이에요.","16 m의 ⟨1/8⟩만큼은 2 m예요."],"asset":{"type":"fbar","bars":[{"den":8,"num":1,"label":"16 m"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L04_challenge#3','math',3,2,'u4','L04','tb_g3_2_math_u4_L04_challenge','lesson_challenge','M3-2-u4-C4',3,'sa','auto','「수학 되돌아보기」 서준이는 12시간의 ⟨4/12⟩만큼 영화를 보고, 12시간의 ⟨2/12⟩만큼 강아지와 산책했어요. 영화를 본 시간은 산책한 시간보다 몇 시간 더 긴가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u4-C4","difficulty":3,"kind":"sa","stem":"「수학 되돌아보기」 서준이는 12시간의 ⟨4/12⟩만큼 영화를 보고, 12시간의 ⟨2/12⟩만큼 강아지와 산책했어요. 영화를 본 시간은 산책한 시간보다 몇 시간 더 긴가요? 숫자로 쓰세요.","answer":["2"],"explanation":["12시간의 ⟨4/12⟩만큼은 12시간을 12부분으로 나눈 4부분 — 4시간이에요.","12시간의 ⟨2/12⟩만큼은 2시간이에요.","4 − 2 = 2 — 영화를 본 시간이 2시간 더 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L04_challenge#4','math',3,2,'u4','L04','tb_g3_2_math_u4_L04_challenge','lesson_challenge','M3-2-u4-C4',3,'sa','auto','「익힘」 채원이는 하루의 ⟨2/24⟩만큼 독서를 하고, 하루의 ⟨1/24⟩만큼 운동을 했어요. 독서와 운동을 한 시간은 모두 몇 시간인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M3-2-u4-C4","difficulty":3,"kind":"sa","stem":"「익힘」 채원이는 하루의 ⟨2/24⟩만큼 독서를 하고, 하루의 ⟨1/24⟩만큼 운동을 했어요. 독서와 운동을 한 시간은 모두 몇 시간인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["하루는 24시간이에요 — 24시간을 24부분으로 나누면 한 부분은 1시간이에요.","24시간의 ⟨2/24⟩만큼은 2시간, 24시간의 ⟨1/24⟩만큼은 1시간이에요.","2 + 1 = 3 — 모두 3시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L04_challenge#5','math',3,2,'u4','L04','tb_g3_2_math_u4_L04_challenge','lesson_challenge','M3-2-u4-C4',3,'error','auto','「익힘」 길이가 80 cm인 띠를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u4-X25','M3-2-u4-X20']::text[],false,'{"seq":5,"concept":"M3-2-u4-C4","difficulty":3,"kind":"error","stem":"「익힘」 길이가 80 cm인 띠를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하윤 — 「80 cm의 ⟨3/4⟩만큼은 ⟨3/4⟩ cm야」","correct":true,"mis_target":"M3-2-u4-X25"},{"t":"도윤 — 「80 cm의 ⟨1/4⟩만큼은 20 cm야」","mis":"M3-2-u4-X20"},{"t":"은비 — 「⟨3/4⟩만큼은 20 cm가 3부분이라 60 cm야」","mis":"M3-2-u4-X20"}],"explanation":["80 cm를 똑같이 4부분으로 나누면 한 부분이 20 cm예요.","⟨3/4⟩만큼은 20 cm가 3부분 — 60 cm예요.","하윤이는 전체의 분수만큼과 ⟨3/4⟩ cm라는 길이를 헷갈렸어요."],"asset":{"type":"fbar","bars":[{"den":4,"num":3,"label":"띠 80 cm"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L04_challenge#6','math',3,2,'u4','L04','tb_g3_2_math_u4_L04_challenge','lesson_challenge','M3-2-u4-C4',3,'sa','auto','「익힘」 길이가 400 m인 산책로를 오전에는 ⟨1/2⟩만큼, 오후에는 ⟨1/4⟩만큼 달렸어요. 아직 달리지 않은 거리는 몇 m인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M3-2-u4-C4","difficulty":3,"kind":"sa","stem":"「익힘」 길이가 400 m인 산책로를 오전에는 ⟨1/2⟩만큼, 오후에는 ⟨1/4⟩만큼 달렸어요. 아직 달리지 않은 거리는 몇 m인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["400 m의 ⟨1/2⟩만큼은 200 m, 400 m의 ⟨1/4⟩만큼은 100 m예요.","달린 거리는 200 + 100 = 300 m예요.","400 − 300 = 100 — 아직 100 m가 남았어요."],"asset":{"type":"fbar","bars":[{"den":4,"num":3,"label":"산책로 400 m"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L04_challenge#7','math',3,2,'u4','L04','tb_g3_2_math_u4_L04_challenge','lesson_challenge','M3-2-u4-C4',3,'mc','auto','“20 m짜리 띠의 ⟨1/2⟩만큼 잘라 줘.”라는 말을 들었어요. 몇 m를 잘라 주어야 하나요?',ARRAY['M3-2-u4-X25','M3-2-u4-X23']::text[],false,'{"seq":7,"concept":"M3-2-u4-C4","difficulty":3,"kind":"mc","stem":"“20 m짜리 띠의 ⟨1/2⟩만큼 잘라 줘.”라는 말을 들었어요. 몇 m를 잘라 주어야 하나요?","options":[{"t":"10 m","correct":true},{"t":"⟨1/2⟩ m","mis":"M3-2-u4-X25"},{"t":"2 m","mis":"M3-2-u4-X23"}],"explanation":["20 m의 ⟨1/2⟩만큼은 20 m를 똑같이 2부분으로 나눈 것 중의 1부분이에요.","20 ÷ 2 = 10 — 한 부분은 10 m예요.","그래서 10 m를 잘라 주어요 — 생활에서도 분수로 전체에 대한 부분을 말해요."],"asset":{"type":"fbar","bars":[{"den":2,"num":1,"label":"띠 20 m"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L04_challenge#8','math',3,2,'u4','L04','tb_g3_2_math_u4_L04_challenge','lesson_challenge','M3-2-u4-C4',4,'sa','auto','색 테이프 전체의 ⟨1/3⟩만큼이 2 m예요. 색 테이프 전체의 길이는 몇 m인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u4-C4","difficulty":4,"kind":"sa","stem":"색 테이프 전체의 ⟨1/3⟩만큼이 2 m예요. 색 테이프 전체의 길이는 몇 m인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["⟨1/3⟩만큼은 전체를 똑같이 3부분으로 나눈 것 중의 1부분이에요.","1부분이 2 m이므로 3부분은 2 × 3 = 6 m예요.","전체는 6 m — 연극 무대 색 테이프 장면과 같아요."],"variant_rule":{"alt":[{"stem":"「익힘」 띠 전체의 ⟨1/4⟩만큼이 20 cm예요. 띠 전체의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["⟨1/4⟩만큼은 전체를 똑같이 4부분으로 나눈 것 중의 1부분이에요.","1부분이 20 cm이므로 4부분은 20 × 4 = 80 cm예요.","띠 전체는 80 cm예요."]},{"stem":"「익힘」 산책로 전체의 ⟨1/2⟩만큼이 200 m예요. 산책로 전체의 길이는 몇 m인가요? 숫자로 쓰세요.","answer":["400"],"explanation":["⟨1/2⟩만큼은 전체를 똑같이 2부분으로 나눈 것 중의 1부분이에요.","1부분이 200 m이므로 2부분은 200 × 2 = 400 m예요.","산책로 전체는 400 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L04_challenge#9','math',3,2,'u4','L04','tb_g3_2_math_u4_L04_challenge','lesson_challenge','M3-2-u4-C4',4,'essay','teacher','「6 m의 ⟨1/3⟩만큼」과 「⟨1/3⟩ m」는 같은 길이인지 쓰고, 그렇게 생각한 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u4-C4","difficulty":4,"kind":"essay","stem":"「6 m의 ⟨1/3⟩만큼」과 「⟨1/3⟩ m」는 같은 길이인지 쓰고, 그렇게 생각한 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 같은 길이가 아니다. 6 m의 ⟨1/3⟩만큼은 6 m를 똑같이 3부분으로 나눈 것 중의 1부분이므로 2 m이다. ⟨1/3⟩ m는 1 m를 똑같이 3부분으로 나눈 것 중의 1부분이므로 1 m보다 짧다.","scoring_points":["같지 않다고 답했는가","6 m의 ⟨1/3⟩만큼이 2 m라고 구했는가","⟨1/3⟩ m는 1 m를 3부분으로 나눈 1부분이라고 설명했는가"]},"explanation":["6 m의 ⟨1/3⟩만큼은 2 m예요.","⟨1/3⟩ m는 1 m보다 짧아요.","전체가 무엇인지 보고 분수만큼을 구해요."],"asset":{"type":"fbar","bars":[{"den":3,"num":1,"label":"색 테이프 6 m"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L04_challenge#10','math',3,2,'u4','L04','tb_g3_2_math_u4_L04_challenge','lesson_challenge','M3-2-u4-C4',4,'essay','teacher','12의 ⟨3/4⟩을 구하고, 12의 ⟨1/4⟩을 이용하여 구한 방법을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u4-C4","difficulty":4,"kind":"essay","stem":"12의 ⟨3/4⟩을 구하고, 12의 ⟨1/4⟩을 이용하여 구한 방법을 설명해 보세요.","answer_guide":{"answer":"예: 12를 분모 4만큼 똑같이 4부분으로 나누면 한 부분이 3이므로 12의 ⟨1/4⟩은 3이다. ⟨3/4⟩은 ⟨1/4⟩이 3개이므로 12의 ⟨3/4⟩은 3이 3부분인 9이다.","scoring_points":["12의 ⟨1/4⟩을 3이라고 구했는가","⟨3/4⟩은 ⟨1/4⟩이 3개라고 썼는가","12의 ⟨3/4⟩을 9라고 구했는가"]},"explanation":["12 ÷ 4 = 3이에요.","3이 3부분이에요.","12의 ⟨3/4⟩은 9예요."],"asset":{"type":"fbar","bars":[{"den":12,"num":9,"grp":3,"label":"0부터 12까지"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L05_basic#1','math',3,2,'u4','L05','tb_g3_2_math_u4_L05_basic','lesson_basic','M3-2-u4-C5',1,'mc','auto','바람개비 한 개를 만드는 데 수수깡 ⟨1/3⟩개가 필요해요. 바람개비 4개를 만드는 데 필요한 수수깡은 몇 개인지 분수로 나타내면 무엇인가요?',ARRAY['M3-2-u4-X03','M3-2-u4-X07']::text[],true,'{"seq":1,"concept":"M3-2-u4-C5","difficulty":1,"kind":"mc","stem":"바람개비 한 개를 만드는 데 수수깡 ⟨1/3⟩개가 필요해요. 바람개비 4개를 만드는 데 필요한 수수깡은 몇 개인지 분수로 나타내면 무엇인가요?","options":[{"t":"⟨4/3⟩개","correct":true},{"t":"⟨3/4⟩개","mis":"M3-2-u4-X03"},{"t":"⟨1/12⟩개","mis":"M3-2-u4-X07"}],"explanation":["⟨1/3⟩이 1개, 2개, 3개, 4개이면 ⟨1/3⟩, ⟨2/3⟩, ⟨3/3⟩, ⟨4/3⟩예요.","단위분수의 개수가 분자 — 분모 3은 그대로예요.","그래서 수수깡은 ⟨4/3⟩개 — 분자가 분모보다 큰 가분수예요."],"asset":{"type":"fbar","bars":[{"den":3,"num":3},{"den":3,"num":1,"label":"수수깡 ⟨1/3⟩개씩 4개"}]},"variant_rule":{"alt":[{"stem":"「익힘」 바람개비 한 개를 만드는 데 수수깡 ⟨1/2⟩개가 필요해요. 바람개비 3개를 만드는 데 필요한 수수깡은 몇 개인지 분수로 나타내면 무엇인가요?","options":[{"t":"⟨3/2⟩개","correct":true},{"t":"⟨2/3⟩개","mis":"M3-2-u4-X03"},{"t":"⟨1/6⟩개","mis":"M3-2-u4-X07"}],"explanation":["⟨1/2⟩이 1개, 2개, 3개이면 ⟨1/2⟩, ⟨2/2⟩, ⟨3/2⟩이에요.","단위분수의 개수가 분자 — 분모 2는 그대로예요.","그래서 수수깡은 ⟨3/2⟩개예요."],"asset":{"type":"fbar","bars":[{"den":2,"num":2},{"den":2,"num":1,"label":"수수깡 ⟨1/2⟩개씩 3개"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L05_basic#2','math',3,2,'u4','L05','tb_g3_2_math_u4_L05_basic','lesson_basic','M3-2-u4-C5',1,'mc','auto','분수 ⟨4/3⟩는 진분수, 가분수, 대분수, 자연수 중 무엇인가요?',ARRAY['M3-2-u4-X08']::text[],true,'{"seq":2,"concept":"M3-2-u4-C5","difficulty":1,"kind":"mc","stem":"분수 ⟨4/3⟩는 진분수, 가분수, 대분수, 자연수 중 무엇인가요?","options":[{"t":"가분수","correct":true},{"t":"진분수","mis":"M3-2-u4-X08"},{"t":"대분수","mis":"M3-2-u4-X08"},{"t":"자연수","mis":"M3-2-u4-X08"}],"explanation":["분자 4와 분모 3을 견주어요.","분자가 분모보다 커요.","⟨4/3⟩는 가분수예요."],"variant_rule":{"alt":[{"stem":"분수 ⟨2/10⟩는 진분수, 가분수, 대분수, 자연수 중 무엇인가요?","options":[{"t":"진분수","correct":true},{"t":"가분수","mis":"M3-2-u4-X08"},{"t":"대분수","mis":"M3-2-u4-X08"},{"t":"자연수","mis":"M3-2-u4-X08"}],"explanation":["분자 2와 분모 10을 견주어요.","분자가 분모보다 작아요.","⟨2/10⟩는 진분수예요."]},{"stem":"분수 ⟨8/8⟩은 진분수, 가분수, 대분수, 자연수 중 무엇인가요?","options":[{"t":"가분수","correct":true},{"t":"진분수","mis":"M3-2-u4-X08"},{"t":"대분수","mis":"M3-2-u4-X08"},{"t":"자연수","mis":"M3-2-u4-X24"}],"explanation":["분자 8과 분모 8을 견주어요.","분자가 분모보다 같아요.","⟨8/8⟩은 가분수예요. 1과 크기가 같아도 꼴은 가분수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L05_basic#3','math',3,2,'u4','L05','tb_g3_2_math_u4_L05_basic','lesson_basic','M3-2-u4-C6',1,'sa','auto','자연수 1을 분모가 4인 가분수 ⟨□/4⟩로 나타낼 때 □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u4-C6","difficulty":1,"kind":"sa","stem":"자연수 1을 분모가 4인 가분수 ⟨□/4⟩로 나타낼 때 □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["⟨1/4⟩이 4개이면 1이에요.","분모 4는 그대로, 분자는 ⟨1/4⟩의 개수 4예요.","1 = ⟨4/4⟩ — □는 4예요."],"variant_rule":{"alt":[{"stem":"자연수 2를 분모가 4인 가분수 ⟨□/4⟩로 나타낼 때 □에 알맞은 수를 쓰세요.","answer":["8"],"explanation":["1 = ⟨4/4⟩ — ⟨1/4⟩이 4개예요.","2는 1이 2개 — ⟨1/4⟩이 4 × 2 = 8개예요.","2 = ⟨8/4⟩ — □는 8이에요."]},{"stem":"「익힘」 정사각형 2개를 각각 똑같이 8조각으로 나누었어요. 2 = ⟨□/8⟩일 때 □에 알맞은 수를 쓰세요.","answer":["16"],"explanation":["1 = ⟨8/8⟩ — ⟨1/8⟩이 8개예요.","2는 1이 2개 — ⟨1/8⟩이 8 × 2 = 16개예요.","2 = ⟨16/8⟩ — □는 16이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L05_basic#4','math',3,2,'u4','L05','tb_g3_2_math_u4_L05_basic','lesson_basic','M3-2-u4-C5',1,'mc','auto','분모가 3인 분수를 수직선에 왼쪽부터 차례대로 썼어요. ?에 알맞은 분수는 무엇인가요?',ARRAY['M3-2-u4-X03','M3-2-u4-X21']::text[],true,'{"seq":4,"concept":"M3-2-u4-C5","difficulty":1,"kind":"mc","stem":"분모가 3인 분수를 수직선에 왼쪽부터 차례대로 썼어요. ?에 알맞은 분수는 무엇인가요?","options":[{"t":"⟨3/3⟩","correct":true},{"t":"⟨3/1⟩","mis":"M3-2-u4-X03"},{"t":"⟨4/3⟩","mis":"M3-2-u4-X21"},{"t":"⟨2/3⟩","mis":"M3-2-u4-X21"}],"explanation":["한 칸이 ⟨1/3⟩ — 오른쪽으로 갈 때마다 분자가 1씩 커져요.","?는 ⟨1/3⟩이 3개인 자리 — ⟨3/3⟩이에요.","⟨3/3⟩은 1과 같아요 — 분모는 그대로 3이에요."],"asset":{"type":"number_line","cells":["0","⟨1/3⟩","⟨2/3⟩","?","⟨4/3⟩","⟨5/3⟩"]},"variant_rule":{"alt":[{"stem":"「익힘」 분모가 5인 분수를 수직선에 차례대로 썼어요. ?에 알맞은 분수는 무엇인가요?","options":[{"t":"⟨8/5⟩","correct":true},{"t":"⟨5/8⟩","mis":"M3-2-u4-X03"},{"t":"⟨9/5⟩","mis":"M3-2-u4-X21"},{"t":"⟨7/5⟩","mis":"M3-2-u4-X21"}],"explanation":["한 칸이 ⟨1/5⟩ — 오른쪽으로 갈 때마다 분자가 1씩 커져요.","?는 ⟨1/5⟩이 8개인 자리예요.","?는 ⟨8/5⟩이에요."],"asset":{"type":"number_line","cells":["⟨5/5⟩","⟨6/5⟩","⟨7/5⟩","?","⟨9/5⟩","⟨10/5⟩"]}},{"stem":"분모가 4인 분수를 수직선에 차례대로 썼어요. ?에 알맞은 분수는 무엇인가요?","options":[{"t":"⟨7/4⟩","correct":true},{"t":"⟨4/7⟩","mis":"M3-2-u4-X03"},{"t":"⟨8/4⟩","mis":"M3-2-u4-X21"},{"t":"⟨6/4⟩","mis":"M3-2-u4-X21"}],"explanation":["한 칸이 ⟨1/4⟩ — 오른쪽으로 갈 때마다 분자가 1씩 커져요.","?는 ⟨1/4⟩이 7개인 자리예요.","?는 ⟨7/4⟩이에요."],"asset":{"type":"number_line","cells":["⟨4/4⟩","⟨5/4⟩","⟨6/4⟩","?","⟨8/4⟩"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L05_basic#5','math',3,2,'u4','L05','tb_g3_2_math_u4_L05_basic','lesson_basic','M3-2-u4-C5',2,'sa','auto','⟨1/5⟩, 2, ⟨13/12⟩, ⟨8/8⟩, ⟨2/10⟩, ⟨7/2⟩ 중에서 가분수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u4-C5","difficulty":2,"kind":"sa","stem":"⟨1/5⟩, 2, ⟨13/12⟩, ⟨8/8⟩, ⟨2/10⟩, ⟨7/2⟩ 중에서 가분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["진분수는 분자가 분모보다 작은 분수, 가분수는 분자가 분모와 같거나 큰 분수예요.","가분수: ⟨13/12⟩, ⟨8/8⟩, ⟨7/2⟩.","모두 3개 — 분자와 분모가 같은 분수도 가분수예요."],"variant_rule":{"alt":[{"stem":"「익힘」 ⟨8/7⟩, ⟨4/4⟩, 4, ⟨7/8⟩, ⟨3/9⟩ 중에서 가분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["진분수는 분자가 분모보다 작은 분수, 가분수는 분자가 분모와 같거나 큰 분수예요.","가분수: ⟨8/7⟩, ⟨4/4⟩.","모두 2개 — 분자와 분모가 같은 분수도 가분수예요."]},{"stem":"「확인 문제」 ⟨6/13⟩, ⟨5/4⟩, ⟨6/8⟩, ⟨25/11⟩, ⟨9/9⟩, ⟨4/3⟩ 중에서 가분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["진분수는 분자가 분모보다 작은 분수, 가분수는 분자가 분모와 같거나 큰 분수예요.","가분수: ⟨5/4⟩, ⟨25/11⟩, ⟨9/9⟩, ⟨4/3⟩.","모두 4개 — 분자와 분모가 같은 분수도 가분수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L05_basic#6','math',3,2,'u4','L05','tb_g3_2_math_u4_L05_basic','lesson_basic','M3-2-u4-C5',2,'mc','auto','⟨1/5⟩, 2, ⟨13/12⟩, ⟨8/8⟩, ⟨2/10⟩, ⟨7/2⟩ 중에서 진분수만 모두 고른 것은 무엇인가요?',ARRAY['M3-2-u4-X08','M3-2-u4-X20']::text[],true,'{"seq":6,"concept":"M3-2-u4-C5","difficulty":2,"kind":"mc","stem":"⟨1/5⟩, 2, ⟨13/12⟩, ⟨8/8⟩, ⟨2/10⟩, ⟨7/2⟩ 중에서 진분수만 모두 고른 것은 무엇인가요?","options":[{"t":"⟨1/5⟩, ⟨2/10⟩","correct":true},{"t":"⟨1/5⟩, ⟨2/10⟩, ⟨8/8⟩","mis":"M3-2-u4-X08"},{"t":"⟨13/12⟩, ⟨8/8⟩, ⟨7/2⟩","mis":"M3-2-u4-X20"},{"t":"⟨1/5⟩, 2, ⟨2/10⟩","mis":"M3-2-u4-X08"}],"explanation":["진분수는 분자가 분모보다 작은 분수예요.","⟨1/5⟩, ⟨2/10⟩는 분자가 분모보다 작아요.","⟨8/8⟩은 분자와 분모가 같은 가분수, 2는 자연수예요."],"variant_rule":{"alt":[{"stem":"「확인 문제」 ⟨6/13⟩, ⟨5/4⟩, ⟨6/8⟩, ⟨25/11⟩, ⟨9/9⟩, ⟨4/3⟩ 중에서 진분수만 모두 고른 것은 무엇인가요?","options":[{"t":"⟨6/13⟩, ⟨6/8⟩","correct":true},{"t":"⟨6/13⟩, ⟨6/8⟩, ⟨9/9⟩","mis":"M3-2-u4-X08"},{"t":"⟨5/4⟩, ⟨25/11⟩, ⟨4/3⟩","mis":"M3-2-u4-X20"},{"t":"⟨6/13⟩, ⟨5/4⟩, ⟨6/8⟩","mis":"M3-2-u4-X08"}],"explanation":["진분수는 분자가 분모보다 작은 분수예요.","⟨6/13⟩, ⟨6/8⟩은 분자가 분모보다 작아요.","⟨9/9⟩는 분자와 분모가 같은 가분수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L05_basic#7','math',3,2,'u4','L05','tb_g3_2_math_u4_L05_basic','lesson_basic','M3-2-u4-C5',2,'mc','auto','가분수를 바르게 설명한 것은 무엇인가요?',ARRAY['M3-2-u4-X08']::text[],true,'{"seq":7,"concept":"M3-2-u4-C5","difficulty":2,"kind":"mc","stem":"가분수를 바르게 설명한 것은 무엇인가요?","options":[{"t":"분자가 분모와 같거나 분모보다 큰 분수","correct":true},{"t":"분자가 분모보다 작은 분수","mis":"M3-2-u4-X08"},{"t":"1보다 작은 분수","mis":"M3-2-u4-X08"},{"t":"자연수와 진분수로 이루어진 분수","mis":"M3-2-u4-X08"}],"explanation":["⟨3/3⟩, ⟨4/3⟩와 같이 분자가 분모와 같거나 분모보다 큰 분수를 가분수라고 해요.","분자가 분모보다 작은 분수는 진분수예요.","가분수는 1과 같거나 1보다 커요."],"variant_rule":{"alt":[{"stem":"「익힘」 진분수를 바르게 설명한 것은 무엇인가요?","options":[{"t":"분자가 분모보다 작은 분수로 0보다 크고 1보다 작아요","correct":true},{"t":"분자가 분모와 같거나 분모보다 큰 분수예요","mis":"M3-2-u4-X08"},{"t":"1과 같거나 1보다 큰 분수예요","mis":"M3-2-u4-X08"},{"t":"자연수와 진분수로 이루어진 분수예요","mis":"M3-2-u4-X08"}],"explanation":["진분수에서 「진」은 「참 진(眞)」이에요.","⟨1/3⟩, ⟨2/3⟩와 같이 분자가 분모보다 작은 분수가 진분수예요.","진분수는 0보다 크고 1보다 작아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L05_basic#8','math',3,2,'u4','L05','tb_g3_2_math_u4_L05_basic','lesson_basic','M3-2-u4-C5',2,'ox','auto','건우는 「⟨4/4⟩는 1과 같으니까 가분수가 아니라 자연수야.」라고 했어요. 건우의 말이 옳은가요?',ARRAY['M3-2-u4-X24']::text[],true,'{"seq":8,"concept":"M3-2-u4-C5","difficulty":2,"kind":"ox","stem":"건우는 「⟨4/4⟩는 1과 같으니까 가분수가 아니라 자연수야.」라고 했어요. 건우의 말이 옳은가요?","answer":"X","reason_options":[{"t":"분자가 분모와 같은 분수는 가분수라서","correct":true},{"t":"1과 크기가 같으니까","mis":"M3-2-u4-X24"}],"mis":"M3-2-u4-X24","explanation":["⟨4/4⟩는 분자와 분모가 같은 분수예요.","분자가 분모와 같거나 크면 가분수 — ⟨4/4⟩는 가분수예요.","⟨4/4⟩ = 1처럼 크기가 같아도 꼴은 가분수, 자연수는 1, 2, 3처럼 쓴 수예요."],"variant_rule":{"alt":[{"stem":"은비는 「⟨8/8⟩은 분자가 분모보다 작지 않으니까 가분수야.」라고 했어요. 은비의 말이 옳은가요?","answer":"O","reason_options":[{"t":"분자와 분모가 같은 분수도 가분수라서","correct":true},{"t":"1과 크기가 같으니까 자연수라서","mis":"M3-2-u4-X24"}],"explanation":["⟨8/8⟩은 분자와 분모가 같은 분수예요.","분자가 분모와 같거나 크면 가분수예요.","⟨8/8⟩은 1과 크기가 같은 가분수 — 은비의 말이 옳아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L05_basic#9','math',3,2,'u4','L05','tb_g3_2_math_u4_L05_basic','lesson_basic','M3-2-u4-C6',2,'mc','auto','자연수 2를 분모가 4인 가분수로 바르게 나타낸 것은 무엇인가요?',ARRAY['M3-2-u4-X09','M3-2-u4-X03','M3-2-u4-X10']::text[],true,'{"seq":9,"concept":"M3-2-u4-C6","difficulty":2,"kind":"mc","stem":"자연수 2를 분모가 4인 가분수로 바르게 나타낸 것은 무엇인가요?","options":[{"t":"⟨8/4⟩","correct":true},{"t":"⟨2/4⟩","mis":"M3-2-u4-X09"},{"t":"⟨4/8⟩","mis":"M3-2-u4-X03"},{"t":"⟨6/4⟩","mis":"M3-2-u4-X10"}],"explanation":["⟨1/4⟩이 4개이면 1이에요 — 1 = ⟨4/4⟩.","2는 1이 2개 — ⟨1/4⟩이 4 × 2 = 8개예요.","2 = ⟨8/4⟩ — 자연수를 그대로 분자에 쓰지 않아요."],"variant_rule":{"alt":[{"stem":"「익힘」 자연수 2를 분모가 8인 가분수로 바르게 나타낸 것은 무엇인가요?","options":[{"t":"⟨16/8⟩","correct":true},{"t":"⟨2/8⟩","mis":"M3-2-u4-X09"},{"t":"⟨8/16⟩","mis":"M3-2-u4-X03"},{"t":"⟨10/8⟩","mis":"M3-2-u4-X10"}],"explanation":["⟨1/8⟩이 8개이면 1이에요 — 1 = ⟨8/8⟩.","2는 1이 2개 — ⟨1/8⟩이 8 × 2 = 16개예요.","2 = ⟨16/8⟩ — 자연수를 그대로 분자에 쓰지 않아요."]},{"stem":"「익힘」 자연수 1을 분모가 6인 가분수로 바르게 나타낸 것은 무엇인가요?","options":[{"t":"⟨6/6⟩","correct":true},{"t":"⟨1/6⟩","mis":"M3-2-u4-X09"},{"t":"⟨7/6⟩","mis":"M3-2-u4-X10"},{"t":"⟨5/6⟩","mis":"M3-2-u4-X21"}],"explanation":["⟨1/6⟩이 6개이면 1이에요 — 1 = ⟨6/6⟩.","자연수 1은 분자와 분모가 같은 가분수로 나타내요.","1 = ⟨6/6⟩ — 자연수를 그대로 분자에 쓰지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L05_basic#10','math',3,2,'u4','L05','tb_g3_2_math_u4_L05_basic','lesson_basic','M3-2-u4-C5',3,'sa','auto','「익힘」 수 카드 4, 4, 5, 9 중에서 2장을 뽑아 한 번씩만 사용하여 가분수를 만들려고 해요. 만들 수 있는 가분수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u4-C5","difficulty":3,"kind":"sa","stem":"「익힘」 수 카드 4, 4, 5, 9 중에서 2장을 뽑아 한 번씩만 사용하여 가분수를 만들려고 해요. 만들 수 있는 가분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["가분수는 분자가 분모와 같거나 분모보다 커요.","분모 4: ⟨4/4⟩, ⟨5/4⟩, ⟨9/4⟩ · 분모 5: ⟨9/5⟩ · 분모 9: 없어요.","모두 4개 — 4가 2장이라 ⟨4/4⟩도 만들 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L05_challenge#1','math',3,2,'u4','L05','tb_g3_2_math_u4_L05_challenge','lesson_challenge','M3-2-u4-C5',2,'sa','auto','「익힘」 0부터 2까지의 수직선에서 0과 1 사이가 똑같이 4칸으로 나뉘어 있어요. ⟨7/4⟩만큼 색칠하려면 모두 몇 칸을 색칠해야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u4-C5","difficulty":2,"kind":"sa","stem":"「익힘」 0부터 2까지의 수직선에서 0과 1 사이가 똑같이 4칸으로 나뉘어 있어요. ⟨7/4⟩만큼 색칠하려면 모두 몇 칸을 색칠해야 하나요? 숫자로 쓰세요.","answer":["7"],"explanation":["한 칸은 ⟨1/4⟩이에요.","⟨7/4⟩은 ⟨1/4⟩이 7개예요.","모두 7칸 — 1을 지나 3칸 더 색칠해요."],"variant_rule":{"alt":[{"stem":"「익힘」 0부터 2까지의 수직선에서 0과 1 사이가 똑같이 4칸으로 나뉘어 있어요. ⟨3/4⟩만큼 색칠하려면 모두 몇 칸을 색칠해야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["한 칸은 ⟨1/4⟩이에요.","⟨3/4⟩은 ⟨1/4⟩이 3개예요.","모두 3칸 — 1보다 작아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L05_challenge#2','math',3,2,'u4','L05','tb_g3_2_math_u4_L05_challenge','lesson_challenge','M3-2-u4-C5',2,'mc','auto','「확인 문제」 1을 똑같이 4로 나눈 띠 2개 중 7칸을 색칠했어요. 색칠한 부분을 분수로 나타내면 무엇인가요?',ARRAY['M3-2-u4-X02','M3-2-u4-X03','M3-2-u4-X12']::text[],false,'{"seq":2,"concept":"M3-2-u4-C5","difficulty":2,"kind":"mc","stem":"「확인 문제」 1을 똑같이 4로 나눈 띠 2개 중 7칸을 색칠했어요. 색칠한 부분을 분수로 나타내면 무엇인가요?","options":[{"t":"⟨7/4⟩","correct":true},{"t":"⟨7/8⟩","mis":"M3-2-u4-X02"},{"t":"⟨4/7⟩","mis":"M3-2-u4-X03"},{"t":"⟨3/4⟩","mis":"M3-2-u4-X12"}],"explanation":["띠 하나가 1 — 한 칸은 ⟨1/4⟩이에요.","색칠한 칸은 ⟨1/4⟩이 7개예요.","그래서 ⟨7/4⟩ — 띠 2개를 합쳐 8칸 중 7칸으로 보지 않아요."],"asset":{"type":"fbar","bars":[{"den":4,"num":4},{"den":4,"num":3}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L05_challenge#3','math',3,2,'u4','L05','tb_g3_2_math_u4_L05_challenge','lesson_challenge','M3-2-u4-C5',3,'sa','auto','「스스로 마무리하기」 주사위를 두 번 던져 처음 나온 수를 분모로, 나중 나온 수를 분자로 하여 분수를 만들어요. 처음에 4가 나왔을 때 만들 수 있는 가분수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u4-C5","difficulty":3,"kind":"sa","stem":"「스스로 마무리하기」 주사위를 두 번 던져 처음 나온 수를 분모로, 나중 나온 수를 분자로 하여 분수를 만들어요. 처음에 4가 나왔을 때 만들 수 있는 가분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["주사위의 수는 1부터 6까지예요.","분모 4인 가분수는 분자가 4와 같거나 커야 해요 — ⟨4/4⟩, ⟨5/4⟩, ⟨6/4⟩.","모두 3개예요."],"variant_rule":{"alt":[{"stem":"「스스로 마무리하기」 주사위를 두 번 던져 처음 나온 수를 분모로, 나중 나온 수를 분자로 하여 분수를 만들어요. 처음에 4가 나왔을 때 만들 수 있는 진분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["주사위의 수는 1부터 6까지예요.","분모 4인 진분수는 분자가 4보다 작아야 해요 — ⟨1/4⟩, ⟨2/4⟩, ⟨3/4⟩.","모두 3개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L05_challenge#4','math',3,2,'u4','L05','tb_g3_2_math_u4_L05_challenge','lesson_challenge','M3-2-u4-C5',3,'error','auto','진분수, 가분수, 자연수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u4-X24','M3-2-u4-X20']::text[],true,'{"seq":4,"concept":"M3-2-u4-C5","difficulty":3,"kind":"error","stem":"진분수, 가분수, 자연수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서준 — 「⟨8/8⟩은 1과 같으니까 자연수야」","correct":true,"mis_target":"M3-2-u4-X24"},{"t":"채원 — 「1은 ⟨4/4⟩와 같아」","mis":"M3-2-u4-X20"},{"t":"도윤 — 「2는 ⟨8/4⟩로 나타낼 수 있어」","mis":"M3-2-u4-X20"}],"explanation":["1 = ⟨4/4⟩, 2 = ⟨8/4⟩이에요.","⟨8/8⟩은 1과 크기가 같은 가분수예요.","서준이는 크기가 같은 가분수를 자연수라고 했어요."],"variant_rule":{"alt":[{"stem":"진분수와 가분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하윤 — 「⟨4/4⟩는 분자가 분모보다 크지 않으니까 진분수야」","correct":true,"mis_target":"M3-2-u4-X08"},{"t":"지유 — 「⟨5/4⟩는 가분수야」","mis":"M3-2-u4-X20"},{"t":"준우 — 「⟨3/4⟩은 진분수야」","mis":"M3-2-u4-X20"}],"explanation":["진분수는 분자가 분모보다 작은 분수예요.","분자가 분모와 같으면 가분수예요 — ⟨4/4⟩는 가분수예요.","하윤이는 진분수의 뜻을 헷갈렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L05_challenge#5','math',3,2,'u4','L05','tb_g3_2_math_u4_L05_challenge','lesson_challenge','M3-2-u4-C6',3,'sa','auto','「익힘」 ⟨10/5⟩은 자연수 얼마와 같나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u4-C6","difficulty":3,"kind":"sa","stem":"「익힘」 ⟨10/5⟩은 자연수 얼마와 같나요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨5/5⟩ = 1 — ⟨1/5⟩이 5개이면 1이에요.","⟨10/5⟩은 ⟨1/5⟩이 10개 — 5개씩 2번이에요.","⟨10/5⟩ = 2예요."],"variant_rule":{"alt":[{"stem":"「익힘」 ⟨16/8⟩은 자연수 얼마와 같나요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨8/8⟩ = 1 — ⟨1/8⟩이 8개이면 1이에요.","⟨16/8⟩은 ⟨1/8⟩이 16개 — 8개씩 2번이에요.","⟨16/8⟩ = 2예요."]},{"stem":"⟨9/3⟩는 자연수 얼마와 같나요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨3/3⟩ = 1 — ⟨1/3⟩이 3개이면 1이에요.","⟨9/3⟩는 ⟨1/3⟩이 9개 — 3개씩 3번이에요.","⟨9/3⟩ = 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L05_challenge#6','math',3,2,'u4','L05','tb_g3_2_math_u4_L05_challenge','lesson_challenge','M3-2-u4-C5',3,'mc','auto','분모가 4인 분수 ⟨1/4⟩, ⟨2/4⟩, ⟨3/4⟩, ⟨4/4⟩, ⟨5/4⟩, ⟨6/4⟩, ⟨7/4⟩, ⟨8/4⟩ 중에서 가분수를 모두 고른 것은 무엇인가요?',ARRAY['M3-2-u4-X24','M3-2-u4-X20']::text[],false,'{"seq":6,"concept":"M3-2-u4-C5","difficulty":3,"kind":"mc","stem":"분모가 4인 분수 ⟨1/4⟩, ⟨2/4⟩, ⟨3/4⟩, ⟨4/4⟩, ⟨5/4⟩, ⟨6/4⟩, ⟨7/4⟩, ⟨8/4⟩ 중에서 가분수를 모두 고른 것은 무엇인가요?","options":[{"t":"⟨4/4⟩, ⟨5/4⟩, ⟨6/4⟩, ⟨7/4⟩, ⟨8/4⟩","correct":true},{"t":"⟨5/4⟩, ⟨6/4⟩, ⟨7/4⟩","mis":"M3-2-u4-X24"},{"t":"⟨1/4⟩, ⟨2/4⟩, ⟨3/4⟩","mis":"M3-2-u4-X20"},{"t":"⟨5/4⟩, ⟨6/4⟩, ⟨7/4⟩, ⟨8/4⟩","mis":"M3-2-u4-X24"}],"explanation":["분자가 분모 4와 같거나 4보다 크면 가분수예요.","⟨4/4⟩ = 1, ⟨8/4⟩ = 2처럼 자연수와 크기가 같아도 가분수예요.","가분수는 ⟨4/4⟩부터 ⟨8/4⟩까지 5개예요."],"asset":{"type":"number_line","cells":["⟨1/4⟩","⟨2/4⟩","⟨3/4⟩","⟨4/4⟩","⟨5/4⟩","⟨6/4⟩","⟨7/4⟩","⟨8/4⟩"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L05_challenge#7','math',3,2,'u4','L05','tb_g3_2_math_u4_L05_challenge','lesson_challenge','M3-2-u4-C5',3,'mc','auto','「익힘」 가분수에서 「가」의 뜻과 가분수의 크기를 바르게 말한 것은 무엇인가요?',ARRAY['M3-2-u4-X08']::text[],false,'{"seq":7,"concept":"M3-2-u4-C5","difficulty":3,"kind":"mc","stem":"「익힘」 가분수에서 「가」의 뜻과 가분수의 크기를 바르게 말한 것은 무엇인가요?","options":[{"t":"「거짓 가(假)」 — 1과 같거나 1보다 커요","correct":true},{"t":"「큰 가」 — 1보다 작아요","mis":"M3-2-u4-X08"},{"t":"「참 가」 — 0보다 크고 1보다 작아요","mis":"M3-2-u4-X08"},{"t":"「거짓 가(假)」 — 0보다 크고 1보다 작아요","mis":"M3-2-u4-X08"}],"explanation":["가분수의 「가」는 「거짓 가(假)」로 임시로 만든 분수라는 뜻이에요.","가분수는 분자가 분모와 같거나 분모보다 커요.","그래서 가분수는 1과 같거나 1보다 커요 — 수학에서 틀린 분수라는 뜻은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L05_challenge#8','math',3,2,'u4','L05','tb_g3_2_math_u4_L05_challenge','lesson_challenge','M3-2-u4-C5',4,'sa','auto','「익힘」 수 카드 4, 4, 5, 9 중에서 2장을 뽑아 한 번씩만 사용하여 진분수를 만들려고 해요. 만들 수 있는 진분수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u4-C5","difficulty":4,"kind":"sa","stem":"「익힘」 수 카드 4, 4, 5, 9 중에서 2장을 뽑아 한 번씩만 사용하여 진분수를 만들려고 해요. 만들 수 있는 진분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["진분수는 분자가 분모보다 작아요.","분모 5: ⟨4/5⟩ · 분모 9: ⟨4/9⟩, ⟨5/9⟩ · 분모 4: 없어요.","모두 3개 — 같은 4를 두 번 쓴 ⟨4/4⟩는 가분수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L05_challenge#9','math',3,2,'u4','L05','tb_g3_2_math_u4_L05_challenge','lesson_challenge','M3-2-u4-C6',4,'essay','teacher','자연수 1과 2를 분모가 4인 가분수로 나타내고, 그 방법을 이야기해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u4-C6","difficulty":4,"kind":"essay","stem":"자연수 1과 2를 분모가 4인 가분수로 나타내고, 그 방법을 이야기해 보세요.","answer_guide":{"answer":"예: ⟨1/4⟩이 4개이면 1이므로 1 = ⟨4/4⟩이다. 2는 1이 2개이므로 ⟨1/4⟩이 8개이고 2 = ⟨8/4⟩이다. 분모는 그대로 4로 두고 ⟨1/4⟩이 몇 개인지 세어 분자로 쓴다.","scoring_points":["1 = ⟨4/4⟩를 썼는가","2 = ⟨8/4⟩을 썼는가","⟨1/4⟩의 개수를 분자로 쓴다고 설명했는가"]},"explanation":["1 = ⟨4/4⟩예요.","2 = ⟨8/4⟩이에요.","분모는 그대로, 분자는 단위분수의 개수예요."],"asset":{"type":"number_line","cells":["0","⟨1/4⟩","⟨2/4⟩","⟨3/4⟩","1","⟨5/4⟩","⟨6/4⟩","⟨7/4⟩","2"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L05_challenge#10','math',3,2,'u4','L05','tb_g3_2_math_u4_L05_challenge','lesson_challenge','M3-2-u4-C5',4,'essay','teacher','바람개비 한 개를 만드는 데 수수깡 ⟨1/3⟩개가 필요해요. 바람개비 4개를 만드는 데 필요한 수수깡을 분수로 나타내고, 그 분수가 진분수인지 가분수인지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u4-C5","difficulty":4,"kind":"essay","stem":"바람개비 한 개를 만드는 데 수수깡 ⟨1/3⟩개가 필요해요. 바람개비 4개를 만드는 데 필요한 수수깡을 분수로 나타내고, 그 분수가 진분수인지 가분수인지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: ⟨1/3⟩이 4개이므로 필요한 수수깡은 ⟨4/3⟩개이다. 단위분수의 개수가 분자가 되기 때문이다. ⟨4/3⟩는 분자 4가 분모 3보다 크므로 가분수이다.","scoring_points":["⟨4/3⟩개라고 썼는가","단위분수의 개수가 분자라고 설명했는가","분자가 분모보다 커서 가분수라고 썼는가"]},"explanation":["⟨1/3⟩이 4개예요.","⟨4/3⟩개예요.","분자가 분모보다 크니 가분수예요."],"asset":{"type":"fbar","bars":[{"den":3,"num":3},{"den":3,"num":1}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L06_basic#1','math',3,2,'u4','L06','tb_g3_2_math_u4_L06_basic','lesson_basic','M3-2-u4-C7',1,'mc','auto','⟨1 2/3⟩를 바르게 읽은 것은 무엇인가요?',ARRAY['M3-2-u4-X03','M3-2-u4-X16','M3-2-u4-X12']::text[],true,'{"seq":1,"concept":"M3-2-u4-C7","difficulty":1,"kind":"mc","stem":"⟨1 2/3⟩를 바르게 읽은 것은 무엇인가요?","options":[{"t":"일과 삼분의 이","correct":true},{"t":"일과 이분의 삼","mis":"M3-2-u4-X03"},{"t":"일 점 이삼","mis":"M3-2-u4-X16"},{"t":"삼분의 이","mis":"M3-2-u4-X12"}],"explanation":["대분수는 자연수 부분을 먼저 읽고 「과(와)」를 붙여요.","분수 부분은 분모부터 「○분의 △」로 읽어요.","⟨1 2/3⟩는 「일과 삼분의 이」라고 읽어요."],"variant_rule":{"alt":[{"stem":"⟨1 1/5⟩을 바르게 읽은 것은 무엇인가요?","options":[{"t":"일과 오분의 일","correct":true},{"t":"일과 일분의 오","mis":"M3-2-u4-X03"},{"t":"일 점 일오","mis":"M3-2-u4-X16"},{"t":"오분의 일","mis":"M3-2-u4-X12"}],"explanation":["대분수는 자연수 부분을 먼저 읽고 「과(와)」를 붙여요.","분수 부분은 분모부터 「○분의 △」로 읽어요.","⟨1 1/5⟩은 「일과 오분의 일」이라고 읽어요."]},{"stem":"「익힘」 ⟨2 3/5⟩을 바르게 읽은 것은 무엇인가요?","options":[{"t":"이와 오분의 삼","correct":true},{"t":"이와 삼분의 오","mis":"M3-2-u4-X03"},{"t":"이 점 삼오","mis":"M3-2-u4-X16"},{"t":"오분의 삼","mis":"M3-2-u4-X12"}],"explanation":["대분수는 자연수 부분을 먼저 읽고 「과(와)」를 붙여요.","분수 부분은 분모부터 「○분의 △」로 읽어요.","⟨2 3/5⟩은 「이와 오분의 삼」이라고 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L06_basic#2','math',3,2,'u4','L06','tb_g3_2_math_u4_L06_basic','lesson_basic','M3-2-u4-C7',1,'mc','auto','친구들과 바람개비를 만들었더니 수수깡이 1개와 ⟨2/3⟩개가 남았어요. 남은 수수깡은 몇 개인지 대분수로 나타내면 무엇인가요?',ARRAY['M3-2-u4-X12','M3-2-u4-X21','M3-2-u4-X03']::text[],true,'{"seq":2,"concept":"M3-2-u4-C7","difficulty":1,"kind":"mc","stem":"친구들과 바람개비를 만들었더니 수수깡이 1개와 ⟨2/3⟩개가 남았어요. 남은 수수깡은 몇 개인지 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨1 2/3⟩개","correct":true},{"t":"⟨2/3⟩개","mis":"M3-2-u4-X12"},{"t":"⟨2 2/3⟩개","mis":"M3-2-u4-X21"},{"t":"⟨1 3/2⟩개","mis":"M3-2-u4-X03"}],"explanation":["수수깡 1개는 자연수 1이에요.","남은 ⟨2/3⟩개는 진분수예요.","1과 ⟨2/3⟩는 ⟨1 2/3⟩이라 쓰고 「일과 삼분의 이」라고 읽어요."],"asset":{"type":"fbar","bars":[{"den":3,"num":3},{"den":3,"num":2}]},"variant_rule":{"alt":[{"stem":"「익힘」 친구들과 바람개비를 만들었더니 수수깡 1개와 ⟨1/2⟩개가 남았어요. 남은 수수깡은 몇 개인지 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨1 1/2⟩개","correct":true},{"t":"⟨1/2⟩개","mis":"M3-2-u4-X12"},{"t":"⟨2 1/2⟩개","mis":"M3-2-u4-X21"},{"t":"⟨1 2/2⟩개","mis":"M3-2-u4-X21"}],"explanation":["수수깡 1개는 자연수 1이에요.","남은 ⟨1/2⟩개는 진분수예요.","1과 ⟨1/2⟩은 ⟨1 1/2⟩이에요."],"asset":{"type":"fbar","bars":[{"den":2,"num":2},{"den":2,"num":1}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L06_basic#3','math',3,2,'u4','L06','tb_g3_2_math_u4_L06_basic','lesson_basic','M3-2-u4-C7',1,'sa','auto','⟨2 3/4⟩을 가분수 ⟨□/4⟩로 나타낼 때 □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u4-C7","difficulty":1,"kind":"sa","stem":"⟨2 3/4⟩을 가분수 ⟨□/4⟩로 나타낼 때 □에 알맞은 수를 쓰세요.","answer":["11"],"explanation":["2는 ⟨1/4⟩이 8개예요.","⟨3/4⟩은 ⟨1/4⟩이 3개 — 모두 8 + 3 = 11개예요.","⟨2 3/4⟩ = ⟨11/4⟩ — □는 11이에요."],"asset":{"type":"fbar","bars":[{"den":4,"num":4},{"den":4,"num":4},{"den":4,"num":3}]},"variant_rule":{"alt":[{"stem":"⟨3 1/3⟩을 가분수 ⟨□/3⟩으로 나타낼 때 □에 알맞은 수를 쓰세요.","answer":["10"],"explanation":["3은 ⟨1/3⟩이 9개예요 — 3 = ⟨9/3⟩.","⟨1/3⟩이 1개 더 — 모두 9 + 1 = 10개예요.","⟨3 1/3⟩ = ⟨10/3⟩ — □는 10이에요."],"asset":null},{"stem":"⟨1 5/9⟩를 가분수 ⟨□/9⟩로 나타낼 때 □에 알맞은 수를 쓰세요.","answer":["14"],"explanation":["1은 ⟨1/9⟩이 9개예요 — 1 = ⟨9/9⟩.","⟨5/9⟩는 ⟨1/9⟩이 5개 — 모두 9 + 5 = 14개예요.","⟨1 5/9⟩ = ⟨14/9⟩ — □는 14예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L06_basic#4','math',3,2,'u4','L06','tb_g3_2_math_u4_L06_basic','lesson_basic','M3-2-u4-C7',1,'sa','auto','⟨17/5⟩을 대분수로 나타내면 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u4-C7","difficulty":1,"kind":"sa","stem":"⟨17/5⟩을 대분수로 나타내면 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨17/5⟩은 ⟨15/5⟩와 ⟨2/5⟩예요.","⟨15/5⟩ = 3이에요.","⟨17/5⟩ = ⟨3 2/5⟩ — 자연수 부분은 3이에요."],"variant_rule":{"alt":[{"stem":"⟨13/6⟩을 대분수로 나타내면 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨13/6⟩은 ⟨12/6⟩와 ⟨1/6⟩이에요.","⟨12/6⟩ = 2예요.","⟨13/6⟩ = ⟨2 1/6⟩ — 자연수 부분은 2예요."]},{"stem":"⟨5/2⟩를 대분수로 나타내면 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨5/2⟩는 ⟨4/2⟩와 ⟨1/2⟩이에요.","⟨4/2⟩ = 2예요.","⟨5/2⟩ = ⟨2 1/2⟩ — 자연수 부분은 2예요."],"asset":{"type":"fbar","bars":[{"den":2,"num":2},{"den":2,"num":2},{"den":2,"num":1}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L06_basic#5','math',3,2,'u4','L06','tb_g3_2_math_u4_L06_basic','lesson_basic','M3-2-u4-C7',2,'mc','auto','⟨2 3/4⟩을 가분수로 나타낸 것은 무엇인가요?',ARRAY['M3-2-u4-X10','M3-2-u4-X03']::text[],true,'{"seq":5,"concept":"M3-2-u4-C7","difficulty":2,"kind":"mc","stem":"⟨2 3/4⟩을 가분수로 나타낸 것은 무엇인가요?","options":[{"t":"⟨11/4⟩","correct":true},{"t":"⟨7/4⟩","mis":"M3-2-u4-X10"},{"t":"⟨5/4⟩","mis":"M3-2-u4-X10"},{"t":"⟨4/11⟩","mis":"M3-2-u4-X03"}],"explanation":["자연수 2는 ⟨1/4⟩이 8개예요.","⟨3/4⟩은 ⟨1/4⟩이 3개 — 모두 8 + 3 = 11개예요.","⟨2 3/4⟩ = ⟨11/4⟩ — 분모는 그대로 두고 단위분수의 개수를 세어요."],"variant_rule":{"alt":[{"stem":"「확인 문제」 은비는 미역국을 만들기 위해 냄비에 물을 ⟨2 3/4⟩컵 넣었어요. 은비가 넣은 물은 몇 컵인지 가분수로 나타내면 무엇인가요?","options":[{"t":"⟨11/4⟩","correct":true},{"t":"⟨7/4⟩","mis":"M3-2-u4-X10"},{"t":"⟨5/4⟩","mis":"M3-2-u4-X10"},{"t":"⟨4/11⟩","mis":"M3-2-u4-X03"}],"explanation":["자연수 2는 ⟨1/4⟩이 8개예요.","⟨3/4⟩은 ⟨1/4⟩이 3개 — 모두 8 + 3 = 11개예요.","⟨2 3/4⟩ = ⟨11/4⟩ — 분모는 그대로 두고 단위분수의 개수를 세어요."]},{"stem":"「익힘」 ⟨1 1/6⟩을 가분수로 나타낸 것은 무엇인가요?","options":[{"t":"⟨7/6⟩","correct":true},{"t":"⟨2/6⟩","mis":"M3-2-u4-X10"},{"t":"⟨6/7⟩","mis":"M3-2-u4-X03"},{"t":"⟨8/6⟩","mis":"M3-2-u4-X21"}],"explanation":["자연수 1은 ⟨1/6⟩이 6개예요.","⟨1/6⟩은 ⟨1/6⟩이 1개 — 모두 6 + 1 = 7개예요.","⟨1 1/6⟩ = ⟨7/6⟩ — 분모는 그대로 두고 단위분수의 개수를 세어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L06_basic#6','math',3,2,'u4','L06','tb_g3_2_math_u4_L06_basic','lesson_basic','M3-2-u4-C7',2,'mc','auto','⟨5/2⟩를 대분수로 나타낸 것은 무엇인가요?',ARRAY['M3-2-u4-X11','M3-2-u4-X12','M3-2-u4-X21']::text[],true,'{"seq":6,"concept":"M3-2-u4-C7","difficulty":2,"kind":"mc","stem":"⟨5/2⟩를 대분수로 나타낸 것은 무엇인가요?","options":[{"t":"⟨2 1/2⟩","correct":true},{"t":"⟨1 3/2⟩","mis":"M3-2-u4-X11"},{"t":"⟨1/2⟩","mis":"M3-2-u4-X12"},{"t":"⟨3 1/2⟩","mis":"M3-2-u4-X21"}],"explanation":["⟨5/2⟩는 ⟨1/2⟩이 5개예요.","⟨1/2⟩이 2개씩 모이면 1 — 자연수 2만큼 모으고 ⟨1/2⟩이 1개 남아요.","⟨5/2⟩ = ⟨2 1/2⟩ — 분수 부분은 진분수예요."],"variant_rule":{"alt":[{"stem":"「익힘」 ⟨13/8⟩을 대분수로 나타낸 것은 무엇인가요?","options":[{"t":"⟨1 5/8⟩","correct":true},{"t":"⟨5/8⟩","mis":"M3-2-u4-X12"},{"t":"⟨2 5/8⟩","mis":"M3-2-u4-X21"},{"t":"⟨5 1/8⟩","mis":"M3-2-u4-X03"}],"explanation":["⟨13/8⟩은 ⟨1/8⟩이 13개예요.","⟨1/8⟩이 8개씩 모이면 1 — 자연수 1만큼 모으고 ⟨1/8⟩이 5개 남아요.","⟨13/8⟩ = ⟨1 5/8⟩ — 분수 부분은 진분수예요."]},{"stem":"「익힘」 ⟨33/9⟩을 대분수로 나타낸 것은 무엇인가요?","options":[{"t":"⟨3 6/9⟩","correct":true},{"t":"⟨2 15/9⟩","mis":"M3-2-u4-X11"},{"t":"⟨6/9⟩","mis":"M3-2-u4-X12"},{"t":"⟨4 6/9⟩","mis":"M3-2-u4-X21"}],"explanation":["⟨33/9⟩은 ⟨1/9⟩이 33개예요.","⟨1/9⟩이 9개씩 모이면 1 — 자연수 3만큼 모으고 ⟨1/9⟩이 6개 남아요.","⟨33/9⟩ = ⟨3 6/9⟩ — 분수 부분은 진분수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L06_basic#7','math',3,2,'u4','L06','tb_g3_2_math_u4_L06_basic','lesson_basic','M3-2-u4-C7',2,'mc','auto','「확인 문제」 ⟨2 3/8⟩, ⟨10/12⟩, ⟨9/6⟩, ⟨4 2/3⟩, ⟨11/11⟩ 중에서 대분수만 모두 고른 것은 무엇인가요?',ARRAY['M3-2-u4-X08']::text[],true,'{"seq":7,"concept":"M3-2-u4-C7","difficulty":2,"kind":"mc","stem":"「확인 문제」 ⟨2 3/8⟩, ⟨10/12⟩, ⟨9/6⟩, ⟨4 2/3⟩, ⟨11/11⟩ 중에서 대분수만 모두 고른 것은 무엇인가요?","options":[{"t":"⟨2 3/8⟩, ⟨4 2/3⟩","correct":true},{"t":"⟨9/6⟩, ⟨11/11⟩","mis":"M3-2-u4-X08"},{"t":"⟨2 3/8⟩, ⟨4 2/3⟩, ⟨11/11⟩","mis":"M3-2-u4-X08"},{"t":"⟨10/12⟩, ⟨9/6⟩","mis":"M3-2-u4-X08"}],"explanation":["대분수는 자연수와 진분수로 이루어진 분수예요.","⟨2 3/8⟩은 2와 ⟨3/8⟩, ⟨4 2/3⟩는 4와 ⟨2/3⟩로 이루어졌어요.","⟨10/12⟩은 진분수, ⟨9/6⟩와 ⟨11/11⟩은 가분수예요."],"variant_rule":{"alt":[{"stem":"「익힘」 대분수를 바르게 설명한 것은 무엇인가요?","options":[{"t":"자연수와 진분수로 이루어진 분수 — 「띠 대(帶)」를 써요","correct":true},{"t":"큰 분수라는 뜻 — 「큰 대(大)」를 써요","mis":"M3-2-u4-X08"},{"t":"분자가 분모보다 큰 분수예요","mis":"M3-2-u4-X08"},{"t":"자연수와 가분수로 이루어진 분수예요","mis":"M3-2-u4-X11"}],"explanation":["⟨2 3/8⟩과 같이 자연수와 진분수로 이루어진 분수를 대분수라고 해요.","대분수의 모양이 허리에 띠를 두른 것처럼 보여서 「띠 대(帶)」를 써요.","큰 분수라는 뜻이 아니고, 분수 부분은 늘 진분수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L06_basic#8','math',3,2,'u4','L06','tb_g3_2_math_u4_L06_basic','lesson_basic','M3-2-u4-C7',2,'mc','auto','「익힘」 레몬주스 한 병을 만드는 데 레몬즙 ⟨1 5/7⟩컵, 시럽 ⟨2/5⟩컵, 물 ⟨9/4⟩컵, 얼음 ⟨3/2⟩컵이 필요해요. 필요한 양이 대분수인 재료와 그 양을 가분수로 바르게 나타낸 것은 무엇인가요?',ARRAY['M3-2-u4-X08','M3-2-u4-X10']::text[],false,'{"seq":8,"concept":"M3-2-u4-C7","difficulty":2,"kind":"mc","stem":"「익힘」 레몬주스 한 병을 만드는 데 레몬즙 ⟨1 5/7⟩컵, 시럽 ⟨2/5⟩컵, 물 ⟨9/4⟩컵, 얼음 ⟨3/2⟩컵이 필요해요. 필요한 양이 대분수인 재료와 그 양을 가분수로 바르게 나타낸 것은 무엇인가요?","options":[{"t":"레몬즙, ⟨12/7⟩컵","correct":true},{"t":"물, ⟨2 1/4⟩컵","mis":"M3-2-u4-X08"},{"t":"레몬즙, ⟨6/7⟩컵","mis":"M3-2-u4-X10"},{"t":"얼음, ⟨1 1/2⟩컵","mis":"M3-2-u4-X08"}],"explanation":["대분수인 것은 자연수와 진분수로 이루어진 ⟨1 5/7⟩ — 레몬즙이에요.","1 = ⟨7/7⟩이고 ⟨5/7⟩를 더하면 ⟨1/7⟩이 12개예요.","⟨1 5/7⟩ = ⟨12/7⟩ — ⟨9/4⟩와 ⟨3/2⟩은 가분수, ⟨2/5⟩는 진분수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L06_basic#9','math',3,2,'u4','L06','tb_g3_2_math_u4_L06_basic','lesson_basic','M3-2-u4-C7',2,'mc','auto','「익힘」 조건에 맞는 대분수는 무엇인가요?  · 6보다 크고 7보다 작아요.  · 분모는 3이에요.  · 분자는 홀수예요.',ARRAY['M3-2-u4-X20','M3-2-u4-X21','M3-2-u4-X03']::text[],false,'{"seq":9,"concept":"M3-2-u4-C7","difficulty":2,"kind":"mc","stem":"「익힘」 조건에 맞는 대분수는 무엇인가요?  · 6보다 크고 7보다 작아요.  · 분모는 3이에요.  · 분자는 홀수예요.","options":[{"t":"⟨6 1/3⟩","correct":true},{"t":"⟨6 2/3⟩","mis":"M3-2-u4-X20"},{"t":"⟨7 1/3⟩","mis":"M3-2-u4-X21"},{"t":"⟨1 6/3⟩","mis":"M3-2-u4-X03"}],"explanation":["6보다 크고 7보다 작으니 자연수 부분은 6이에요.","분모 3인 진분수는 ⟨1/3⟩, ⟨2/3⟩ — 분자가 홀수인 것은 ⟨1/3⟩이에요.","조건에 맞는 대분수는 ⟨6 1/3⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L06_basic#10','math',3,2,'u4','L06','tb_g3_2_math_u4_L06_basic','lesson_basic','M3-2-u4-C7',3,'error','auto','가분수와 대분수를 바꾸어 나타낸 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u4-X11','M3-2-u4-X20']::text[],true,'{"seq":10,"concept":"M3-2-u4-C7","difficulty":3,"kind":"error","stem":"가분수와 대분수를 바꾸어 나타낸 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「⟨5/2⟩는 대분수로 ⟨1 3/2⟩이야」","correct":true,"mis_target":"M3-2-u4-X11"},{"t":"서윤 — 「⟨3 1/3⟩은 ⟨10/3⟩이야」","mis":"M3-2-u4-X20"},{"t":"채원 — 「⟨17/5⟩은 ⟨3 2/5⟩야」","mis":"M3-2-u4-X20"}],"explanation":["대분수의 분수 부분은 반드시 진분수예요.","⟨3/2⟩에서 1을 더 모을 수 있어요 — ⟨5/2⟩ = ⟨2 1/2⟩이에요.","도윤이는 분수 부분을 가분수로 남겼어요."],"variant_rule":{"alt":[{"stem":"대분수를 가분수로 나타낸 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"건우 — 「⟨2 3/4⟩은 가분수로 ⟨7/4⟩이야」","correct":true,"mis_target":"M3-2-u4-X10"},{"t":"지유 — 「⟨1 5/9⟩는 ⟨14/9⟩야」","mis":"M3-2-u4-X20"},{"t":"준우 — 「⟨13/6⟩은 ⟨2 1/6⟩이야」","mis":"M3-2-u4-X20"}],"explanation":["2는 ⟨1/4⟩이 8개예요.","⟨2 3/4⟩ = ⟨11/4⟩ — 2를 ⟨4/4⟩ 하나만큼으로 보면 안 돼요.","건우는 자연수 부분을 단위분수의 개수로 바르게 바꾸지 않았어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L06_challenge#1','math',3,2,'u4','L06','tb_g3_2_math_u4_L06_challenge','lesson_challenge','M3-2-u4-C7',2,'sa','auto','「익힘」 ⟨13/8⟩ = ⟨1 □/8⟩일 때 □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u4-C7","difficulty":2,"kind":"sa","stem":"「익힘」 ⟨13/8⟩ = ⟨1 □/8⟩일 때 □에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["⟨13/8⟩은 ⟨8/8⟩과 ⟨5/8⟩예요.","⟨8/8⟩ = 1이에요.","⟨13/8⟩ = ⟨1 5/8⟩ — □는 5예요."],"variant_rule":{"alt":[{"stem":"「익힘」 ⟨33/9⟩ = ⟨3 □/9⟩일 때 □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["⟨33/9⟩은 ⟨27/9⟩과 ⟨6/9⟩이에요.","⟨27/9⟩ = 3이에요.","⟨33/9⟩ = ⟨3 6/9⟩ — □는 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L06_challenge#2','math',3,2,'u4','L06','tb_g3_2_math_u4_L06_challenge','lesson_challenge','M3-2-u4-C7',2,'mc','auto','⟨2 3/4⟩만큼 색칠했어요. 2는 ⟨1/4⟩이 몇 개이고, ⟨3/4⟩은 ⟨1/4⟩이 몇 개인가요?',ARRAY['M3-2-u4-X10','M3-2-u4-X21']::text[],false,'{"seq":2,"concept":"M3-2-u4-C7","difficulty":2,"kind":"mc","stem":"⟨2 3/4⟩만큼 색칠했어요. 2는 ⟨1/4⟩이 몇 개이고, ⟨3/4⟩은 ⟨1/4⟩이 몇 개인가요?","options":[{"t":"8개, 3개","correct":true},{"t":"2개, 3개","mis":"M3-2-u4-X10"},{"t":"4개, 3개","mis":"M3-2-u4-X10"},{"t":"8개, 4개","mis":"M3-2-u4-X21"}],"explanation":["1은 ⟨1/4⟩이 4개예요.","2는 1이 2개 — ⟨1/4⟩이 8개예요.","⟨3/4⟩은 ⟨1/4⟩이 3개 — ⟨2 3/4⟩은 ⟨1/4⟩이 모두 11개예요."],"asset":{"type":"fbar","bars":[{"den":4,"num":4},{"den":4,"num":4},{"den":4,"num":3}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L06_challenge#3','math',3,2,'u4','L06','tb_g3_2_math_u4_L06_challenge','lesson_challenge','M3-2-u4-C7',3,'sa','auto','「확인 문제」 은비는 냄비에 물을 ⟨2 3/4⟩컵 넣었어요. ⟨1/4⟩컵으로 몇 번 부은 것과 같나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u4-C7","difficulty":3,"kind":"sa","stem":"「확인 문제」 은비는 냄비에 물을 ⟨2 3/4⟩컵 넣었어요. ⟨1/4⟩컵으로 몇 번 부은 것과 같나요? 숫자로 쓰세요.","answer":["11"],"explanation":["1컵은 ⟨1/4⟩컵이 4번이에요.","2컵은 8번, ⟨3/4⟩컵은 3번 — 모두 8 + 3 = 11번이에요.","⟨2 3/4⟩ = ⟨11/4⟩ — 11번 부은 것과 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L06_challenge#4','math',3,2,'u4','L06','tb_g3_2_math_u4_L06_challenge','lesson_challenge','M3-2-u4-C7',3,'match','auto','대분수는 가분수로, 가분수는 대분수로 나타내어 크기가 같은 것끼리 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"M3-2-u4-C7","difficulty":3,"kind":"match","stem":"대분수는 가분수로, 가분수는 대분수로 나타내어 크기가 같은 것끼리 알맞게 이으세요.","pairs":[{"l":"⟨3 1/3⟩","r":"⟨10/3⟩"},{"l":"⟨1 5/9⟩","r":"⟨14/9⟩"},{"l":"⟨17/5⟩","r":"⟨3 2/5⟩"},{"l":"⟨13/6⟩","r":"⟨2 1/6⟩"}],"mis":"M3-2-u4-X10","explanation":["3 = ⟨9/3⟩이므로 ⟨3 1/3⟩ = ⟨10/3⟩, 1 = ⟨9/9⟩이므로 ⟨1 5/9⟩ = ⟨14/9⟩예요.","⟨15/5⟩ = 3이므로 ⟨17/5⟩ = ⟨3 2/5⟩, ⟨12/6⟩ = 2이므로 ⟨13/6⟩ = ⟨2 1/6⟩이에요.","분모는 그대로 — 단위분수의 개수로 바꾸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L06_challenge#5','math',3,2,'u4','L06','tb_g3_2_math_u4_L06_challenge','lesson_challenge','M3-2-u4-C7',3,'mc','auto','대분수를 가분수로 나타내는 방법으로 알맞은 것은 무엇인가요?',ARRAY['M3-2-u4-X10','M3-2-u4-X03','M3-2-u4-X12']::text[],false,'{"seq":5,"concept":"M3-2-u4-C7","difficulty":3,"kind":"mc","stem":"대분수를 가분수로 나타내는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"분모는 그대로 두고 단위분수가 모두 몇 개인지 센다","correct":true},{"t":"자연수와 분자를 더해 분자로 쓴다","mis":"M3-2-u4-X10"},{"t":"자연수를 분모에 곱해 분모로 쓴다","mis":"M3-2-u4-X03"},{"t":"자연수를 빼고 분수 부분만 쓴다","mis":"M3-2-u4-X12"}],"explanation":["⟨2 3/4⟩에서 2는 ⟨1/4⟩이 8개예요.","⟨3/4⟩은 ⟨1/4⟩이 3개 — 모두 11개예요.","⟨2 3/4⟩ = ⟨11/4⟩ — 분모 4는 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L06_challenge#6','math',3,2,'u4','L06','tb_g3_2_math_u4_L06_challenge','lesson_challenge','M3-2-u4-C7',3,'sa','auto','「이 단원 학습을 마치고」 색 테이프가 1 m와 ⟨1/2⟩ m만큼 있어요. 이 길이를 가분수 ⟨□/2⟩ m로 나타낼 때 □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M3-2-u4-C7","difficulty":3,"kind":"sa","stem":"「이 단원 학습을 마치고」 색 테이프가 1 m와 ⟨1/2⟩ m만큼 있어요. 이 길이를 가분수 ⟨□/2⟩ m로 나타낼 때 □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["1 m와 ⟨1/2⟩ m는 대분수로 ⟨1 1/2⟩ m예요.","1은 ⟨1/2⟩이 2개 — ⟨1/2⟩이 모두 3개예요.","⟨1 1/2⟩ = ⟨3/2⟩ — □는 3이에요."],"asset":{"type":"fbar","bars":[{"den":2,"num":2},{"den":2,"num":1}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L06_challenge#7','math',3,2,'u4','L06','tb_g3_2_math_u4_L06_challenge','lesson_challenge','M3-2-u4-C7',3,'mc','auto','「익힘」 그림은 ⟨2 1/4⟩만큼 색칠한 것이에요. ⟨2 1/4⟩을 가분수로 나타내면 무엇인가요?',ARRAY['M3-2-u4-X10','M3-2-u4-X03']::text[],false,'{"seq":7,"concept":"M3-2-u4-C7","difficulty":3,"kind":"mc","stem":"「익힘」 그림은 ⟨2 1/4⟩만큼 색칠한 것이에요. ⟨2 1/4⟩을 가분수로 나타내면 무엇인가요?","options":[{"t":"⟨9/4⟩","correct":true},{"t":"⟨3/4⟩","mis":"M3-2-u4-X10"},{"t":"⟨5/4⟩","mis":"M3-2-u4-X10"},{"t":"⟨4/9⟩","mis":"M3-2-u4-X03"}],"explanation":["2는 ⟨1/4⟩이 8개예요.","⟨1/4⟩이 1개 더 — 모두 9개예요.","⟨2 1/4⟩ = ⟨9/4⟩예요."],"asset":{"type":"fbar","bars":[{"den":4,"num":4},{"den":4,"num":4},{"den":4,"num":1}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L06_challenge#8','math',3,2,'u4','L06','tb_g3_2_math_u4_L06_challenge','lesson_challenge','M3-2-u4-C7',4,'sa','auto','「익힘」 6보다 크고 7보다 작으며, 분모는 3이고 분자는 홀수인 대분수가 있어요. 이 대분수를 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u4-C7","difficulty":4,"kind":"sa","stem":"「익힘」 6보다 크고 7보다 작으며, 분모는 3이고 분자는 홀수인 대분수가 있어요. 이 대분수를 가분수로 나타내면 분자는 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["조건에 맞는 대분수는 ⟨6 1/3⟩이에요.","6은 ⟨1/3⟩이 18개 — 18 + 1 = 19개예요.","⟨6 1/3⟩ = ⟨19/3⟩ — 분자는 19예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L06_challenge#9','math',3,2,'u4','L06','tb_g3_2_math_u4_L06_challenge','lesson_challenge','M3-2-u4-C7',4,'sa','auto','「익힘」 레몬주스를 만드는 데 레몬즙이 ⟨1 5/7⟩컵 필요해요. ⟨1/7⟩컵을 담는 계량컵으로 몇 번 담으면 되나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u4-C7","difficulty":4,"kind":"sa","stem":"「익힘」 레몬주스를 만드는 데 레몬즙이 ⟨1 5/7⟩컵 필요해요. ⟨1/7⟩컵을 담는 계량컵으로 몇 번 담으면 되나요? 숫자로 쓰세요.","answer":["12"],"explanation":["1컵은 ⟨1/7⟩컵이 7번이에요.","⟨5/7⟩컵은 5번 — 모두 7 + 5 = 12번이에요.","⟨1 5/7⟩ = ⟨12/7⟩ — 12번 담으면 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L06_challenge#10','math',3,2,'u4','L06','tb_g3_2_math_u4_L06_challenge','lesson_challenge','M3-2-u4-C7',4,'essay','teacher','⟨2 3/4⟩을 가분수로, ⟨5/2⟩를 대분수로 나타내고, 각각의 방법을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u4-C7","difficulty":4,"kind":"essay","stem":"⟨2 3/4⟩을 가분수로, ⟨5/2⟩를 대분수로 나타내고, 각각의 방법을 설명해 보세요.","answer_guide":{"answer":"예: 2는 ⟨1/4⟩이 8개이고 ⟨3/4⟩은 ⟨1/4⟩이 3개이므로 ⟨2 3/4⟩ = ⟨11/4⟩이다. ⟨5/2⟩는 ⟨4/2⟩와 ⟨1/2⟩이고 ⟨4/2⟩ = 2이므로 ⟨5/2⟩ = ⟨2 1/2⟩이다.","scoring_points":["⟨2 3/4⟩ = ⟨11/4⟩을 썼는가","⟨5/2⟩ = ⟨2 1/2⟩을 썼는가","단위분수의 개수·자연수로 나타낼 수 있는 부분으로 설명했는가"]},"explanation":["⟨2 3/4⟩ = ⟨11/4⟩이에요.","⟨5/2⟩ = ⟨2 1/2⟩이에요.","분수 부분은 진분수로 남겨요."],"asset":{"type":"fbar","bars":[{"den":4,"num":4},{"den":4,"num":4},{"den":4,"num":3}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L07_basic#1','math',3,2,'u4','L07','tb_g3_2_math_u4_L07_basic','lesson_basic','M3-2-u4-C8',1,'mc','auto','길이가 각각 ⟨7/4⟩ m, ⟨6/4⟩ m인 천에 말을 넣어 꾸몄어요. 더 긴 천을 복도에 붙이기로 했어요. 어느 천이 더 긴가요?',ARRAY['M3-2-u4-X13','M3-2-u4-X22']::text[],true,'{"seq":1,"concept":"M3-2-u4-C8","difficulty":1,"kind":"mc","stem":"길이가 각각 ⟨7/4⟩ m, ⟨6/4⟩ m인 천에 말을 넣어 꾸몄어요. 더 긴 천을 복도에 붙이기로 했어요. 어느 천이 더 긴가요?","options":[{"t":"⟨7/4⟩ m인 천","correct":true},{"t":"⟨6/4⟩ m인 천","mis":"M3-2-u4-X13"},{"t":"두 천의 길이가 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["⟨7/4⟩은 ⟨1/4⟩이 7개, ⟨6/4⟩은 ⟨1/4⟩이 6개예요.","분모가 같은 가분수는 분자가 클수록 커요.","⟨7/4⟩ > ⟨6/4⟩ — ⟨7/4⟩ m인 천이 더 길어요."],"asset":{"type":"number_line","cells":["0","⟨1/4⟩","⟨2/4⟩","⟨3/4⟩","1","⟨5/4⟩","⟨6/4⟩","⟨7/4⟩","2"]},"variant_rule":{"alt":[{"stem":"「익힘」 길이가 각각 ⟨5/3⟩ m, ⟨4/3⟩ m인 천에 말을 넣어 꾸몄어요. 어느 천이 더 긴가요?","options":[{"t":"⟨5/3⟩ m인 천","correct":true},{"t":"⟨4/3⟩ m인 천","mis":"M3-2-u4-X13"},{"t":"두 천의 길이가 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["⟨5/3⟩는 ⟨1/3⟩이 5개, ⟨4/3⟩는 ⟨1/3⟩이 4개예요.","분모가 같은 가분수는 분자가 클수록 커요.","⟨5/3⟩ > ⟨4/3⟩ — ⟨5/3⟩ m인 천이 더 길어요."],"asset":{"type":"number_line","cells":["0","⟨1/3⟩","⟨2/3⟩","1","⟨4/3⟩","⟨5/3⟩","2"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L07_basic#2','math',3,2,'u4','L07','tb_g3_2_math_u4_L07_basic','lesson_basic','M3-2-u4-C8',1,'sa','auto','⟨7/4⟩은 ⟨1/4⟩이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u4-C8","difficulty":1,"kind":"sa","stem":"⟨7/4⟩은 ⟨1/4⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["분자는 단위분수의 개수예요.","⟨7/4⟩의 분자는 7이에요.","⟨7/4⟩은 ⟨1/4⟩이 7개예요."],"variant_rule":{"alt":[{"stem":"「익힘」 ⟨5/3⟩는 ⟨1/3⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["분자는 단위분수의 개수예요.","⟨5/3⟩의 분자는 5예요.","⟨5/3⟩는 ⟨1/3⟩이 5개예요."]},{"stem":"⟨6/4⟩은 ⟨1/4⟩이 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["분자는 단위분수의 개수예요.","⟨6/4⟩의 분자는 6이에요.","⟨6/4⟩은 ⟨1/4⟩이 6개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L07_basic#3','math',3,2,'u4','L07','tb_g3_2_math_u4_L07_basic','lesson_basic','M3-2-u4-C8',1,'mc','auto','두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨13/9⟩ ○ ⟨10/9⟩',ARRAY['M3-2-u4-X13','M3-2-u4-X22']::text[],true,'{"seq":3,"concept":"M3-2-u4-C8","difficulty":1,"kind":"mc","stem":"두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨13/9⟩ ○ ⟨10/9⟩","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u4-X13"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["분모가 같은 가분수는 분자의 크기를 비교해요.","⟨13/9⟩은 ⟨1/9⟩이 13개, ⟨10/9⟩은 10개예요.","그래서 ⟨13/9⟩ > ⟨10/9⟩."],"variant_rule":{"alt":[{"stem":"「익힘」 두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨9/5⟩ ○ ⟨7/5⟩","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u4-X13"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["분모가 같은 가분수는 분자의 크기를 비교해요.","⟨9/5⟩는 ⟨1/5⟩이 9개, ⟨7/5⟩은 7개예요.","그래서 ⟨9/5⟩ > ⟨7/5⟩."]},{"stem":"「익힘」 두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨15/10⟩ ○ ⟨19/10⟩","options":[{"t":"<","correct":true},{"t":">","mis":"M3-2-u4-X13"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["분모가 같은 가분수는 분자의 크기를 비교해요.","⟨15/10⟩는 ⟨1/10⟩이 15개, ⟨19/10⟩는 19개예요.","그래서 ⟨15/10⟩ < ⟨19/10⟩."]},{"stem":"「준비하기」 두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨5/7⟩ ○ ⟨3/7⟩","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u4-X13"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["분모가 같은 진분수예요 — 1학기에 배웠어요.","⟨5/7⟩는 ⟨1/7⟩이 5개, ⟨3/7⟩은 ⟨1/7⟩이 3개예요.","분모가 같으면 분자가 클수록 커요 — ⟨5/7⟩ > ⟨3/7⟩."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L07_basic#4','math',3,2,'u4','L07','tb_g3_2_math_u4_L07_basic','lesson_basic','M3-2-u4-C8',1,'mc','auto','두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨2 1/5⟩ ○ ⟨1 4/5⟩',ARRAY['M3-2-u4-X13','M3-2-u4-X22']::text[],true,'{"seq":4,"concept":"M3-2-u4-C8","difficulty":1,"kind":"mc","stem":"두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨2 1/5⟩ ○ ⟨1 4/5⟩","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u4-X13"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["분모가 같은 대분수는 먼저 자연수의 크기를 비교해요.","자연수의 크기가 같으면 진분수의 크기를 비교해요.","그래서 ⟨2 1/5⟩ > ⟨1 4/5⟩."],"variant_rule":{"alt":[{"stem":"두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨3 5/6⟩ ○ ⟨4 2/6⟩","options":[{"t":"<","correct":true},{"t":">","mis":"M3-2-u4-X13"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["분모가 같은 대분수는 먼저 자연수의 크기를 비교해요.","자연수의 크기가 같으면 진분수의 크기를 비교해요.","그래서 ⟨3 5/6⟩ < ⟨4 2/6⟩."]},{"stem":"「익힘」 두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨4 3/8⟩ ○ ⟨4 6/8⟩","options":[{"t":"<","correct":true},{"t":">","mis":"M3-2-u4-X13"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["분모가 같은 대분수는 먼저 자연수의 크기를 비교해요.","자연수의 크기가 같으면 진분수의 크기를 비교해요.","그래서 ⟨4 3/8⟩ < ⟨4 6/8⟩."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L07_basic#5','math',3,2,'u4','L07','tb_g3_2_math_u4_L07_basic','lesson_basic','M3-2-u4-C8',2,'mc','auto','두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨8/3⟩ ○ ⟨2 1/3⟩',ARRAY['M3-2-u4-X14','M3-2-u4-X22']::text[],true,'{"seq":5,"concept":"M3-2-u4-C8","difficulty":2,"kind":"mc","stem":"두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨8/3⟩ ○ ⟨2 1/3⟩","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u4-X14"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["가분수를 대분수로, 또는 대분수를 가분수로 나타내어 비교해요.","⟨8/3⟩ = ⟨2 2/3⟩, ⟨2 1/3⟩ = ⟨7/3⟩이에요.","그래서 ⟨8/3⟩ > ⟨2 1/3⟩."],"variant_rule":{"alt":[{"stem":"두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨24/7⟩ ○ ⟨3 2/7⟩","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u4-X14"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["가분수를 대분수로, 또는 대분수를 가분수로 나타내어 비교해요.","⟨24/7⟩ = ⟨3 3/7⟩, ⟨3 2/7⟩ = ⟨23/7⟩이에요.","그래서 ⟨24/7⟩ > ⟨3 2/7⟩."]},{"stem":"「익힘」 두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨32/15⟩ ○ ⟨2 2/15⟩","options":[{"t":"=","correct":true},{"t":">","mis":"M3-2-u4-X14"},{"t":"<","mis":"M3-2-u4-X14"}],"explanation":["가분수를 대분수로, 또는 대분수를 가분수로 나타내어 비교해요.","⟨32/15⟩ = ⟨2 2/15⟩, ⟨2 2/15⟩ = ⟨32/15⟩예요.","그래서 ⟨32/15⟩ = ⟨2 2/15⟩."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L07_basic#6','math',3,2,'u4','L07','tb_g3_2_math_u4_L07_basic','lesson_basic','M3-2-u4-C8',2,'mc','auto','분모가 같은 가분수의 크기를 비교하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['M3-2-u4-X13','M3-2-u4-X22']::text[],false,'{"seq":6,"concept":"M3-2-u4-C8","difficulty":2,"kind":"mc","stem":"분모가 같은 가분수의 크기를 비교하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"분자의 크기를 비교한다","correct":true},{"t":"분모의 크기를 비교한다","mis":"M3-2-u4-X13"},{"t":"분자가 작을수록 더 크다","mis":"M3-2-u4-X13"},{"t":"가분수끼리는 비교할 수 없다","mis":"M3-2-u4-X22"}],"explanation":["분모가 같으면 단위분수의 크기가 같아요.","분자는 단위분수의 개수 — 개수가 많을수록 커요.","⟨7/4⟩ > ⟨6/4⟩ — 분자 7 > 6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L07_basic#7','math',3,2,'u4','L07','tb_g3_2_math_u4_L07_basic','lesson_basic','M3-2-u4-C8',2,'mc','auto','분모가 같은 대분수의 크기를 비교하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['M3-2-u4-X13','M3-2-u4-X20','M3-2-u4-X22']::text[],false,'{"seq":7,"concept":"M3-2-u4-C8","difficulty":2,"kind":"mc","stem":"분모가 같은 대분수의 크기를 비교하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"먼저 자연수의 크기를 비교하고, 자연수가 같으면 진분수의 크기를 비교한다","correct":true},{"t":"진분수의 크기만 비교한다","mis":"M3-2-u4-X13"},{"t":"자연수가 작을수록 더 크다","mis":"M3-2-u4-X20"},{"t":"대분수는 가분수로 바꾸지 않으면 비교할 수 없다","mis":"M3-2-u4-X22"}],"explanation":["자연수의 크기 비교에서 높은 자리부터 보듯 대분수도 자연수부터 비교해요.","⟨2 1/5⟩과 ⟨1 4/5⟩는 자연수 2 > 1이에요.","그래서 ⟨2 1/5⟩ > ⟨1 4/5⟩ — 진분수만 보면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L07_basic#8','math',3,2,'u4','L07','tb_g3_2_math_u4_L07_basic','lesson_basic','M3-2-u4-C8',2,'mc','auto','「확인 문제」 ⟨4 2/5⟩, 3, ⟨12/5⟩ 중에서 가장 큰 수는 무엇인가요?',ARRAY['M3-2-u4-X14','M3-2-u4-X22']::text[],true,'{"seq":8,"concept":"M3-2-u4-C8","difficulty":2,"kind":"mc","stem":"「확인 문제」 ⟨4 2/5⟩, 3, ⟨12/5⟩ 중에서 가장 큰 수는 무엇인가요?","options":[{"t":"⟨4 2/5⟩","correct":true},{"t":"⟨12/5⟩","mis":"M3-2-u4-X14"},{"t":"3","mis":"M3-2-u4-X14"},{"t":"세 수가 모두 같아요","mis":"M3-2-u4-X22"}],"explanation":["⟨12/5⟩ = ⟨2 2/5⟩, 3 = ⟨15/5⟩예요.","자연수 부분을 비교하면 4 > 3 > 2예요.","가장 큰 수는 ⟨4 2/5⟩ — 분자 12가 크다고 큰 수가 아니에요."],"variant_rule":{"alt":[{"stem":"「익힘」 ⟨8/8⟩, ⟨1 3/8⟩, ⟨13/8⟩, ⟨2 1/8⟩, 2 중에서 가장 큰 수는 무엇인가요?","options":[{"t":"⟨2 1/8⟩","correct":true},{"t":"⟨13/8⟩","mis":"M3-2-u4-X14"},{"t":"2","mis":"M3-2-u4-X14"},{"t":"⟨8/8⟩","mis":"M3-2-u4-X20"}],"explanation":["⟨8/8⟩ = 1, ⟨13/8⟩ = ⟨1 5/8⟩예요.","자연수 부분이 2인 것은 2와 ⟨2 1/8⟩ — ⟨2 1/8⟩이 더 커요.","가장 큰 수는 ⟨2 1/8⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L07_basic#9','math',3,2,'u4','L07','tb_g3_2_math_u4_L07_basic','lesson_basic','M3-2-u4-C8',2,'mc','auto','「익힘」 채원이는 케이크를 만드는 데 우유 ⟨8/3⟩컵을, 건우는 우유 ⟨1 1/3⟩컵을 사용했어요. 컵의 크기가 같을 때 우유를 더 많이 사용한 사람은 누구인가요?',ARRAY['M3-2-u4-X14','M3-2-u4-X22']::text[],false,'{"seq":9,"concept":"M3-2-u4-C8","difficulty":2,"kind":"mc","stem":"「익힘」 채원이는 케이크를 만드는 데 우유 ⟨8/3⟩컵을, 건우는 우유 ⟨1 1/3⟩컵을 사용했어요. 컵의 크기가 같을 때 우유를 더 많이 사용한 사람은 누구인가요?","options":[{"t":"채원","correct":true},{"t":"건우","mis":"M3-2-u4-X14"},{"t":"두 사람이 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["⟨8/3⟩ = ⟨2 2/3⟩예요.","⟨2 2/3⟩와 ⟨1 1/3⟩은 자연수 2 > 1이에요.","⟨8/3⟩ > ⟨1 1/3⟩ — 채원이가 더 많이 사용했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L07_basic#10','math',3,2,'u4','L07','tb_g3_2_math_u4_L07_basic','lesson_basic','M3-2-u4-C8',3,'sa','auto','「익힘」 □⟨2/7⟩ < ⟨30/7⟩이에요. □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u4-C8","difficulty":3,"kind":"sa","stem":"「익힘」 □⟨2/7⟩ < ⟨30/7⟩이에요. □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨30/7⟩ = ⟨4 2/7⟩예요.","진분수가 ⟨2/7⟩로 같으니 자연수 □가 4보다 작아야 해요.","□는 1, 2, 3 — 모두 3개예요. 4를 넣으면 두 수가 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L07_challenge#1','math',3,2,'u4','L07','tb_g3_2_math_u4_L07_challenge','lesson_challenge','M3-2-u4-C8',2,'mc','auto','「익힘」 두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨2 2/6⟩ ○ ⟨1 5/6⟩',ARRAY['M3-2-u4-X13','M3-2-u4-X22']::text[],true,'{"seq":1,"concept":"M3-2-u4-C8","difficulty":2,"kind":"mc","stem":"「익힘」 두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨2 2/6⟩ ○ ⟨1 5/6⟩","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u4-X13"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["분모가 같은 대분수는 먼저 자연수의 크기를 비교해요.","자연수의 크기가 같으면 진분수의 크기를 비교해요.","그래서 ⟨2 2/6⟩ > ⟨1 5/6⟩."],"variant_rule":{"alt":[{"stem":"「익힘」 두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨1 1/4⟩ ○ ⟨1 2/4⟩","options":[{"t":"<","correct":true},{"t":">","mis":"M3-2-u4-X13"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["분모가 같은 대분수는 먼저 자연수의 크기를 비교해요.","자연수의 크기가 같으면 진분수의 크기를 비교해요.","그래서 ⟨1 1/4⟩ < ⟨1 2/4⟩."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L07_challenge#2','math',3,2,'u4','L07','tb_g3_2_math_u4_L07_challenge','lesson_challenge','M3-2-u4-C8',2,'sa','auto','⟨8/3⟩과 ⟨2 1/3⟩의 크기를 비교하려고 ⟨2 1/3⟩을 가분수 ⟨□/3⟩으로 나타냈어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u4-C8","difficulty":2,"kind":"sa","stem":"⟨8/3⟩과 ⟨2 1/3⟩의 크기를 비교하려고 ⟨2 1/3⟩을 가분수 ⟨□/3⟩으로 나타냈어요. □에 알맞은 수를 쓰세요.","answer":["7"],"explanation":["2는 ⟨1/3⟩이 6개예요.","⟨1/3⟩이 1개 더 — 모두 7개예요.","⟨2 1/3⟩ = ⟨7/3⟩ — ⟨8/3⟩ > ⟨7/3⟩이에요."],"variant_rule":{"alt":[{"stem":"「익힘」 ⟨3 2/6⟩와 ⟨16/6⟩의 크기를 비교하려고 ⟨3 2/6⟩를 가분수 ⟨□/6⟩으로 나타냈어요. □에 알맞은 수를 쓰세요.","answer":["20"],"explanation":["3은 ⟨1/6⟩이 18개예요.","⟨2/6⟩는 2개 — 모두 20개예요.","⟨3 2/6⟩ = ⟨20/6⟩ — ⟨20/6⟩ > ⟨16/6⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L07_challenge#3','math',3,2,'u4','L07','tb_g3_2_math_u4_L07_challenge','lesson_challenge','M3-2-u4-C8',3,'mc','auto','「확인 문제」 두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨1 7/9⟩ ○ ⟨3 1/9⟩',ARRAY['M3-2-u4-X13','M3-2-u4-X22']::text[],true,'{"seq":3,"concept":"M3-2-u4-C8","difficulty":3,"kind":"mc","stem":"「확인 문제」 두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨1 7/9⟩ ○ ⟨3 1/9⟩","options":[{"t":"<","correct":true},{"t":">","mis":"M3-2-u4-X13"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["분모가 같은 대분수는 먼저 자연수의 크기를 비교해요.","자연수의 크기가 같으면 진분수의 크기를 비교해요.","그래서 ⟨1 7/9⟩ < ⟨3 1/9⟩."],"variant_rule":{"alt":[{"stem":"「확인 문제」 두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨16/8⟩ ○ ⟨9/8⟩","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u4-X13"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["분모가 같은 가분수는 분자의 크기를 비교해요.","⟨16/8⟩은 ⟨1/8⟩이 16개, ⟨9/8⟩는 9개예요.","그래서 ⟨16/8⟩ > ⟨9/8⟩."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L07_challenge#4','math',3,2,'u4','L07','tb_g3_2_math_u4_L07_challenge','lesson_challenge','M3-2-u4-C8',3,'mc','auto','「익힘」 ⟨8/8⟩, ⟨1 3/8⟩, ⟨13/8⟩, ⟨2 1/8⟩, 2 중에서 가장 작은 수는 무엇인가요?',ARRAY['M3-2-u4-X14','M3-2-u4-X20']::text[],true,'{"seq":4,"concept":"M3-2-u4-C8","difficulty":3,"kind":"mc","stem":"「익힘」 ⟨8/8⟩, ⟨1 3/8⟩, ⟨13/8⟩, ⟨2 1/8⟩, 2 중에서 가장 작은 수는 무엇인가요?","options":[{"t":"⟨8/8⟩","correct":true},{"t":"⟨1 3/8⟩","mis":"M3-2-u4-X14"},{"t":"2","mis":"M3-2-u4-X14"},{"t":"⟨2 1/8⟩","mis":"M3-2-u4-X20"}],"explanation":["⟨8/8⟩ = 1, ⟨1 3/8⟩ = ⟨11/8⟩, ⟨13/8⟩ = ⟨1 5/8⟩예요.","1은 ⟨1 3/8⟩보다 작아요.","가장 작은 수는 ⟨8/8⟩ — 분자 8이 크다고 큰 수가 아니에요."],"variant_rule":{"alt":[{"stem":"「확인 문제」 ⟨4 2/5⟩, 3, ⟨12/5⟩ 중에서 가장 작은 수는 무엇인가요?","options":[{"t":"⟨12/5⟩","correct":true},{"t":"3","mis":"M3-2-u4-X14"},{"t":"⟨4 2/5⟩","mis":"M3-2-u4-X20"},{"t":"세 수가 모두 같아요","mis":"M3-2-u4-X22"}],"explanation":["⟨12/5⟩ = ⟨2 2/5⟩예요.","자연수 부분을 비교하면 2 < 3 < 4예요.","가장 작은 수는 ⟨12/5⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L07_challenge#5','math',3,2,'u4','L07','tb_g3_2_math_u4_L07_challenge','lesson_challenge','M3-2-u4-C8',3,'error','auto','분모가 같은 분수의 크기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u4-X13','M3-2-u4-X20']::text[],false,'{"seq":5,"concept":"M3-2-u4-C8","difficulty":3,"kind":"error","stem":"분모가 같은 분수의 크기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지훈 — 「⟨4/5⟩가 ⟨1/5⟩보다 크니까 ⟨1 4/5⟩가 ⟨2 1/5⟩보다 커」","correct":true,"mis_target":"M3-2-u4-X13"},{"t":"은비 — 「⟨8/3⟩ = ⟨2 2/3⟩이라서 ⟨2 1/3⟩보다 커」","mis":"M3-2-u4-X20"},{"t":"서준 — 「⟨2 1/3⟩ = ⟨7/3⟩이라서 ⟨8/3⟩보다 작아」","mis":"M3-2-u4-X20"}],"explanation":["대분수는 자연수의 크기를 먼저 비교해요.","⟨2 1/5⟩은 2보다 크고 ⟨1 4/5⟩는 2보다 작아요.","지훈이는 진분수만 보고 비교했어요 — ⟨2 1/5⟩ > ⟨1 4/5⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L07_challenge#6','math',3,2,'u4','L07','tb_g3_2_math_u4_L07_challenge','lesson_challenge','M3-2-u4-C8',3,'mc','auto','「익힘」 ⟨3 2/6⟩와 ⟨16/6⟩의 크기를 바르게 비교한 것은 무엇인가요?',ARRAY['M3-2-u4-X14','M3-2-u4-X10','M3-2-u4-X13']::text[],false,'{"seq":6,"concept":"M3-2-u4-C8","difficulty":3,"kind":"mc","stem":"「익힘」 ⟨3 2/6⟩와 ⟨16/6⟩의 크기를 바르게 비교한 것은 무엇인가요?","options":[{"t":"⟨16/6⟩ = ⟨2 4/6⟩이므로 ⟨3 2/6⟩ > ⟨16/6⟩","correct":true},{"t":"16 > 3이므로 ⟨16/6⟩이 더 커요","mis":"M3-2-u4-X14"},{"t":"⟨3 2/6⟩ = ⟨5/6⟩이므로 ⟨16/6⟩이 더 커요","mis":"M3-2-u4-X10"},{"t":"⟨2/6⟩ < ⟨4/6⟩이므로 ⟨3 2/6⟩ < ⟨16/6⟩","mis":"M3-2-u4-X13"}],"explanation":["방법 1 — ⟨3 2/6⟩ = ⟨20/6⟩이고 ⟨20/6⟩ > ⟨16/6⟩이에요.","방법 2 — ⟨16/6⟩ = ⟨2 4/6⟩이고 ⟨3 2/6⟩ > ⟨2 4/6⟩예요.","어느 방법이든 ⟨3 2/6⟩ > ⟨16/6⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L07_challenge#7','math',3,2,'u4','L07','tb_g3_2_math_u4_L07_challenge','lesson_challenge','M3-2-u4-C8',3,'sa','auto','「익힘」 □⟨2/7⟩ < ⟨30/7⟩일 때 □ 안에 들어갈 수 있는 가장 큰 자연수를 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M3-2-u4-C8","difficulty":3,"kind":"sa","stem":"「익힘」 □⟨2/7⟩ < ⟨30/7⟩일 때 □ 안에 들어갈 수 있는 가장 큰 자연수를 쓰세요.","answer":["3"],"explanation":["⟨30/7⟩ = ⟨4 2/7⟩예요.","진분수가 ⟨2/7⟩로 같으니 □는 4보다 작아야 해요.","가장 큰 자연수는 3이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L07_challenge#8','math',3,2,'u4','L07','tb_g3_2_math_u4_L07_challenge','lesson_challenge','M3-2-u4-C8',4,'mc','auto','「익힘」 ⟨8/8⟩, ⟨1 3/8⟩, ⟨13/8⟩, ⟨2 1/8⟩, 2를 작은 수부터 차례대로 바르게 쓴 것은 무엇인가요?',ARRAY['M3-2-u4-X14','M3-2-u4-X21']::text[],false,'{"seq":8,"concept":"M3-2-u4-C8","difficulty":4,"kind":"mc","stem":"「익힘」 ⟨8/8⟩, ⟨1 3/8⟩, ⟨13/8⟩, ⟨2 1/8⟩, 2를 작은 수부터 차례대로 바르게 쓴 것은 무엇인가요?","options":[{"t":"⟨8/8⟩, ⟨1 3/8⟩, ⟨13/8⟩, 2, ⟨2 1/8⟩","correct":true},{"t":"⟨8/8⟩, ⟨13/8⟩, ⟨1 3/8⟩, 2, ⟨2 1/8⟩","mis":"M3-2-u4-X14"},{"t":"⟨1 3/8⟩, ⟨2 1/8⟩, 2, ⟨8/8⟩, ⟨13/8⟩","mis":"M3-2-u4-X14"},{"t":"2, ⟨8/8⟩, ⟨1 3/8⟩, ⟨13/8⟩, ⟨2 1/8⟩","mis":"M3-2-u4-X21"}],"explanation":["모두 가분수로 나타내면 ⟨8/8⟩, ⟨11/8⟩, ⟨13/8⟩, ⟨17/8⟩, ⟨16/8⟩이에요.","분자를 비교하면 8 < 11 < 13 < 16 < 17이에요.","작은 수부터 ⟨8/8⟩, ⟨1 3/8⟩, ⟨13/8⟩, 2, ⟨2 1/8⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L07_challenge#9','math',3,2,'u4','L07','tb_g3_2_math_u4_L07_challenge','lesson_challenge','M3-2-u4-C8',4,'essay','teacher','「익힘」 ⟨3 2/6⟩와 ⟨16/6⟩의 크기를 두 가지 방법으로 비교해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u4-C8","difficulty":4,"kind":"essay","stem":"「익힘」 ⟨3 2/6⟩와 ⟨16/6⟩의 크기를 두 가지 방법으로 비교해 보세요.","answer_guide":{"answer":"예: 방법 1 — 대분수를 가분수로 나타내면 ⟨3 2/6⟩ = ⟨20/6⟩이고 ⟨20/6⟩ > ⟨16/6⟩이므로 ⟨3 2/6⟩ > ⟨16/6⟩이다. 방법 2 — 가분수를 대분수로 나타내면 ⟨16/6⟩ = ⟨2 4/6⟩이고 자연수 3 > 2이므로 ⟨3 2/6⟩ > ⟨16/6⟩이다.","scoring_points":["대분수를 가분수로 바꾸어 비교했는가","가분수를 대분수로 바꾸어 비교했는가","⟨3 2/6⟩ > ⟨16/6⟩이라고 답했는가"]},"explanation":["⟨3 2/6⟩ = ⟨20/6⟩이에요.","⟨16/6⟩ = ⟨2 4/6⟩예요.","⟨3 2/6⟩가 더 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L07_challenge#10','math',3,2,'u4','L07','tb_g3_2_math_u4_L07_challenge','lesson_challenge','M3-2-u4-C8',4,'essay','teacher','한 친구가 「⟨4/5⟩가 ⟨1/5⟩보다 크니까 ⟨1 4/5⟩가 ⟨2 1/5⟩보다 커.」라고 했어요. 친구의 생각을 바로잡아 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u4-C8","difficulty":4,"kind":"essay","stem":"한 친구가 「⟨4/5⟩가 ⟨1/5⟩보다 크니까 ⟨1 4/5⟩가 ⟨2 1/5⟩보다 커.」라고 했어요. 친구의 생각을 바로잡아 설명해 보세요.","answer_guide":{"answer":"예: 대분수의 크기를 비교할 때는 자연수의 크기를 먼저 비교해야 한다. ⟨2 1/5⟩은 자연수가 2이고 ⟨1 4/5⟩는 자연수가 1이므로 ⟨2 1/5⟩ > ⟨1 4/5⟩이다. 진분수의 크기는 자연수가 같을 때 비교한다.","scoring_points":["자연수를 먼저 비교해야 한다고 썼는가","⟨2 1/5⟩ > ⟨1 4/5⟩라고 답했는가","진분수는 자연수가 같을 때 비교한다고 설명했는가"]},"explanation":["자연수부터 비교해요.","2 > 1이에요.","⟨2 1/5⟩이 더 커요."],"asset":{"type":"number_line","cells":["0","1","⟨1 4/5⟩","2","⟨2 1/5⟩","3"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L08_basic#1','math',3,2,'u4','L08','tb_g3_2_math_u4_L08_basic','lesson_basic','M3-2-u4-C9',1,'mc','auto','길이가 4 cm 7 mm인 종이 빨대로 모둠 작품을 만들려고 해요. 7 mm는 몇 cm인지 분수로 나타내면 무엇인가요?',ARRAY['M3-2-u4-X03','M3-2-u4-X17','M3-2-u4-X20']::text[],true,'{"seq":1,"concept":"M3-2-u4-C9","difficulty":1,"kind":"mc","stem":"길이가 4 cm 7 mm인 종이 빨대로 모둠 작품을 만들려고 해요. 7 mm는 몇 cm인지 분수로 나타내면 무엇인가요?","options":[{"t":"⟨7/10⟩ cm","correct":true},{"t":"⟨10/7⟩ cm","mis":"M3-2-u4-X03"},{"t":"7 cm","mis":"M3-2-u4-X17"},{"t":"⟨4 7/10⟩ cm","mis":"M3-2-u4-X20"}],"explanation":["1 cm = 10 mm예요.","7 mm는 1 cm를 똑같이 10으로 나눈 것 중의 7이에요.","7 mm = ⟨7/10⟩ cm — 소수로는 0.7 cm예요."],"asset":{"type":"mmruler","len":47,"label":"종이 빨대"},"variant_rule":{"alt":[{"stem":"「익힘」 길이가 3 cm 9 mm인 종이 빨대가 있어요. 9 mm는 몇 cm인지 분수로 나타내면 무엇인가요?","options":[{"t":"⟨9/10⟩ cm","correct":true},{"t":"⟨10/9⟩ cm","mis":"M3-2-u4-X03"},{"t":"9 cm","mis":"M3-2-u4-X17"},{"t":"⟨3 9/10⟩ cm","mis":"M3-2-u4-X20"}],"explanation":["1 cm = 10 mm예요.","9 mm는 1 cm를 똑같이 10으로 나눈 것 중의 9예요.","9 mm = ⟨9/10⟩ cm — 소수로는 0.9 cm예요."],"asset":{"type":"mmruler","len":39,"label":"종이 빨대"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L08_basic#2','math',3,2,'u4','L08','tb_g3_2_math_u4_L08_basic','lesson_basic','M3-2-u4-C9',1,'mc','auto','종이 빨대의 길이 4 cm 7 mm는 몇 cm인지 소수로 나타내면 무엇인가요?',ARRAY['M3-2-u4-X17','M3-2-u4-X16']::text[],true,'{"seq":2,"concept":"M3-2-u4-C9","difficulty":1,"kind":"mc","stem":"종이 빨대의 길이 4 cm 7 mm는 몇 cm인지 소수로 나타내면 무엇인가요?","options":[{"t":"4.7 cm","correct":true},{"t":"4.07 cm","mis":"M3-2-u4-X17"},{"t":"7.4 cm","mis":"M3-2-u4-X16"},{"t":"47 cm","mis":"M3-2-u4-X17"}],"explanation":["7 mm는 1 cm를 똑같이 10으로 나눈 것 중의 7 — ⟨7/10⟩ cm = 0.7 cm예요.","4 cm 7 mm = ⟨4 7/10⟩ cm예요.","4 cm 7 mm = 4.7 cm — 「사 점 칠」이라고 읽어요."],"asset":{"type":"mmruler","len":47,"label":"종이 빨대"},"variant_rule":{"alt":[{"stem":"「익힘」 종이 빨대의 길이 3 cm 9 mm는 몇 cm인지 소수로 나타내면 무엇인가요?","options":[{"t":"3.9 cm","correct":true},{"t":"3.09 cm","mis":"M3-2-u4-X17"},{"t":"9.3 cm","mis":"M3-2-u4-X16"},{"t":"39 cm","mis":"M3-2-u4-X17"}],"explanation":["9 mm는 1 cm를 똑같이 10으로 나눈 것 중의 9 — ⟨9/10⟩ cm = 0.9 cm예요.","3 cm 9 mm = ⟨3 9/10⟩ cm예요.","3 cm 9 mm = 3.9 cm — 「삼 점 구」라고 읽어요."],"asset":{"type":"mmruler","len":39,"label":"종이 빨대"}},{"stem":"「익힘」 배추흰나비 애벌레의 길이 2 cm 8 mm는 몇 cm인지 소수로 나타내면 무엇인가요?","options":[{"t":"2.8 cm","correct":true},{"t":"2.08 cm","mis":"M3-2-u4-X17"},{"t":"8.2 cm","mis":"M3-2-u4-X16"},{"t":"28 cm","mis":"M3-2-u4-X17"}],"explanation":["8 mm는 1 cm를 똑같이 10으로 나눈 것 중의 8 — ⟨8/10⟩ cm = 0.8 cm예요.","2 cm 8 mm = ⟨2 8/10⟩ cm예요.","2 cm 8 mm = 2.8 cm — 「이 점 팔」이라고 읽어요."],"asset":{"type":"mmruler","len":28,"label":"애벌레"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L08_basic#3','math',3,2,'u4','L08','tb_g3_2_math_u4_L08_basic','lesson_basic','M3-2-u4-C9',1,'mc','auto','4.7을 바르게 읽은 것은 무엇인가요?',ARRAY['M3-2-u4-X16','M3-2-u4-X17']::text[],true,'{"seq":3,"concept":"M3-2-u4-C9","difficulty":1,"kind":"mc","stem":"4.7을 바르게 읽은 것은 무엇인가요?","options":[{"t":"사 점 칠","correct":true},{"t":"칠 점 사","mis":"M3-2-u4-X16"},{"t":"사십칠","mis":"M3-2-u4-X17"},{"t":"사 점 영칠","mis":"M3-2-u4-X17"}],"explanation":["소수점 왼쪽의 자연수를 먼저 읽고 소수점은 「점」으로 읽어요.","소수점 오른쪽 수는 숫자 그대로 읽어요.","4.7은 「사 점 칠」이라고 읽어요."],"variant_rule":{"alt":[{"stem":"「익힘」 1.9를 바르게 읽은 것은 무엇인가요?","options":[{"t":"일 점 구","correct":true},{"t":"구 점 일","mis":"M3-2-u4-X16"},{"t":"십구","mis":"M3-2-u4-X17"},{"t":"일 점 영구","mis":"M3-2-u4-X17"}],"explanation":["소수점 왼쪽의 자연수를 먼저 읽고 소수점은 「점」으로 읽어요.","소수점 오른쪽 수는 숫자 그대로 읽어요.","1.9는 「일 점 구」라고 읽어요."]},{"stem":"「확인 문제」 9.3을 바르게 읽은 것은 무엇인가요?","options":[{"t":"구 점 삼","correct":true},{"t":"삼 점 구","mis":"M3-2-u4-X16"},{"t":"구십삼","mis":"M3-2-u4-X17"},{"t":"구 점 영삼","mis":"M3-2-u4-X17"}],"explanation":["소수점 왼쪽의 자연수를 먼저 읽고 소수점은 「점」으로 읽어요.","소수점 오른쪽 수는 숫자 그대로 읽어요.","9.3은 「구 점 삼」이라고 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L08_basic#4','math',3,2,'u4','L08','tb_g3_2_math_u4_L08_basic','lesson_basic','M3-2-u4-C9',1,'sa','auto','2.9는 0.1이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u4-C9","difficulty":1,"kind":"sa","stem":"2.9는 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["29"],"explanation":["2는 0.1이 20개예요 — 1은 0.1이 10개예요.","0.9는 0.1이 9개예요.","2.9는 0.1이 20 + 9 = 29개예요."],"variant_rule":{"alt":[{"stem":"「익힘」 1.3은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["1은 0.1이 10개예요 — 1은 0.1이 10개예요.","0.3은 0.1이 3개예요.","1.3은 0.1이 10 + 3 = 13개예요."]},{"stem":"⟨1 4/10⟩를 소수로 쓰면 1.4예요. 1.4는 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["1은 0.1이 10개예요 — 1은 0.1이 10개예요.","0.4는 0.1이 4개예요.","1.4는 0.1이 10 + 4 = 14개예요."]},{"stem":"「준비하기」 0.4는 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["0.1, 0.2, 0.3과 같은 수를 소수라고 해요 — 1학기에 배웠어요.","⟨4/10⟩ = 0.4예요.","0.4는 0.1이 4개예요 — 1보다 큰 소수도 0.1의 개수로 세어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L08_basic#5','math',3,2,'u4','L08','tb_g3_2_math_u4_L08_basic','lesson_basic','M3-2-u4-C9',2,'mc','auto','⟨5 8/10⟩을 소수로 나타내면 무엇인가요?',ARRAY['M3-2-u4-X16','M3-2-u4-X17']::text[],true,'{"seq":5,"concept":"M3-2-u4-C9","difficulty":2,"kind":"mc","stem":"⟨5 8/10⟩을 소수로 나타내면 무엇인가요?","options":[{"t":"5.8","correct":true},{"t":"8.5","mis":"M3-2-u4-X16"},{"t":"5.08","mis":"M3-2-u4-X17"},{"t":"58","mis":"M3-2-u4-X17"}],"explanation":["⟨8/10⟩ = 0.8이에요.","⟨5 8/10⟩은 5와 0.8만큼이에요.","⟨5 8/10⟩ = 5.8 — 「오 점 팔」이라고 읽어요."],"variant_rule":{"alt":[{"stem":"2와 0.4만큼인 수를 소수로 나타내면 무엇인가요?","options":[{"t":"2.4","correct":true},{"t":"4.2","mis":"M3-2-u4-X16"},{"t":"2.04","mis":"M3-2-u4-X17"},{"t":"0.24","mis":"M3-2-u4-X17"}],"explanation":["2와 0.4만큼은 자연수 2와 소수 0.4를 합한 수예요.","⟨2 4/10⟩와 같아요.","2와 0.4만큼은 2.4 — 「이 점 사」라고 읽어요."]},{"stem":"0.1이 35개인 수를 소수로 나타내면 무엇인가요?","options":[{"t":"3.5","correct":true},{"t":"35","mis":"M3-2-u4-X17"},{"t":"0.35","mis":"M3-2-u4-X17"},{"t":"5.3","mis":"M3-2-u4-X16"}],"explanation":["0.1이 10개이면 1이에요.","0.1이 35개는 0.1이 30개(3)와 5개(0.5)예요.","0.1이 35개이면 3.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L08_basic#6','math',3,2,'u4','L08','tb_g3_2_math_u4_L08_basic','lesson_basic','M3-2-u4-C9',2,'mc','auto','46 mm는 몇 cm인지 소수로 나타내면 무엇인가요?',ARRAY['M3-2-u4-X17','M3-2-u4-X16']::text[],true,'{"seq":6,"concept":"M3-2-u4-C9","difficulty":2,"kind":"mc","stem":"46 mm는 몇 cm인지 소수로 나타내면 무엇인가요?","options":[{"t":"4.6 cm","correct":true},{"t":"46 cm","mis":"M3-2-u4-X17"},{"t":"0.46 cm","mis":"M3-2-u4-X17"},{"t":"6.4 cm","mis":"M3-2-u4-X16"}],"explanation":["10 mm = 1 cm예요.","46 mm는 4 cm 6 mm — 4 cm와 ⟨6/10⟩ cm예요.","46 mm = 4.6 cm예요."],"variant_rule":{"alt":[{"stem":"「익힘」 클립의 길이 34 mm는 몇 cm인지 소수로 나타내면 무엇인가요?","options":[{"t":"3.4 cm","correct":true},{"t":"34 cm","mis":"M3-2-u4-X17"},{"t":"0.34 cm","mis":"M3-2-u4-X17"},{"t":"4.3 cm","mis":"M3-2-u4-X16"}],"explanation":["10 mm = 1 cm예요.","34 mm는 3 cm 4 mm — 3 cm와 ⟨4/10⟩ cm예요.","34 mm = 3.4 cm예요."],"asset":{"type":"mmruler","len":34,"label":"클립"}},{"stem":"「익힘」 어제 내린 비의 양 52 mm는 몇 cm인지 소수로 나타내면 무엇인가요?","options":[{"t":"5.2 cm","correct":true},{"t":"52 cm","mis":"M3-2-u4-X17"},{"t":"0.52 cm","mis":"M3-2-u4-X17"},{"t":"2.5 cm","mis":"M3-2-u4-X16"}],"explanation":["10 mm = 1 cm예요.","52 mm는 5 cm 2 mm — 5 cm와 ⟨2/10⟩ cm예요.","52 mm = 5.2 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L08_basic#7','math',3,2,'u4','L08','tb_g3_2_math_u4_L08_basic','lesson_basic','M3-2-u4-C9',2,'match','auto','「확인 문제」 소수와 읽는 방법을 알맞게 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u4-C9","difficulty":2,"kind":"match","stem":"「확인 문제」 소수와 읽는 방법을 알맞게 이으세요.","pairs":[{"l":"3.9","r":"삼 점 구"},{"l":"2.4","r":"이 점 사"},{"l":"9.3","r":"구 점 삼"}],"mis":"M3-2-u4-X16","explanation":["소수점 왼쪽의 자연수를 먼저 읽어요.","3.9는 삼 점 구, 2.4는 이 점 사, 9.3은 구 점 삼이에요.","3.9와 9.3처럼 숫자의 자리가 바뀌면 다른 수예요."],"variant_rule":{"alt":[{"stem":"「익힘」 관계있는 것끼리 알맞게 이으세요.","pairs":[{"l":"7과 0.4만큼인 수","r":"7.4"},{"l":"⟨4 2/10⟩","r":"4.2"},{"l":"⟨4 7/10⟩","r":"4.7"}],"explanation":["7과 0.4만큼인 수는 7.4예요.","⟨4 2/10⟩ = 4.2, ⟨4 7/10⟩ = 4.7이에요.","자연수 부분은 소수점 왼쪽에 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L08_basic#8','math',3,2,'u4','L08','tb_g3_2_math_u4_L08_basic','lesson_basic','M3-2-u4-C9',2,'sa','auto','등산로 팻말에 「정상(2.4 km)」이라고 쓰여 있어요. 2.4는 0.1이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u4-C9","difficulty":2,"kind":"sa","stem":"등산로 팻말에 「정상(2.4 km)」이라고 쓰여 있어요. 2.4는 0.1이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["2는 0.1이 20개예요 — 1은 0.1이 10개예요.","0.4는 0.1이 4개예요.","2.4는 0.1이 20 + 4 = 24개예요."],"variant_rule":{"alt":[{"stem":"50 m 달리기 기록을 측정했더니 11.5초가 나왔어요. 11.5는 0.1이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["115"],"explanation":["11은 0.1이 110개예요 — 1은 0.1이 10개예요.","0.5는 0.1이 5개예요.","11.5는 0.1이 110 + 5 = 115개예요."]},{"stem":"시력을 측정했더니 왼쪽, 오른쪽 모두 1.2였어요. 1.2는 0.1이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["1은 0.1이 10개예요 — 1은 0.1이 10개예요.","0.2는 0.1이 2개예요.","1.2는 0.1이 10 + 2 = 12개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L08_basic#9','math',3,2,'u4','L08','tb_g3_2_math_u4_L08_basic','lesson_basic','M3-2-u4-C9',2,'mc','auto','「익힘」 은비가 키우는 배추흰나비 애벌레의 길이가 2 cm 8 mm예요. 애벌레의 길이를 대분수와 소수로 바르게 나타낸 것은 무엇인가요?',ARRAY['M3-2-u4-X16','M3-2-u4-X17']::text[],true,'{"seq":9,"concept":"M3-2-u4-C9","difficulty":2,"kind":"mc","stem":"「익힘」 은비가 키우는 배추흰나비 애벌레의 길이가 2 cm 8 mm예요. 애벌레의 길이를 대분수와 소수로 바르게 나타낸 것은 무엇인가요?","options":[{"t":"⟨2 8/10⟩ cm, 2.8 cm","correct":true},{"t":"⟨2 8/10⟩ cm, 8.2 cm","mis":"M3-2-u4-X16"},{"t":"⟨8 2/10⟩ cm, 8.2 cm","mis":"M3-2-u4-X16"},{"t":"⟨2 8/10⟩ cm, 2.08 cm","mis":"M3-2-u4-X17"}],"explanation":["8 mm = ⟨8/10⟩ cm = 0.8 cm예요.","2 cm 8 mm = ⟨2 8/10⟩ cm예요.","⟨2 8/10⟩ cm = 2.8 cm예요."],"asset":{"type":"mmruler","len":28,"label":"애벌레"},"variant_rule":{"alt":[{"stem":"「익힘」 종이 빨대의 길이가 3 cm 9 mm예요. 대분수와 소수로 바르게 나타낸 것은 무엇인가요?","options":[{"t":"⟨3 9/10⟩ cm, 3.9 cm","correct":true},{"t":"⟨3 9/10⟩ cm, 9.3 cm","mis":"M3-2-u4-X16"},{"t":"⟨9 3/10⟩ cm, 9.3 cm","mis":"M3-2-u4-X16"},{"t":"⟨3 9/10⟩ cm, 3.09 cm","mis":"M3-2-u4-X17"}],"explanation":["9 mm = ⟨9/10⟩ cm = 0.9 cm예요.","3 cm 9 mm = ⟨3 9/10⟩ cm예요.","⟨3 9/10⟩ cm = 3.9 cm예요."],"asset":{"type":"mmruler","len":39,"label":"종이 빨대"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L08_basic#10','math',3,2,'u4','L08','tb_g3_2_math_u4_L08_basic','lesson_basic','M3-2-u4-C9',3,'sa','auto','「익힘」 신문에 「어제 52 mm의 비가 내렸습니다.」라는 기사가 났어요. 비의 양을 cm로 나타내면 0.1 cm가 몇 개인 길이인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u4-C9","difficulty":3,"kind":"sa","stem":"「익힘」 신문에 「어제 52 mm의 비가 내렸습니다.」라는 기사가 났어요. 비의 양을 cm로 나타내면 0.1 cm가 몇 개인 길이인가요? 숫자로 쓰세요.","answer":["52"],"explanation":["1 mm = 0.1 cm예요.","52 mm = 5.2 cm예요.","5.2는 0.1이 52개 — 0.1 cm가 52개인 길이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L08_challenge#1','math',3,2,'u4','L08','tb_g3_2_math_u4_L08_challenge','lesson_challenge','M3-2-u4-C9',2,'mc','auto','「익힘」 1을 똑같이 10칸으로 나눈 띠 2개 중 19칸을 색칠했어요. 색칠한 부분을 소수로 쓰고 읽은 것으로 알맞은 것은 무엇인가요?',ARRAY['M3-2-u4-X16','M3-2-u4-X17']::text[],false,'{"seq":1,"concept":"M3-2-u4-C9","difficulty":2,"kind":"mc","stem":"「익힘」 1을 똑같이 10칸으로 나눈 띠 2개 중 19칸을 색칠했어요. 색칠한 부분을 소수로 쓰고 읽은 것으로 알맞은 것은 무엇인가요?","options":[{"t":"1.9 — 일 점 구","correct":true},{"t":"1.9 — 구 점 일","mis":"M3-2-u4-X16"},{"t":"9.1 — 구 점 일","mis":"M3-2-u4-X16"},{"t":"0.19 — 영 점 일구","mis":"M3-2-u4-X17"}],"explanation":["띠 하나가 1 — 한 칸은 0.1이에요.","19칸은 0.1이 19개 — 1과 0.9만큼이에요.","1.9라 쓰고 「일 점 구」라고 읽어요."],"asset":{"type":"fbar","bars":[{"den":10,"num":10},{"den":10,"num":9}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L08_challenge#2','math',3,2,'u4','L08','tb_g3_2_math_u4_L08_challenge','lesson_challenge','M3-2-u4-C9',2,'sa','auto','⟨7/10⟩ cm는 0.7 cm예요. 0.7 cm는 몇 mm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u4-C9","difficulty":2,"kind":"sa","stem":"⟨7/10⟩ cm는 0.7 cm예요. 0.7 cm는 몇 mm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["1 cm = 10 mm — 0.1 cm = 1 mm예요.","0.7 cm는 0.1 cm가 7개예요.","0.7 cm = 7 mm예요."],"variant_rule":{"alt":[{"stem":"「익힘」 ⟨9/10⟩ cm는 0.9 cm예요. 0.9 cm는 몇 mm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["1 cm = 10 mm — 0.1 cm = 1 mm예요.","0.9 cm는 0.1 cm가 9개예요.","0.9 cm = 9 mm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L08_challenge#3','math',3,2,'u4','L08','tb_g3_2_math_u4_L08_challenge','lesson_challenge','M3-2-u4-C9',3,'mc','auto','1을 똑같이 10칸으로 나눈 띠 2개 중 14칸을 색칠했어요. 색칠한 부분을 분수로 나타낸 다음 소수로 바르게 쓴 것은 무엇인가요?',ARRAY['M3-2-u4-X15','M3-2-u4-X16','M3-2-u4-X17']::text[],false,'{"seq":3,"concept":"M3-2-u4-C9","difficulty":3,"kind":"mc","stem":"1을 똑같이 10칸으로 나눈 띠 2개 중 14칸을 색칠했어요. 색칠한 부분을 분수로 나타낸 다음 소수로 바르게 쓴 것은 무엇인가요?","options":[{"t":"⟨1 4/10⟩, 1.4","correct":true},{"t":"⟨4/10⟩, 0.4","mis":"M3-2-u4-X15"},{"t":"⟨1 4/10⟩, 4.1","mis":"M3-2-u4-X16"},{"t":"⟨1 4/10⟩, 1.04","mis":"M3-2-u4-X17"}],"explanation":["띠 하나가 통째로 색칠되어 자연수 1이에요.","남은 띠는 10칸 중 4칸 — ⟨4/10⟩ = 0.4예요.","⟨1 4/10⟩ = 1.4 — 「일 점 사」라고 읽어요."],"asset":{"type":"fbar","bars":[{"den":10,"num":10},{"den":10,"num":4}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L08_challenge#4','math',3,2,'u4','L08','tb_g3_2_math_u4_L08_challenge','lesson_challenge','M3-2-u4-C9',3,'error','auto','소수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u4-X17','M3-2-u4-X20']::text[],false,'{"seq":4,"concept":"M3-2-u4-C9","difficulty":3,"kind":"error","stem":"소수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「0.1이 35개이면 0.35야」","correct":true,"mis_target":"M3-2-u4-X17"},{"t":"지훈 — 「⟨5 8/10⟩은 5.8이야」","mis":"M3-2-u4-X20"},{"t":"준우 — 「46 mm는 4.6 cm야」","mis":"M3-2-u4-X20"}],"explanation":["0.1이 10개이면 1이에요.","0.1이 35개는 0.1이 30개(3)와 5개(0.5) — 3.5예요.","서윤이는 0.1의 개수를 소수로 바꿀 때 자리를 잘못 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L08_challenge#5','math',3,2,'u4','L08','tb_g3_2_math_u4_L08_challenge','lesson_challenge','M3-2-u4-C9',3,'mc','auto','「익힘」 ⟨4 2/10⟩와 관계있는 소수는 무엇인가요?',ARRAY['M3-2-u4-X16','M3-2-u4-X17']::text[],true,'{"seq":5,"concept":"M3-2-u4-C9","difficulty":3,"kind":"mc","stem":"「익힘」 ⟨4 2/10⟩와 관계있는 소수는 무엇인가요?","options":[{"t":"4.2","correct":true},{"t":"2.4","mis":"M3-2-u4-X16"},{"t":"4.02","mis":"M3-2-u4-X17"},{"t":"42","mis":"M3-2-u4-X17"}],"explanation":["⟨2/10⟩ = 0.2예요.","⟨4 2/10⟩는 4와 0.2만큼이에요.","⟨4 2/10⟩ = 4.2예요."],"variant_rule":{"alt":[{"stem":"「익힘」 7과 0.4만큼인 수와 관계있는 소수는 무엇인가요?","options":[{"t":"7.4","correct":true},{"t":"4.7","mis":"M3-2-u4-X16"},{"t":"7.04","mis":"M3-2-u4-X17"},{"t":"0.74","mis":"M3-2-u4-X17"}],"explanation":["7과 0.4만큼은 자연수 7과 소수 0.4예요.","⟨7 4/10⟩와 같아요.","7과 0.4만큼인 수는 7.4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L08_challenge#6','math',3,2,'u4','L08','tb_g3_2_math_u4_L08_challenge','lesson_challenge','M3-2-u4-C9',3,'sa','auto','「단원 도입」 3 cm 5 mm는 3.5 cm예요. 3.5는 0.1이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u4-C9","difficulty":3,"kind":"sa","stem":"「단원 도입」 3 cm 5 mm는 3.5 cm예요. 3.5는 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["3은 0.1이 30개예요 — 1은 0.1이 10개예요.","0.5는 0.1이 5개예요.","3.5는 0.1이 30 + 5 = 35개예요."],"variant_rule":{"alt":[{"stem":"종이 빨대의 길이 4 cm 7 mm는 4.7 cm예요. 4.7은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["47"],"explanation":["4는 0.1이 40개예요 — 1은 0.1이 10개예요.","0.7은 0.1이 7개예요.","4.7은 0.1이 40 + 7 = 47개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L08_challenge#7','math',3,2,'u4','L08','tb_g3_2_math_u4_L08_challenge','lesson_challenge','M3-2-u4-C9',3,'mc','auto','터널 입구에 「4.5 m」라고 쓰여 있어요. 4.5 m를 바르게 설명한 것은 무엇인가요?',ARRAY['M3-2-u4-X17','M3-2-u4-X16','M3-2-u4-X15']::text[],false,'{"seq":7,"concept":"M3-2-u4-C9","difficulty":3,"kind":"mc","stem":"터널 입구에 「4.5 m」라고 쓰여 있어요. 4.5 m를 바르게 설명한 것은 무엇인가요?","options":[{"t":"4와 0.5만큼인 높이","correct":true},{"t":"4와 0.05만큼인 높이","mis":"M3-2-u4-X17"},{"t":"5와 0.4만큼인 높이","mis":"M3-2-u4-X16"},{"t":"0.1 m가 5개인 높이","mis":"M3-2-u4-X15"}],"explanation":["4.5는 자연수 4와 소수 0.5를 합한 수예요.","4.5는 0.1이 45개예요.","그래서 4.5 m는 4와 0.5만큼인 높이 — 정확한 높이를 알려 주려면 소수가 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L08_challenge#8','math',3,2,'u4','L08','tb_g3_2_math_u4_L08_challenge','lesson_challenge','M3-2-u4-C9',4,'sa','auto','과학관에서 나비의 날개 길이가 5.8 cm라고 쓰여 있었어요. 5.8 cm는 몇 mm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u4-C9","difficulty":4,"kind":"sa","stem":"과학관에서 나비의 날개 길이가 5.8 cm라고 쓰여 있었어요. 5.8 cm는 몇 mm인가요? 숫자로 쓰세요.","answer":["58"],"explanation":["5.8 cm는 5 cm와 0.8 cm예요.","5 cm = 50 mm, 0.8 cm = 8 mm예요.","5.8 cm = 50 + 8 = 58 mm예요."],"variant_rule":{"alt":[{"stem":"「익힘」 배추흰나비 애벌레의 길이가 2.8 cm예요. 2.8 cm는 몇 mm인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["2.8 cm는 2 cm와 0.8 cm예요.","2 cm = 20 mm, 0.8 cm = 8 mm예요.","2.8 cm = 20 + 8 = 28 mm예요."]},{"stem":"길이가 4.6 cm예요. 4.6 cm는 몇 mm인가요? 숫자로 쓰세요.","answer":["46"],"explanation":["4.6 cm는 4 cm와 0.6 cm예요.","4 cm = 40 mm, 0.6 cm = 6 mm예요.","4.6 cm = 40 + 6 = 46 mm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L08_challenge#9','math',3,2,'u4','L08','tb_g3_2_math_u4_L08_challenge','lesson_challenge','M3-2-u4-C9',4,'essay','teacher','길이가 4 cm 7 mm인 종이 빨대의 길이를 cm 단위의 분수와 소수로 나타내고, 그 방법을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u4-C9","difficulty":4,"kind":"essay","stem":"길이가 4 cm 7 mm인 종이 빨대의 길이를 cm 단위의 분수와 소수로 나타내고, 그 방법을 설명해 보세요.","answer_guide":{"answer":"예: 7 mm는 1 cm를 똑같이 10으로 나눈 것 중의 7이므로 ⟨7/10⟩ cm이다. 그래서 4 cm 7 mm는 ⟨4 7/10⟩ cm이다. ⟨7/10⟩ cm는 0.7 cm이므로 ⟨4 7/10⟩ cm는 4.7 cm로 나타낼 수 있고 「사 점 칠」이라고 읽는다.","scoring_points":["⟨4 7/10⟩ cm를 썼는가","4.7 cm를 썼는가","7 mm = ⟨7/10⟩ cm = 0.7 cm로 설명했는가"]},"explanation":["7 mm = ⟨7/10⟩ cm예요.","4 cm 7 mm = ⟨4 7/10⟩ cm예요.","⟨4 7/10⟩ cm = 4.7 cm예요."],"asset":{"type":"mmruler","len":47,"label":"종이 빨대"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L08_challenge#10','math',3,2,'u4','L08','tb_g3_2_math_u4_L08_challenge','lesson_challenge','M3-2-u4-C9',4,'essay','teacher','2.9는 0.1이 몇 개인지 쓰고, 그렇게 생각한 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u4-C9","difficulty":4,"kind":"essay","stem":"2.9는 0.1이 몇 개인지 쓰고, 그렇게 생각한 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 2.9는 0.1이 29개이다. 0.1이 10개이면 1이므로 2는 0.1이 20개이고, 0.9는 0.1이 9개이다. 그래서 2.9는 0.1이 20 + 9 = 29개이다.","scoring_points":["29개라고 답했는가","2는 0.1이 20개라고 썼는가","0.9는 0.1이 9개라고 썼는가"]},"explanation":["2는 0.1이 20개예요.","0.9는 0.1이 9개예요.","2.9는 0.1이 29개예요."],"asset":{"type":"fbar","bars":[{"den":10,"num":10},{"den":10,"num":10},{"den":10,"num":9}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L09_basic#1','math',3,2,'u4','L09','tb_g3_2_math_u4_L09_basic','lesson_basic','M3-2-u4-C10',1,'mc','auto','건우네 반 친구들이 풍선에 리본을 달아 교실을 꾸몄어요. 초록색 리본의 길이는 1.8 m, 분홍색 리본의 길이는 2.3 m예요. 어느 색 리본이 더 긴가요?',ARRAY['M3-2-u4-X18','M3-2-u4-X22']::text[],true,'{"seq":1,"concept":"M3-2-u4-C10","difficulty":1,"kind":"mc","stem":"건우네 반 친구들이 풍선에 리본을 달아 교실을 꾸몄어요. 초록색 리본의 길이는 1.8 m, 분홍색 리본의 길이는 2.3 m예요. 어느 색 리본이 더 긴가요?","options":[{"t":"분홍색 리본","correct":true},{"t":"초록색 리본","mis":"M3-2-u4-X18"},{"t":"두 리본의 길이가 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수 부분을 비교하면 1 < 2예요.","2.3 m는 2 m보다 길고 1.8 m는 2 m보다 짧아요.","1.8 < 2.3 — 분홍색 리본이 더 길어요. 소수점 오른쪽 8만 보지 않아요."],"variant_rule":{"alt":[{"stem":"「익힘」 초록색 리본의 길이는 2.1 m, 파란색 리본의 길이는 1.5 m예요. 어느 색 리본이 더 긴가요?","options":[{"t":"초록색 리본","correct":true},{"t":"파란색 리본","mis":"M3-2-u4-X18"},{"t":"두 리본의 길이가 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["2.1은 0.1이 21개, 1.5는 0.1이 15개예요.","자연수 부분을 비교하면 2 > 1이에요.","2.1 > 1.5 — 초록색 리본이 더 길어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L09_basic#2','math',3,2,'u4','L09','tb_g3_2_math_u4_L09_basic','lesson_basic','M3-2-u4-C10',1,'sa','auto','1.3은 0.1이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u4-C10","difficulty":1,"kind":"sa","stem":"1.3은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["1은 0.1이 10개예요 — 1은 0.1이 10개예요.","0.3은 0.1이 3개예요.","1.3은 0.1이 10 + 3 = 13개예요."],"variant_rule":{"alt":[{"stem":"1.2는 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["1은 0.1이 10개예요 — 1은 0.1이 10개예요.","0.2는 0.1이 2개예요.","1.2는 0.1이 10 + 2 = 12개예요."]},{"stem":"「익힘」 2.1은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["2는 0.1이 20개예요 — 1은 0.1이 10개예요.","0.1은 0.1이 1개예요.","2.1은 0.1이 20 + 1 = 21개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L09_basic#3','math',3,2,'u4','L09','tb_g3_2_math_u4_L09_basic','lesson_basic','M3-2-u4-C10',1,'mc','auto','두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  3.5 ○ 2.6',ARRAY['M3-2-u4-X18','M3-2-u4-X22']::text[],true,'{"seq":3,"concept":"M3-2-u4-C10","difficulty":1,"kind":"mc","stem":"두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  3.5 ○ 2.6","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u4-X18"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["3.5는 0.1이 35개, 2.6은 0.1이 26개예요.","자연수의 크기를 먼저 비교하고, 같으면 소수점 오른쪽 수의 크기를 비교해요.","그래서 3.5 > 2.6."],"variant_rule":{"alt":[{"stem":"두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  6.2 ○ 6.9","options":[{"t":"<","correct":true},{"t":">","mis":"M3-2-u4-X20"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["6.2는 0.1이 62개, 6.9는 0.1이 69개예요.","자연수의 크기를 먼저 비교하고, 같으면 소수점 오른쪽 수의 크기를 비교해요.","그래서 6.2 < 6.9."]},{"stem":"두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  0.7 ○ 1.2","options":[{"t":"<","correct":true},{"t":">","mis":"M3-2-u4-X18"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["0.7은 0.1이 7개, 1.2는 0.1이 12개예요.","자연수의 크기를 먼저 비교하고, 같으면 소수점 오른쪽 수의 크기를 비교해요.","그래서 0.7 < 1.2."]},{"stem":"두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  14.2 ○ 14.7","options":[{"t":"<","correct":true},{"t":">","mis":"M3-2-u4-X20"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["14.2는 0.1이 142개, 14.7은 0.1이 147개예요.","자연수의 크기를 먼저 비교하고, 같으면 소수점 오른쪽 수의 크기를 비교해요.","그래서 14.2 < 14.7."]},{"stem":"「준비하기」 두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  0.2 ○ 0.5","options":[{"t":"<","correct":true},{"t":">","mis":"M3-2-u4-X20"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["0.2는 0.1이 2개, 0.5는 0.1이 5개예요.","자연수의 크기를 먼저 비교하고, 같으면 소수점 오른쪽 수의 크기를 비교해요.","그래서 0.2 < 0.5."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L09_basic#4','math',3,2,'u4','L09','tb_g3_2_math_u4_L09_basic','lesson_basic','M3-2-u4-C10',1,'mc','auto','1.3과 1.2 중에서 어느 소수가 더 큰가요?',ARRAY['M3-2-u4-X20','M3-2-u4-X22']::text[],true,'{"seq":4,"concept":"M3-2-u4-C10","difficulty":1,"kind":"mc","stem":"1.3과 1.2 중에서 어느 소수가 더 큰가요?","options":[{"t":"1.3","correct":true},{"t":"1.2","mis":"M3-2-u4-X20"},{"t":"두 소수가 같아요","mis":"M3-2-u4-X22"}],"explanation":["1.3은 0.1이 13개, 1.2는 0.1이 12개예요.","자연수의 크기가 같으면 소수점 오른쪽 수의 크기를 비교해요.","3 > 2 — 1.3이 더 커요."],"asset":{"type":"fbar","bars":[{"den":10,"num":10},{"den":10,"num":3}]},"variant_rule":{"alt":[{"stem":"「익힘」 2.1과 1.5 중에서 어느 소수가 더 큰가요?","options":[{"t":"2.1","correct":true},{"t":"1.5","mis":"M3-2-u4-X18"},{"t":"두 소수가 같아요","mis":"M3-2-u4-X22"}],"explanation":["2.1은 0.1이 21개, 1.5는 0.1이 15개예요.","자연수의 크기를 비교하면 2 > 1이에요.","2.1이 더 커요 — 소수점 오른쪽 5가 1보다 커도 2.1이 커요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L09_basic#5','math',3,2,'u4','L09','tb_g3_2_math_u4_L09_basic','lesson_basic','M3-2-u4-C10',2,'mc','auto','50 m 달리기 기록이 준우는 9.8초, 지훈이는 10.1초예요. 누가 더 빠른가요?',ARRAY['M3-2-u4-X19','M3-2-u4-X22']::text[],false,'{"seq":5,"concept":"M3-2-u4-C10","difficulty":2,"kind":"mc","stem":"50 m 달리기 기록이 준우는 9.8초, 지훈이는 10.1초예요. 누가 더 빠른가요?","options":[{"t":"준우","correct":true},{"t":"지훈","mis":"M3-2-u4-X19"},{"t":"두 사람이 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수의 크기를 비교하면 9 < 10이므로 9.8 < 10.1이에요.","달리기 기록은 걸린 시간 — 짧을수록 빨라요.","준우가 더 빨라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L09_basic#6','math',3,2,'u4','L09','tb_g3_2_math_u4_L09_basic','lesson_basic','M3-2-u4-C10',2,'mc','auto','「익힘」 두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  6.3 ○ 4.5',ARRAY['M3-2-u4-X18','M3-2-u4-X22']::text[],true,'{"seq":6,"concept":"M3-2-u4-C10","difficulty":2,"kind":"mc","stem":"「익힘」 두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  6.3 ○ 4.5","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u4-X18"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["6.3은 0.1이 63개, 4.5는 0.1이 45개예요.","자연수의 크기를 먼저 비교하고, 같으면 소수점 오른쪽 수의 크기를 비교해요.","그래서 6.3 > 4.5."],"variant_rule":{"alt":[{"stem":"「익힘」 두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  8.3 ○ 8.7","options":[{"t":"<","correct":true},{"t":">","mis":"M3-2-u4-X20"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["8.3은 0.1이 83개, 8.7은 0.1이 87개예요.","자연수의 크기를 먼저 비교하고, 같으면 소수점 오른쪽 수의 크기를 비교해요.","그래서 8.3 < 8.7."]},{"stem":"「확인 문제」 두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  10.7 ○ 10.5","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u4-X20"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["10.7은 0.1이 107개, 10.5는 0.1이 105개예요.","자연수의 크기를 먼저 비교하고, 같으면 소수점 오른쪽 수의 크기를 비교해요.","그래서 10.7 > 10.5."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L09_basic#7','math',3,2,'u4','L09','tb_g3_2_math_u4_L09_basic','lesson_basic','M3-2-u4-C10',2,'mc','auto','자연수의 크기가 같은 두 소수의 크기를 비교하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['M3-2-u4-X20','M3-2-u4-X22']::text[],false,'{"seq":7,"concept":"M3-2-u4-C10","difficulty":2,"kind":"mc","stem":"자연수의 크기가 같은 두 소수의 크기를 비교하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"소수점 오른쪽 수의 크기를 비교한다","correct":true},{"t":"소수점 오른쪽 수가 작을수록 더 크다","mis":"M3-2-u4-X20"},{"t":"자연수가 같으면 두 소수의 크기는 같다","mis":"M3-2-u4-X22"},{"t":"소수는 수직선에 나타내야만 비교할 수 있다","mis":"M3-2-u4-X22"}],"explanation":["1.3과 1.2는 자연수가 1로 같아요.","소수점 오른쪽 수를 비교하면 3 > 2예요.","그래서 1.3 > 1.2 — 0.1의 개수 13개와 12개로 견주어도 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L09_basic#8','math',3,2,'u4','L09','tb_g3_2_math_u4_L09_basic','lesson_basic','M3-2-u4-C10',2,'ox','auto','건우는 「0.7은 7이 2보다 크니까 1.2보다 커.」라고 했어요. 건우의 말이 옳은가요?',ARRAY['M3-2-u4-X18']::text[],true,'{"seq":8,"concept":"M3-2-u4-C10","difficulty":2,"kind":"ox","stem":"건우는 「0.7은 7이 2보다 크니까 1.2보다 커.」라고 했어요. 건우의 말이 옳은가요?","answer":"X","reason_options":[{"t":"자연수 부분 0이 1보다 작아서","correct":true},{"t":"소수점 오른쪽 수 7이 2보다 커서","mis":"M3-2-u4-X18"}],"mis":"M3-2-u4-X18","explanation":["0.7은 0.1이 7개, 1.2는 0.1이 12개예요.","자연수의 크기를 먼저 비교하면 0 < 1이에요.","0.7 < 1.2 — 건우의 말은 옳지 않아요."],"variant_rule":{"alt":[{"stem":"「확인 문제」 은비는 「1.9는 1.7보다 커.」라고 했어요. 은비의 말이 옳은가요?","answer":"O","reason_options":[{"t":"자연수가 같고 소수점 오른쪽 수 9가 7보다 커서","correct":true},{"t":"두 소수는 자연수가 같아서 크기가 같으니까","mis":"M3-2-u4-X22"}],"explanation":["1.9와 1.7은 자연수가 1로 같아요.","소수점 오른쪽 수를 비교하면 9 > 7이에요.","1.9 > 1.7 — 은비의 말이 옳아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L09_basic#9','math',3,2,'u4','L09','tb_g3_2_math_u4_L09_basic','lesson_basic','M3-2-u4-C10',2,'mc','auto','「익힘」 다람쥐가 갈림길마다 더 큰 소수를 따라가요. 갈림길의 두 소수는 차례대로 3.6과 3.4, 1.9와 2.1, 5.6과 5.1, 1.4와 0.7이에요. 다람쥐가 따라간 소수를 차례대로 바르게 쓴 것은 무엇인가요?',ARRAY['M3-2-u4-X20','M3-2-u4-X18']::text[],false,'{"seq":9,"concept":"M3-2-u4-C10","difficulty":2,"kind":"mc","stem":"「익힘」 다람쥐가 갈림길마다 더 큰 소수를 따라가요. 갈림길의 두 소수는 차례대로 3.6과 3.4, 1.9와 2.1, 5.6과 5.1, 1.4와 0.7이에요. 다람쥐가 따라간 소수를 차례대로 바르게 쓴 것은 무엇인가요?","options":[{"t":"3.6, 2.1, 5.6, 1.4","correct":true},{"t":"3.4, 1.9, 5.1, 0.7","mis":"M3-2-u4-X20"},{"t":"3.6, 1.9, 5.6, 0.7","mis":"M3-2-u4-X18"},{"t":"3.6, 2.1, 5.6, 0.7","mis":"M3-2-u4-X18"}],"explanation":["3.6 > 3.4, 5.6 > 5.1 — 자연수가 같아 소수점 오른쪽 수를 비교해요.","1.9 < 2.1, 1.4 > 0.7 — 자연수의 크기를 먼저 비교해요.","따라간 소수는 3.6, 2.1, 5.6, 1.4예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L09_basic#10','math',3,2,'u4','L09','tb_g3_2_math_u4_L09_basic','lesson_basic','M3-2-u4-C10',3,'mc','auto','「익힘」 큐브 빨리 맞추기 대회에서 서준이는 7.3초, 건우는 6.7초, 도윤이는 6.5초가 걸렸어요. 가장 빨리 큐브를 맞춘 사람은 누구인가요?',ARRAY['M3-2-u4-X19','M3-2-u4-X20','M3-2-u4-X22']::text[],false,'{"seq":10,"concept":"M3-2-u4-C10","difficulty":3,"kind":"mc","stem":"「익힘」 큐브 빨리 맞추기 대회에서 서준이는 7.3초, 건우는 6.7초, 도윤이는 6.5초가 걸렸어요. 가장 빨리 큐브를 맞춘 사람은 누구인가요?","options":[{"t":"도윤","correct":true},{"t":"서준","mis":"M3-2-u4-X19"},{"t":"건우","mis":"M3-2-u4-X20"},{"t":"세 사람이 같아요","mis":"M3-2-u4-X22"}],"explanation":["자연수의 크기를 비교하면 7.3이 가장 커요.","6.7과 6.5는 자연수가 같고 7 > 5이므로 6.7 > 6.5 — 가장 작은 수는 6.5예요.","걸린 시간이 가장 짧은 도윤이가 가장 빨리 맞췄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L09_challenge#1','math',3,2,'u4','L09','tb_g3_2_math_u4_L09_challenge','lesson_challenge','M3-2-u4-C10',2,'mc','auto','「익힘」 수 카드 4, 7, 3, 5, 1, 8 중에서 2장을 뽑아 한 번씩만 사용하여 □.□ 꼴의 소수를 만들려고 해요. 가장 큰 소수와 가장 작은 소수를 바르게 쓴 것은 무엇인가요?',ARRAY['M3-2-u4-X18','M3-2-u4-X20']::text[],false,'{"seq":1,"concept":"M3-2-u4-C10","difficulty":2,"kind":"mc","stem":"「익힘」 수 카드 4, 7, 3, 5, 1, 8 중에서 2장을 뽑아 한 번씩만 사용하여 □.□ 꼴의 소수를 만들려고 해요. 가장 큰 소수와 가장 작은 소수를 바르게 쓴 것은 무엇인가요?","options":[{"t":"8.7, 1.3","correct":true},{"t":"7.8, 1.3","mis":"M3-2-u4-X18"},{"t":"1.3, 8.7","mis":"M3-2-u4-X20"},{"t":"8.7, 3.1","mis":"M3-2-u4-X18"}],"explanation":["가장 큰 소수는 자연수 자리에 가장 큰 8, 소수점 오른쪽에 그다음 큰 7 — 8.7이에요.","가장 작은 소수는 자연수 자리에 가장 작은 1, 소수점 오른쪽에 그다음 작은 3 — 1.3이에요.","자연수 자리가 크기를 먼저 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L09_challenge#2','math',3,2,'u4','L09','tb_g3_2_math_u4_L09_challenge','lesson_challenge','M3-2-u4-C10',2,'sa','auto','주사위 1개를 2번 굴려 1과 6이 나왔어요. 나온 수로 1.6과 6.1을 만들었어요. 둘 중 더 큰 소수는 0.1이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M3-2-u4-C10","difficulty":2,"kind":"sa","stem":"주사위 1개를 2번 굴려 1과 6이 나왔어요. 나온 수로 1.6과 6.1을 만들었어요. 둘 중 더 큰 소수는 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["61"],"explanation":["1.6과 6.1의 자연수를 비교하면 1 < 6 — 6.1이 더 커요.","6은 0.1이 60개, 0.1은 0.1이 1개예요.","6.1은 0.1이 61개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L09_challenge#3','math',3,2,'u4','L09','tb_g3_2_math_u4_L09_challenge','lesson_challenge','M3-2-u4-C10',3,'mc','auto','「익힘」 작은 수부터 차례대로 기호를 바르게 쓴 것은 무엇인가요?  ㉠ 5.7  ㉡ 5와 0.8만큼인 수  ㉢ 0.1이 55개인 수',ARRAY['M3-2-u4-X20','M3-2-u4-X17','M3-2-u4-X18']::text[],false,'{"seq":3,"concept":"M3-2-u4-C10","difficulty":3,"kind":"mc","stem":"「익힘」 작은 수부터 차례대로 기호를 바르게 쓴 것은 무엇인가요?  ㉠ 5.7  ㉡ 5와 0.8만큼인 수  ㉢ 0.1이 55개인 수","options":[{"t":"㉢, ㉠, ㉡","correct":true},{"t":"㉡, ㉠, ㉢","mis":"M3-2-u4-X20"},{"t":"㉠, ㉡, ㉢","mis":"M3-2-u4-X17"},{"t":"㉢, ㉡, ㉠","mis":"M3-2-u4-X18"}],"explanation":["㉡ 5와 0.8만큼인 수는 5.8, ㉢ 0.1이 55개인 수는 5.5예요.","자연수가 모두 5이므로 소수점 오른쪽 수를 비교하면 5 < 7 < 8이에요.","작은 수부터 ㉢ 5.5, ㉠ 5.7, ㉡ 5.8이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L09_challenge#4','math',3,2,'u4','L09','tb_g3_2_math_u4_L09_challenge','lesson_challenge','M3-2-u4-C10',3,'mc','auto','등산로 팻말에 쉼터 1.3 km, 정상 2.4 km, 둘레길 1.8 km라고 쓰여 있어요. 가장 가까운 곳은 어디인가요?',ARRAY['M3-2-u4-X20','M3-2-u4-X18','M3-2-u4-X22']::text[],false,'{"seq":4,"concept":"M3-2-u4-C10","difficulty":3,"kind":"mc","stem":"등산로 팻말에 쉼터 1.3 km, 정상 2.4 km, 둘레길 1.8 km라고 쓰여 있어요. 가장 가까운 곳은 어디인가요?","options":[{"t":"쉼터","correct":true},{"t":"정상","mis":"M3-2-u4-X20"},{"t":"둘레길","mis":"M3-2-u4-X18"},{"t":"세 곳이 모두 같아요","mis":"M3-2-u4-X22"}],"explanation":["자연수의 크기를 비교하면 2.4가 가장 커요.","1.3과 1.8은 자연수가 같고 3 < 8이에요.","가장 작은 수는 1.3 — 쉼터가 가장 가까워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L09_challenge#5','math',3,2,'u4','L09','tb_g3_2_math_u4_L09_challenge','lesson_challenge','M3-2-u4-C10',3,'error','auto','「익힘」 큐브 기록(서준 7.3초, 건우 6.7초, 도윤 6.5초)을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u4-X19','M3-2-u4-X20']::text[],false,'{"seq":5,"concept":"M3-2-u4-C10","difficulty":3,"kind":"error","stem":"「익힘」 큐브 기록(서준 7.3초, 건우 6.7초, 도윤 6.5초)을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하윤 — 「7.3이 가장 큰 수니까 서준이가 가장 빨라」","correct":true,"mis_target":"M3-2-u4-X19"},{"t":"채원 — 「자연수를 비교하면 7.3이 가장 커」","mis":"M3-2-u4-X20"},{"t":"지유 — 「6.7 > 6.5니까 도윤이가 가장 빨리 맞췄어」","mis":"M3-2-u4-X20"}],"explanation":["큐브 기록은 걸린 시간이에요.","걸린 시간이 짧을수록 빨리 맞춘 거예요.","가장 작은 수 6.5 — 도윤이가 가장 빨라요. 하윤이는 큰 수를 빠르다고 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L09_challenge#6','math',3,2,'u4','L09','tb_g3_2_math_u4_L09_challenge','lesson_challenge','M3-2-u4-C10',3,'mc','auto','「익힘」 1.3과 2.2를 수직선에 나타냈어요. 알맞은 말은 무엇인가요?',ARRAY['M3-2-u4-X18','M3-2-u4-X22']::text[],false,'{"seq":6,"concept":"M3-2-u4-C10","difficulty":3,"kind":"mc","stem":"「익힘」 1.3과 2.2를 수직선에 나타냈어요. 알맞은 말은 무엇인가요?","options":[{"t":"1.3이 2.2보다 작습니다","correct":true},{"t":"1.3이 2.2보다 큽니다","mis":"M3-2-u4-X18"},{"t":"두 소수의 크기가 같습니다","mis":"M3-2-u4-X22"}],"explanation":["1.3은 0.1이 13개, 2.2는 0.1이 22개예요.","자연수의 크기를 비교하면 1 < 2예요.","1.3 < 2.2 — 소수점 오른쪽 3이 2보다 커도 1.3이 작아요."],"asset":{"type":"fbar","bars":[{"den":10,"num":10},{"den":10,"num":10},{"den":10,"num":2}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L09_challenge#7','math',3,2,'u4','L09','tb_g3_2_math_u4_L09_challenge','lesson_challenge','M3-2-u4-C10',3,'sa','auto','50 m 달리기 기록이 지훈이는 10.1초예요. 10.1은 0.1이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M3-2-u4-C10","difficulty":3,"kind":"sa","stem":"50 m 달리기 기록이 지훈이는 10.1초예요. 10.1은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["101"],"explanation":["10은 0.1이 100개예요 — 1은 0.1이 10개예요.","0.1은 0.1이 1개예요.","10.1은 0.1이 100 + 1 = 101개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L09_challenge#8','math',3,2,'u4','L09','tb_g3_2_math_u4_L09_challenge','lesson_challenge','M3-2-u4-C10',4,'mc','auto','「익힘」 수 카드 4, 7, 3, 5, 1, 8 중에서 2장을 뽑아 한 번씩만 사용하여 □.□ 꼴의 소수를 만들려고 해요. 두 번째로 큰 소수는 무엇인가요?',ARRAY['M3-2-u4-X18','M3-2-u4-X20','M3-2-u4-X21']::text[],false,'{"seq":8,"concept":"M3-2-u4-C10","difficulty":4,"kind":"mc","stem":"「익힘」 수 카드 4, 7, 3, 5, 1, 8 중에서 2장을 뽑아 한 번씩만 사용하여 □.□ 꼴의 소수를 만들려고 해요. 두 번째로 큰 소수는 무엇인가요?","options":[{"t":"8.5","correct":true},{"t":"7.8","mis":"M3-2-u4-X18"},{"t":"8.7","mis":"M3-2-u4-X20"},{"t":"8.4","mis":"M3-2-u4-X21"}],"explanation":["자연수 자리에 가장 큰 8을 놓으면 8.7, 8.5, 8.4, 8.3, 8.1을 만들 수 있어요.","가장 큰 소수는 8.7이에요.","두 번째로 큰 소수는 8.5 — 7.8은 자연수가 7이라 더 작아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L09_challenge#9','math',3,2,'u4','L09','tb_g3_2_math_u4_L09_challenge','lesson_challenge','M3-2-u4-C10',4,'essay','teacher','3.5와 2.6의 크기를 비교하고, 그 방법을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u4-C10","difficulty":4,"kind":"essay","stem":"3.5와 2.6의 크기를 비교하고, 그 방법을 설명해 보세요.","answer_guide":{"answer":"예: 3.5 > 2.6이다. 자연수의 크기를 먼저 비교하면 3 > 2이므로 3.5가 2.6보다 더 크다. 0.1의 개수로 보면 3.5는 0.1이 35개, 2.6은 0.1이 26개이므로 35 > 26이다.","scoring_points":["3.5 > 2.6이라고 답했는가","자연수의 크기를 먼저 비교했는가","0.1의 개수나 수직선으로 확인했는가"]},"explanation":["자연수 3 > 2예요.","0.1이 35개 > 26개예요.","3.5가 더 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L09_challenge#10','math',3,2,'u4','L09','tb_g3_2_math_u4_L09_challenge','lesson_challenge','M3-2-u4-C10',4,'essay','teacher','「익힘」 큐브 빨리 맞추기 대회에서 서준이는 7.3초, 건우는 6.7초, 도윤이는 6.5초가 걸렸어요. 가장 빨리 큐브를 맞춘 사람은 누구인지 풀이 과정을 쓰고 답을 구해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u4-C10","difficulty":4,"kind":"essay","stem":"「익힘」 큐브 빨리 맞추기 대회에서 서준이는 7.3초, 건우는 6.7초, 도윤이는 6.5초가 걸렸어요. 가장 빨리 큐브를 맞춘 사람은 누구인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 자연수의 크기를 비교하면 7.3이 가장 크다. 6.7과 6.5는 자연수가 같으므로 소수점 오른쪽 수를 비교하면 6.7 > 6.5이다. 가장 작은 수는 6.5이므로 걸린 시간이 가장 짧은 도윤이가 가장 빨리 맞췄다.","scoring_points":["자연수의 크기를 먼저 비교했는가","6.7 > 6.5를 비교했는가","걸린 시간이 가장 짧은 도윤이라고 답했는가"]},"explanation":["7.3이 가장 커요.","6.7 > 6.5예요.","도윤이가 가장 빨라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L10_basic#1','math',3,2,'u4','L10','tb_g3_2_math_u4_L10_basic','lesson_basic','M3-2-u4-C11',1,'mc','auto','분수 마을에 ⟨2 5/10⟩와 ⟨3 1/10⟩이 모였어요. 두 분수 중 더 큰 수는 무엇인가요?',ARRAY['M3-2-u4-X13','M3-2-u4-X22']::text[],false,'{"seq":1,"concept":"M3-2-u4-C11","difficulty":1,"kind":"mc","stem":"분수 마을에 ⟨2 5/10⟩와 ⟨3 1/10⟩이 모였어요. 두 분수 중 더 큰 수는 무엇인가요?","options":[{"t":"⟨3 1/10⟩","correct":true},{"t":"⟨2 5/10⟩","mis":"M3-2-u4-X13"},{"t":"두 수가 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["분모가 같은 대분수는 자연수의 크기를 먼저 비교해요.","자연수를 비교하면 2 < 3이에요.","⟨2 5/10⟩ < ⟨3 1/10⟩ — 진분수 5가 1보다 커도 ⟨3 1/10⟩이 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L10_basic#2','math',3,2,'u4','L10','tb_g3_2_math_u4_L10_basic','lesson_basic','M3-2-u4-C11',1,'mc','auto','소수 마을에 3.6과 2.8이 모였어요. 두 소수 중 더 큰 수는 무엇인가요?',ARRAY['M3-2-u4-X18','M3-2-u4-X22']::text[],false,'{"seq":2,"concept":"M3-2-u4-C11","difficulty":1,"kind":"mc","stem":"소수 마을에 3.6과 2.8이 모였어요. 두 소수 중 더 큰 수는 무엇인가요?","options":[{"t":"3.6","correct":true},{"t":"2.8","mis":"M3-2-u4-X18"},{"t":"두 수가 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수의 크기를 먼저 비교해요.","자연수를 비교하면 3 > 2예요.","3.6 > 2.8 — 소수점 오른쪽 8이 6보다 커도 3.6이 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L10_basic#3','math',3,2,'u4','L10','tb_g3_2_math_u4_L10_basic','lesson_basic','M3-2-u4-C11',1,'mc','auto','⟨3 1/10⟩을 소수로 나타내면 무엇인가요?',ARRAY['M3-2-u4-X16','M3-2-u4-X17']::text[],true,'{"seq":3,"concept":"M3-2-u4-C11","difficulty":1,"kind":"mc","stem":"⟨3 1/10⟩을 소수로 나타내면 무엇인가요?","options":[{"t":"3.1","correct":true},{"t":"1.3","mis":"M3-2-u4-X16"},{"t":"3.01","mis":"M3-2-u4-X17"},{"t":"31","mis":"M3-2-u4-X17"}],"explanation":["⟨1/10⟩ = 0.1이에요.","⟨3 1/10⟩은 3과 0.1만큼이에요.","⟨3 1/10⟩ = 3.1이에요."],"variant_rule":{"alt":[{"stem":"3.6을 분수로 나타내면 무엇인가요?","options":[{"t":"⟨3 6/10⟩","correct":true},{"t":"⟨6 3/10⟩","mis":"M3-2-u4-X16"},{"t":"⟨6/10⟩","mis":"M3-2-u4-X15"},{"t":"⟨3/6⟩","mis":"M3-2-u4-X03"}],"explanation":["0.6 = ⟨6/10⟩이에요.","3.6은 3과 0.6만큼이에요.","3.6 = ⟨3 6/10⟩이에요."]},{"stem":"「익힘」 ⟨8 5/10⟩를 소수로 나타내면 무엇인가요?","options":[{"t":"8.5","correct":true},{"t":"5.8","mis":"M3-2-u4-X16"},{"t":"8.05","mis":"M3-2-u4-X17"},{"t":"85","mis":"M3-2-u4-X17"}],"explanation":["⟨5/10⟩ = 0.5예요.","⟨8 5/10⟩는 8과 0.5만큼이에요.","⟨8 5/10⟩ = 8.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L10_basic#4','math',3,2,'u4','L10','tb_g3_2_math_u4_L10_basic','lesson_basic','M3-2-u4-C11',1,'mc','auto','분수와 소수의 크기를 비교하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['M3-2-u4-X22','M3-2-u4-X14']::text[],false,'{"seq":4,"concept":"M3-2-u4-C11","difficulty":1,"kind":"mc","stem":"분수와 소수의 크기를 비교하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"분수를 소수로 나타내거나 소수를 분수로 나타내어 비교한다","correct":true},{"t":"분수와 소수는 크기를 비교할 수 없다","mis":"M3-2-u4-X22"},{"t":"분자와 소수점 오른쪽 수만 비교한다","mis":"M3-2-u4-X14"},{"t":"분수가 소수보다 항상 크다","mis":"M3-2-u4-X14"}],"explanation":["분모가 10인 분수는 소수로 바꿀 수 있어요 — ⟨3 1/10⟩ = 3.1이에요.","소수도 분수로 바꿀 수 있어요 — 3.6 = ⟨3 6/10⟩이에요.","같은 꼴로 바꾸면 크기를 비교할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L10_basic#5','math',3,2,'u4','L10','tb_g3_2_math_u4_L10_basic','lesson_basic','M3-2-u4-C11',2,'mc','auto','분수 마을과 소수 마을에 ⟨2 5/10⟩, ⟨3 1/10⟩, 3.6, 2.8이 모였어요. 가장 큰 수는 무엇인가요?',ARRAY['M3-2-u4-X14','M3-2-u4-X13','M3-2-u4-X18']::text[],false,'{"seq":5,"concept":"M3-2-u4-C11","difficulty":2,"kind":"mc","stem":"분수 마을과 소수 마을에 ⟨2 5/10⟩, ⟨3 1/10⟩, 3.6, 2.8이 모였어요. 가장 큰 수는 무엇인가요?","options":[{"t":"3.6","correct":true},{"t":"⟨3 1/10⟩","mis":"M3-2-u4-X14"},{"t":"⟨2 5/10⟩","mis":"M3-2-u4-X13"},{"t":"2.8","mis":"M3-2-u4-X18"}],"explanation":["분수끼리 비교하면 ⟨3 1/10⟩이 크고, 소수끼리 비교하면 3.6이 커요.","⟨3 1/10⟩ = 3.1이에요.","3.1 < 3.6 — 가장 큰 수는 3.6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L10_basic#6','math',3,2,'u4','L10','tb_g3_2_math_u4_L10_basic','lesson_basic','M3-2-u4-C11',2,'mc','auto','두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨3 1/10⟩ ○ 3.6',ARRAY['M3-2-u4-X14','M3-2-u4-X22']::text[],true,'{"seq":6,"concept":"M3-2-u4-C11","difficulty":2,"kind":"mc","stem":"두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨3 1/10⟩ ○ 3.6","options":[{"t":"<","correct":true},{"t":">","mis":"M3-2-u4-X14"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["분모가 10인 분수는 소수로 나타내어 비교할 수 있어요.","⟨3 1/10⟩ = 3.1이에요.","자연수부터 비교하면 ⟨3 1/10⟩ < 3.6."],"variant_rule":{"alt":[{"stem":"「익힘」 두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨8 5/10⟩ ○ 8.8","options":[{"t":"<","correct":true},{"t":">","mis":"M3-2-u4-X14"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["분모가 10인 분수는 소수로 나타내어 비교할 수 있어요.","⟨8 5/10⟩ = 8.5예요.","자연수부터 비교하면 ⟨8 5/10⟩ < 8.8."]},{"stem":"「익힘」 두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨83/10⟩ ○ ⟨8 5/10⟩","options":[{"t":"<","correct":true},{"t":">","mis":"M3-2-u4-X14"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["⟨8 5/10⟩를 가분수로 나타내면 ⟨85/10⟩예요.","분자를 비교하면 83 < 85예요.","그래서 ⟨83/10⟩ < ⟨8 5/10⟩."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L10_basic#7','math',3,2,'u4','L10','tb_g3_2_math_u4_L10_basic','lesson_basic','M3-2-u4-C11',2,'sa','auto','자연수 1부터 9까지의 수 중에서 ⟨1 □/10⟩ > ⟨1 7/10⟩이 되도록 □에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u4-C11","difficulty":2,"kind":"sa","stem":"자연수 1부터 9까지의 수 중에서 ⟨1 □/10⟩ > ⟨1 7/10⟩이 되도록 □에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["두 분수는 자연수가 1로 같아요.","진분수를 비교하면 □ > 7이어야 해요.","□에는 8, 9 — 모두 2개예요. 7은 두 수가 같아서 안 돼요."],"variant_rule":{"alt":[{"stem":"자연수 1부터 9까지의 수 중에서 1.□ > 1.6이 되도록 □에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["두 소수는 자연수가 1로 같아요.","소수점 오른쪽 수를 비교하면 □ > 6이어야 해요.","□에는 7, 8, 9 — 모두 3개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L10_basic#8','math',3,2,'u4','L10','tb_g3_2_math_u4_L10_basic','lesson_basic','M3-2-u4-C11',2,'mc','auto','「익힘」 ⟨83/10⟩과 ⟨8 5/10⟩ 중 더 큰 수는 무엇인가요?',ARRAY['M3-2-u4-X14','M3-2-u4-X22']::text[],true,'{"seq":8,"concept":"M3-2-u4-C11","difficulty":2,"kind":"mc","stem":"「익힘」 ⟨83/10⟩과 ⟨8 5/10⟩ 중 더 큰 수는 무엇인가요?","options":[{"t":"⟨8 5/10⟩","correct":true},{"t":"⟨83/10⟩","mis":"M3-2-u4-X14"},{"t":"두 수가 같아요","mis":"M3-2-u4-X22"}],"explanation":["⟨83/10⟩을 대분수로 나타내면 ⟨8 3/10⟩이에요.","자연수가 같으니 진분수를 비교하면 ⟨3/10⟩ < ⟨5/10⟩예요.","⟨83/10⟩ < ⟨8 5/10⟩ — 분자 83이 크다고 큰 수가 아니에요."],"variant_rule":{"alt":[{"stem":"「익힘」 8.8과 7.9 중 더 큰 수는 무엇인가요?","options":[{"t":"8.8","correct":true},{"t":"7.9","mis":"M3-2-u4-X18"},{"t":"두 수가 같아요","mis":"M3-2-u4-X22"}],"explanation":["자연수의 크기를 비교하면 8 > 7이에요.","소수점 오른쪽 9가 8보다 커도 자연수가 먼저예요.","8.8 > 7.9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L10_basic#9','math',3,2,'u4','L10','tb_g3_2_math_u4_L10_basic','lesson_basic','M3-2-u4-C11',2,'ox','auto','도윤이는 「⟨3 1/10⟩은 3.1이라서 3.6보다 작아.」라고 했어요. 도윤이의 말이 옳은가요?',ARRAY['M3-2-u4-X22']::text[],true,'{"seq":9,"concept":"M3-2-u4-C11","difficulty":2,"kind":"ox","stem":"도윤이는 「⟨3 1/10⟩은 3.1이라서 3.6보다 작아.」라고 했어요. 도윤이의 말이 옳은가요?","answer":"O","reason_options":[{"t":"⟨3 1/10⟩ = 3.1이고 3.1 < 3.6이라서","correct":true},{"t":"분수와 소수는 크기를 비교할 수 없으니까","mis":"M3-2-u4-X22"}],"mis":"M3-2-u4-X22","explanation":["⟨1/10⟩ = 0.1이므로 ⟨3 1/10⟩ = 3.1이에요.","3.1과 3.6은 자연수가 같고 1 < 6이에요.","⟨3 1/10⟩ < 3.6 — 도윤이의 말이 옳아요."],"variant_rule":{"alt":[{"stem":"「익힘」 서준이는 「⟨8 5/10⟩는 분수라서 8.8보다 커.」라고 했어요. 서준이의 말이 옳은가요?","answer":"X","reason_options":[{"t":"⟨8 5/10⟩ = 8.5이고 8.5 < 8.8이라서","correct":true},{"t":"분수가 소수보다 크니까","mis":"M3-2-u4-X14"}],"explanation":["⟨8 5/10⟩ = 8.5예요.","8.5와 8.8은 자연수가 같고 5 < 8이에요.","⟨8 5/10⟩ < 8.8 — 서준이의 말은 옳지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L10_basic#10','math',3,2,'u4','L10','tb_g3_2_math_u4_L10_basic','lesson_basic','M3-2-u4-C11',3,'mc','auto','마을에 모인 ⟨2 5/10⟩, ⟨3 1/10⟩, 3.6, 2.8 중에서 가장 큰 수를 찾으려고 자연수의 크기를 먼저 비교했어요. 가장 큰 수가 될 수 있는 두 수는 무엇인가요?',ARRAY['M3-2-u4-X20','M3-2-u4-X18','M3-2-u4-X13']::text[],false,'{"seq":10,"concept":"M3-2-u4-C11","difficulty":3,"kind":"mc","stem":"마을에 모인 ⟨2 5/10⟩, ⟨3 1/10⟩, 3.6, 2.8 중에서 가장 큰 수를 찾으려고 자연수의 크기를 먼저 비교했어요. 가장 큰 수가 될 수 있는 두 수는 무엇인가요?","options":[{"t":"⟨3 1/10⟩과 3.6","correct":true},{"t":"⟨2 5/10⟩와 2.8","mis":"M3-2-u4-X20"},{"t":"⟨3 1/10⟩과 2.8","mis":"M3-2-u4-X18"},{"t":"⟨2 5/10⟩와 3.6","mis":"M3-2-u4-X13"}],"explanation":["자연수가 3인 수는 ⟨3 1/10⟩과 3.6, 자연수가 2인 수는 ⟨2 5/10⟩와 2.8이에요.","자연수가 3인 두 수가 2인 수보다 커요.","⟨3 1/10⟩ = 3.1과 3.6을 비교하면 가장 큰 수는 3.6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L10_challenge#1','math',3,2,'u4','L10','tb_g3_2_math_u4_L10_challenge','lesson_challenge','M3-2-u4-C11',2,'sa','auto','⟨1 □/10⟩ > ⟨1 7/10⟩이 되도록 □에 들어갈 수 있는 가장 작은 자연수를 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u4-C11","difficulty":2,"kind":"sa","stem":"⟨1 □/10⟩ > ⟨1 7/10⟩이 되도록 □에 들어갈 수 있는 가장 작은 자연수를 쓰세요.","answer":["8"],"explanation":["두 분수는 자연수가 1로 같아요.","□는 7보다 커야 해요 — 8, 9가 들어갈 수 있어요.","가장 작은 수는 8이에요."],"variant_rule":{"alt":[{"stem":"1.□ > 1.6이 되도록 □에 들어갈 수 있는 가장 작은 자연수를 쓰세요.","answer":["7"],"explanation":["두 소수는 자연수가 1로 같아요.","□는 6보다 커야 해요 — 7, 8, 9가 들어갈 수 있어요.","가장 작은 수는 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L10_challenge#2','math',3,2,'u4','L10','tb_g3_2_math_u4_L10_challenge','lesson_challenge','M3-2-u4-C11',2,'mc','auto','「익힘」 ⟨8 5/10⟩와 8.8 중 더 큰 수는 무엇인가요?',ARRAY['M3-2-u4-X14','M3-2-u4-X22']::text[],false,'{"seq":2,"concept":"M3-2-u4-C11","difficulty":2,"kind":"mc","stem":"「익힘」 ⟨8 5/10⟩와 8.8 중 더 큰 수는 무엇인가요?","options":[{"t":"8.8","correct":true},{"t":"⟨8 5/10⟩","mis":"M3-2-u4-X14"},{"t":"두 수가 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["⟨8 5/10⟩ = 8.5예요.","8.5와 8.8은 자연수가 같고 5 < 8이에요.","⟨8 5/10⟩ < 8.8 — 8.8이 더 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L10_challenge#3','math',3,2,'u4','L10','tb_g3_2_math_u4_L10_challenge','lesson_challenge','M3-2-u4-C11',3,'mc','auto','⟨1 □/10⟩과 1.△의 크기를 비교했더니 ⟨1 □/10⟩이 더 컸어요. □에는 8 또는 9, △에는 7, 8, 9 중 하나가 들어가요. □가 8일 때 △에 들어갈 수 있는 수를 모두 고른 것은 무엇인가요?',ARRAY['M3-2-u4-X21','M3-2-u4-X20']::text[],false,'{"seq":3,"concept":"M3-2-u4-C11","difficulty":3,"kind":"mc","stem":"⟨1 □/10⟩과 1.△의 크기를 비교했더니 ⟨1 □/10⟩이 더 컸어요. □에는 8 또는 9, △에는 7, 8, 9 중 하나가 들어가요. □가 8일 때 △에 들어갈 수 있는 수를 모두 고른 것은 무엇인가요?","options":[{"t":"7","correct":true},{"t":"7, 8","mis":"M3-2-u4-X21"},{"t":"8, 9","mis":"M3-2-u4-X20"},{"t":"9","mis":"M3-2-u4-X20"}],"explanation":["□가 8이면 ⟨1 8/10⟩ = 1.8이에요.","1.8 > 1.△이려면 △는 8보다 작아야 해요.","△에는 7만 들어갈 수 있어요 — 8이면 두 수가 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L10_challenge#4','math',3,2,'u4','L10','tb_g3_2_math_u4_L10_challenge','lesson_challenge','M3-2-u4-C11',3,'sa','auto','⟨1 □/10⟩과 1.△의 크기를 비교했더니 ⟨1 □/10⟩이 더 컸어요. □에는 8 또는 9, △에는 7, 8, 9 중 하나가 들어가요. □가 9일 때 △에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M3-2-u4-C11","difficulty":3,"kind":"sa","stem":"⟨1 □/10⟩과 1.△의 크기를 비교했더니 ⟨1 □/10⟩이 더 컸어요. □에는 8 또는 9, △에는 7, 8, 9 중 하나가 들어가요. □가 9일 때 △에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["□가 9이면 ⟨1 9/10⟩ = 1.9예요.","1.9 > 1.△이려면 △는 9보다 작아야 해요 — 7, 8이에요.","모두 2개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L10_challenge#5','math',3,2,'u4','L10','tb_g3_2_math_u4_L10_challenge','lesson_challenge','M3-2-u4-C11',3,'error','auto','⟨3 1/10⟩과 3.6의 크기 비교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u4-X14','M3-2-u4-X20']::text[],false,'{"seq":5,"concept":"M3-2-u4-C11","difficulty":3,"kind":"error","stem":"⟨3 1/10⟩과 3.6의 크기 비교를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준우 — 「⟨3 1/10⟩은 분수라서 3.6보다 커」","correct":true,"mis_target":"M3-2-u4-X14"},{"t":"은비 — 「⟨3 1/10⟩ = 3.1이고 3.1 < 3.6이야」","mis":"M3-2-u4-X20"},{"t":"지유 — 「3.6 = ⟨3 6/10⟩이고 ⟨3 1/10⟩ < ⟨3 6/10⟩이야」","mis":"M3-2-u4-X20"}],"explanation":["분수를 소수로 바꾸면 ⟨3 1/10⟩ = 3.1이에요.","소수를 분수로 바꾸면 3.6 = ⟨3 6/10⟩이에요.","어느 쪽이든 ⟨3 1/10⟩ < 3.6 — 준우는 바꾸지 않고 꼴만 보고 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L10_challenge#6','math',3,2,'u4','L10','tb_g3_2_math_u4_L10_challenge','lesson_challenge','M3-2-u4-C11',3,'mc','auto','「익힘」 ⟨8 5/10⟩와 8.8의 크기를 바르게 비교한 것은 무엇인가요?',ARRAY['M3-2-u4-X17','M3-2-u4-X16','M3-2-u4-X22']::text[],false,'{"seq":6,"concept":"M3-2-u4-C11","difficulty":3,"kind":"mc","stem":"「익힘」 ⟨8 5/10⟩와 8.8의 크기를 바르게 비교한 것은 무엇인가요?","options":[{"t":"8.8 = ⟨8 8/10⟩이고 ⟨8 5/10⟩ < ⟨8 8/10⟩이에요","correct":true},{"t":"⟨8 5/10⟩ = 8.05이고 8.05 < 8.8이에요","mis":"M3-2-u4-X17"},{"t":"⟨8 5/10⟩ = 5.8이라서 8.8보다 작아요","mis":"M3-2-u4-X16"},{"t":"분수와 소수는 크기를 비교할 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["8.8을 분수로 나타내면 ⟨8 8/10⟩이에요.","자연수가 같으니 진분수를 비교하면 ⟨5/10⟩ < ⟨8/10⟩이에요.","⟨8 5/10⟩ = 8.5로 바꾸어 8.5 < 8.8로 비교해도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L10_challenge#7','math',3,2,'u4','L10','tb_g3_2_math_u4_L10_challenge','lesson_challenge','M3-2-u4-C11',3,'mc','auto','「익힘」 ⟨83/10⟩을 대분수로 나타내면 무엇인가요?',ARRAY['M3-2-u4-X03','M3-2-u4-X11','M3-2-u4-X12']::text[],false,'{"seq":7,"concept":"M3-2-u4-C11","difficulty":3,"kind":"mc","stem":"「익힘」 ⟨83/10⟩을 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨8 3/10⟩","correct":true},{"t":"⟨3 8/10⟩","mis":"M3-2-u4-X03"},{"t":"⟨7 13/10⟩","mis":"M3-2-u4-X11"},{"t":"⟨3/10⟩","mis":"M3-2-u4-X12"}],"explanation":["⟨83/10⟩은 ⟨80/10⟩과 ⟨3/10⟩이에요.","⟨80/10⟩ = 8이에요.","⟨83/10⟩ = ⟨8 3/10⟩ — 분수 부분은 진분수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L10_challenge#8','math',3,2,'u4','L10','tb_g3_2_math_u4_L10_challenge','lesson_challenge','M3-2-u4-C11',4,'mc','auto','「익힘」 두 수의 크기를 비교하여 더 큰 수를 오른쪽에 써요. ㉠은 ⟨83/10⟩과 ⟨8 5/10⟩ 중 더 큰 수, ㉡은 8.8과 7.9 중 더 큰 수, ㉢은 ㉠과 ㉡ 중 더 큰 수예요. ㉢에 들어갈 수는 무엇인가요?',ARRAY['M3-2-u4-X14','M3-2-u4-X18']::text[],false,'{"seq":8,"concept":"M3-2-u4-C11","difficulty":4,"kind":"mc","stem":"「익힘」 두 수의 크기를 비교하여 더 큰 수를 오른쪽에 써요. ㉠은 ⟨83/10⟩과 ⟨8 5/10⟩ 중 더 큰 수, ㉡은 8.8과 7.9 중 더 큰 수, ㉢은 ㉠과 ㉡ 중 더 큰 수예요. ㉢에 들어갈 수는 무엇인가요?","options":[{"t":"8.8","correct":true},{"t":"⟨8 5/10⟩","mis":"M3-2-u4-X14"},{"t":"⟨83/10⟩","mis":"M3-2-u4-X14"},{"t":"7.9","mis":"M3-2-u4-X18"}],"explanation":["㉠ — ⟨83/10⟩ = ⟨8 3/10⟩ < ⟨8 5/10⟩이므로 ⟨8 5/10⟩예요.","㉡ — 8.8 > 7.9이므로 8.8이에요.","㉢ — ⟨8 5/10⟩ = 8.5이고 8.5 < 8.8이므로 8.8이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L10_challenge#9','math',3,2,'u4','L10','tb_g3_2_math_u4_L10_challenge','lesson_challenge','M3-2-u4-C11',4,'essay','teacher','분수 마을과 소수 마을에 모인 ⟨2 5/10⟩, ⟨3 1/10⟩, 3.6, 2.8 중에서 가장 큰 수를 구하고, 그 방법을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u4-C11","difficulty":4,"kind":"essay","stem":"분수 마을과 소수 마을에 모인 ⟨2 5/10⟩, ⟨3 1/10⟩, 3.6, 2.8 중에서 가장 큰 수를 구하고, 그 방법을 설명해 보세요.","answer_guide":{"answer":"예: 가장 큰 수는 3.6이다. 분수끼리 비교하면 자연수 2 < 3이므로 ⟨3 1/10⟩이 크고, 소수끼리 비교하면 3 > 2이므로 3.6이 크다. ⟨3 1/10⟩을 소수로 나타내면 3.1이고 3.1 < 3.6이므로 가장 큰 수는 3.6이다.","scoring_points":["가장 큰 수를 3.6이라고 답했는가","분수끼리·소수끼리(또는 자연수끼리) 먼저 비교했는가","분수를 소수로(또는 소수를 분수로) 바꾸어 비교했는가"]},"explanation":["⟨3 1/10⟩ > ⟨2 5/10⟩예요.","3.6 > 2.8이에요.","3.1 < 3.6 — 3.6이 가장 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_L10_challenge#10','math',3,2,'u4','L10','tb_g3_2_math_u4_L10_challenge','lesson_challenge','M3-2-u4-C11',4,'essay','teacher','⟨1 □/10⟩ > ⟨1 7/10⟩, 1.△ > 1.6이고, ⟨1 □/10⟩이 1.△보다 커요. □와 △에 들어갈 수 있는 수를 모두 구하고, 그 방법을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u4-C11","difficulty":4,"kind":"essay","stem":"⟨1 □/10⟩ > ⟨1 7/10⟩, 1.△ > 1.6이고, ⟨1 □/10⟩이 1.△보다 커요. □와 △에 들어갈 수 있는 수를 모두 구하고, 그 방법을 설명해 보세요.","answer_guide":{"answer":"예: □는 7보다 커야 하므로 8 또는 9이고, △는 6보다 커야 하므로 7, 8, 9 중 하나이다. ⟨1 □/10⟩ = 1.□이므로 1.□ > 1.△이 되려면 □가 △보다 커야 한다. □가 8일 때 △는 7이고, □가 9일 때 △는 7 또는 8이다.","scoring_points":["□에 8, 9가 들어간다고 썼는가","△에 7, 8, 9가 들어갈 수 있다고 썼는가","□가 8일 때 △는 7, □가 9일 때 △는 7 또는 8이라고 답했는가"]},"explanation":["□는 8 또는 9예요.","△는 7, 8, 9 중 하나예요.","□ = 8이면 △ = 7, □ = 9이면 △ = 7 또는 8이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_a#1','math',3,2,'u4','','tb_g3_2_math_u4_review_a','unit_review','M3-2-u4-C1',1,'mc','auto','「스스로 마무리하기」 빈칸을 채워요. 동그라미 10개를 5개씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?',ARRAY['M3-2-u4-X02','M3-2-u4-X23']::text[],false,'{"seq":1,"concept":"M3-2-u4-C1","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 빈칸을 채워요. 동그라미 10개를 5개씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?","options":[{"t":"⟨1/2⟩","correct":true},{"t":"⟨5/2⟩","mis":"M3-2-u4-X02"},{"t":"⟨1/10⟩","mis":"M3-2-u4-X02"},{"t":"⟨1/5⟩","mis":"M3-2-u4-X23"}],"explanation":["10을 5씩 묶으면 2묶음 — 전체 묶음의 수 2가 분모예요.","부분은 그중 1묶음 — 부분 묶음의 수 1이 분자예요.","5는 10의 ⟨1/2⟩ — 낱개의 수가 아니라 묶음의 수로 나타내요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]],"hi":true},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]},{"p":[[4.7,0],[5.7,0],[5.7,1],[4.7,1]]},{"p":[[5.7,0],[6.7,0],[6.7,1],[5.7,1]]},{"p":[[3.7,1],[4.7,1],[4.7,2],[3.7,2]]},{"p":[[4.7,1],[5.7,1],[5.7,2],[4.7,2]]}],"u":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_a#2','math',3,2,'u4','','tb_g3_2_math_u4_review_a','unit_review','M3-2-u4-C2',1,'mc','auto','「스스로 마무리하기」 자동차 8대를 2대씩 묶었어요. 빨간색 자동차 1묶음은 전체 자동차의 얼마인지 분수로 나타내면 무엇인가요?',ARRAY['M3-2-u4-X01','M3-2-u4-X02']::text[],false,'{"seq":2,"concept":"M3-2-u4-C2","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 자동차 8대를 2대씩 묶었어요. 빨간색 자동차 1묶음은 전체 자동차의 얼마인지 분수로 나타내면 무엇인가요?","options":[{"t":"⟨1/4⟩","correct":true},{"t":"⟨1/3⟩","mis":"M3-2-u4-X01"},{"t":"⟨2/4⟩","mis":"M3-2-u4-X02"},{"t":"⟨1/8⟩","mis":"M3-2-u4-X02"}],"explanation":["8을 2씩 묶으면 4묶음 — 전체 묶음의 수 4가 분모예요.","부분은 그중 1묶음 — 부분 묶음의 수 1이 분자예요.","빨간색 자동차는 전체의 ⟨1/4⟩ — 묶음 안의 자동차 수가 모두 같은지 확인해요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]]},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]]},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]]},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]]},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]]}],"u":29}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_a#3','math',3,2,'u4','','tb_g3_2_math_u4_review_a','unit_review','M3-2-u4-C3',1,'sa','auto','「스스로 마무리하기」 빈칸을 채워요. 10의 ⟨4/5⟩는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u4-C3","difficulty":1,"kind":"sa","stem":"「스스로 마무리하기」 빈칸을 채워요. 10의 ⟨4/5⟩는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["10을 똑같이 5묶음으로 나누면 한 묶음이 2예요 — 10 ÷ 5 = 2.","⟨4/5⟩는 ⟨1/5⟩이 4개 — 4묶음이에요.","10의 ⟨4/5⟩만큼은 8이에요. 분자 4만 보고 답하지 않아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]],"hi":true},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]],"hi":true},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]],"hi":true},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]],"hi":true},{"p":[[10.8,0],[11.8,0],[11.8,1],[10.8,1]]},{"p":[[11.8,0],[12.8,0],[12.8,1],[11.8,1]]}],"u":23}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_a#4','math',3,2,'u4','','tb_g3_2_math_u4_review_a','unit_review','M3-2-u4-C4',1,'sa','auto','「스스로 마무리하기」 8 km의 ⟨2/4⟩만큼은 몇 km인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M3-2-u4-C4","difficulty":1,"kind":"sa","stem":"「스스로 마무리하기」 8 km의 ⟨2/4⟩만큼은 몇 km인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["8 km를 똑같이 4부분으로 나누면 한 부분이 2 km예요 — 8 ÷ 4 = 2.","⟨2/4⟩는 ⟨1/4⟩이 2개 — 2부분이에요.","8 km의 ⟨2/4⟩만큼은 4 km예요. 분자 2만 보고 답하지 않아요."],"asset":{"type":"fbar","bars":[{"den":4,"num":2,"label":"8 km"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_a#5','math',3,2,'u4','','tb_g3_2_math_u4_review_a','unit_review','M3-2-u4-C5',1,'mc','auto','「스스로 마무리하기」 빈칸을 채워요. 수직선에 분모가 2인 분수 ⟨1/2⟩, ⟨2/2⟩, ⟨3/2⟩, ⟨4/2⟩를 나타냈어요. 이 중에서 진분수는 무엇인가요?',ARRAY['M3-2-u4-X08','M3-2-u4-X24']::text[],false,'{"seq":5,"concept":"M3-2-u4-C5","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 빈칸을 채워요. 수직선에 분모가 2인 분수 ⟨1/2⟩, ⟨2/2⟩, ⟨3/2⟩, ⟨4/2⟩를 나타냈어요. 이 중에서 진분수는 무엇인가요?","options":[{"t":"⟨1/2⟩","correct":true},{"t":"⟨2/2⟩","mis":"M3-2-u4-X08"},{"t":"⟨3/2⟩","mis":"M3-2-u4-X08"},{"t":"⟨4/2⟩","mis":"M3-2-u4-X24"}],"explanation":["진분수는 분자가 분모보다 작은 분수예요.","⟨2/2⟩, ⟨3/2⟩, ⟨4/2⟩는 가분수예요 — ⟨2/2⟩ = 1, ⟨4/2⟩ = 2인 자연수와 크기가 같아요.","⟨3/2⟩ = ⟨1 1/2⟩은 대분수로도 나타내요 — 진분수는 ⟨1/2⟩뿐이에요."],"asset":{"type":"number_line","cells":["0","⟨1/2⟩","⟨2/2⟩","⟨3/2⟩","⟨4/2⟩"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_a#6','math',3,2,'u4','','tb_g3_2_math_u4_review_a','unit_review','M3-2-u4-C8',1,'mc','auto','「스스로 마무리하기」 두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨11/5⟩ ○ ⟨9/5⟩',ARRAY['M3-2-u4-X13','M3-2-u4-X22']::text[],false,'{"seq":6,"concept":"M3-2-u4-C8","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨11/5⟩ ○ ⟨9/5⟩","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u4-X13"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["분모가 같은 가분수는 분자의 크기를 비교해요.","⟨11/5⟩은 ⟨1/5⟩이 11개, ⟨9/5⟩는 9개예요.","그래서 ⟨11/5⟩ > ⟨9/5⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_a#7','math',3,2,'u4','','tb_g3_2_math_u4_review_a','unit_review','M3-2-u4-C9',1,'mc','auto','「스스로 마무리하기」 수직선에 나타낸 부분을 대분수와 소수로 바르게 나타낸 것은 무엇인가요?',ARRAY['M3-2-u4-X16','M3-2-u4-X17','M3-2-u4-X15']::text[],false,'{"seq":7,"concept":"M3-2-u4-C9","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 수직선에 나타낸 부분을 대분수와 소수로 바르게 나타낸 것은 무엇인가요?","options":[{"t":"⟨2 3/10⟩, 2.3","correct":true},{"t":"⟨3 2/10⟩, 3.2","mis":"M3-2-u4-X16"},{"t":"⟨2 3/10⟩, 2.03","mis":"M3-2-u4-X17"},{"t":"⟨3/10⟩, 0.3","mis":"M3-2-u4-X15"}],"explanation":["수직선에 나타낸 부분은 자연수 2와 진분수 ⟨3/10⟩만큼이에요.","⟨2 3/10⟩ — 「이와 십분의 삼」이라고 읽어요.","⟨2 3/10⟩ = 2.3 — 「이 점 삼」이라고 읽어요."],"asset":{"type":"fbar","bars":[{"den":10,"num":10},{"den":10,"num":10},{"den":10,"num":3}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_a#8','math',3,2,'u4','','tb_g3_2_math_u4_review_a','unit_review','M3-2-u4-C10',1,'mc','auto','「스스로 마무리하기」 두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  4.1 ○ 3.3',ARRAY['M3-2-u4-X18','M3-2-u4-X22']::text[],false,'{"seq":8,"concept":"M3-2-u4-C10","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  4.1 ○ 3.3","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u4-X18"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["4.1은 0.1이 41개, 3.3은 0.1이 33개예요.","자연수의 크기를 먼저 비교하고, 같으면 소수점 오른쪽 수의 크기를 비교해요.","그래서 4.1 > 3.3."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_a#9','math',3,2,'u4','','tb_g3_2_math_u4_review_a','unit_review','M3-2-u4-C3',2,'mc','auto','「스스로 마무리하기」 도윤이는 연필 24자루의 ⟨5/6⟩만큼을 동생에게 주었어요. 도윤이가 동생에게 준 연필은 몇 자루인가요?',ARRAY['M3-2-u4-X04','M3-2-u4-X05']::text[],false,'{"seq":9,"concept":"M3-2-u4-C3","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 도윤이는 연필 24자루의 ⟨5/6⟩만큼을 동생에게 주었어요. 도윤이가 동생에게 준 연필은 몇 자루인가요?","options":[{"t":"20자루","correct":true},{"t":"5자루","mis":"M3-2-u4-X04"},{"t":"4자루","mis":"M3-2-u4-X05"}],"explanation":["24자루를 똑같이 6묶음으로 나누면 한 묶음이 4자루예요 — 24 ÷ 6 = 4.","⟨5/6⟩는 ⟨1/6⟩이 5개 — 5묶음이에요.","24자루의 ⟨5/6⟩만큼은 20자루예요. 분자 5만 보고 답하지 않아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]],"hi":true},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[2.7,1],[3.7,1],[3.7,2],[2.7,2]],"hi":true},{"p":[[3.7,1],[4.7,1],[4.7,2],[3.7,2]],"hi":true},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]],"hi":true},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]],"hi":true},{"p":[[5.4,1],[6.4,1],[6.4,2],[5.4,2]],"hi":true},{"p":[[6.4,1],[7.4,1],[7.4,2],[6.4,2]],"hi":true},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]],"hi":true},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]],"hi":true},{"p":[[8.1,1],[9.1,1],[9.1,2],[8.1,2]],"hi":true},{"p":[[9.1,1],[10.1,1],[10.1,2],[9.1,2]],"hi":true},{"p":[[10.8,0],[11.8,0],[11.8,1],[10.8,1]],"hi":true},{"p":[[11.8,0],[12.8,0],[12.8,1],[11.8,1]],"hi":true},{"p":[[10.8,1],[11.8,1],[11.8,2],[10.8,2]],"hi":true},{"p":[[11.8,1],[12.8,1],[12.8,2],[11.8,2]],"hi":true},{"p":[[13.5,0],[14.5,0],[14.5,1],[13.5,1]]},{"p":[[14.5,0],[15.5,0],[15.5,1],[14.5,1]]},{"p":[[13.5,1],[14.5,1],[14.5,2],[13.5,2]]},{"p":[[14.5,1],[15.5,1],[15.5,2],[14.5,2]]}],"u":19}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_a#10','math',3,2,'u4','','tb_g3_2_math_u4_review_a','unit_review','M3-2-u4-C10',2,'mc','auto','「스스로 마무리하기」 병뚜껑 멀리 보내기 놀이에서 하윤이는 2.5 m, 은서는 1.8 m, 동연이는 2.3 m 멀리 보냈어요. 병뚜껑을 가장 멀리 보낸 사람은 누구인가요?',ARRAY['M3-2-u4-X18','M3-2-u4-X20','M3-2-u4-X22']::text[],false,'{"seq":10,"concept":"M3-2-u4-C10","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 병뚜껑 멀리 보내기 놀이에서 하윤이는 2.5 m, 은서는 1.8 m, 동연이는 2.3 m 멀리 보냈어요. 병뚜껑을 가장 멀리 보낸 사람은 누구인가요?","options":[{"t":"하윤","correct":true},{"t":"은서","mis":"M3-2-u4-X18"},{"t":"동연","mis":"M3-2-u4-X20"},{"t":"세 사람이 같아요","mis":"M3-2-u4-X22"}],"explanation":["자연수의 크기를 먼저 비교하면 1.8이 가장 작아요.","2.5와 2.3은 자연수가 같고 5 > 3이에요.","2.5가 가장 커요 — 병뚜껑을 가장 멀리 보낸 사람은 하윤이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_a#11','math',3,2,'u4','','tb_g3_2_math_u4_review_a','unit_review','M3-2-u4-C5',2,'mc','auto','「스스로 마무리하기」 주사위를 두 번 던져 처음 나온 수를 분모로, 나중 나온 수를 분자로 하여 분수를 만들어요. 처음에 4가 나왔을 때 만들 수 있는 진분수와 가분수를 바르게 나눈 것은 무엇인가요?',ARRAY['M3-2-u4-X08','M3-2-u4-X24','M3-2-u4-X20']::text[],false,'{"seq":11,"concept":"M3-2-u4-C5","difficulty":2,"kind":"mc","stem":"「스스로 마무리하기」 주사위를 두 번 던져 처음 나온 수를 분모로, 나중 나온 수를 분자로 하여 분수를 만들어요. 처음에 4가 나왔을 때 만들 수 있는 진분수와 가분수를 바르게 나눈 것은 무엇인가요?","options":[{"t":"진분수 ⟨1/4⟩, ⟨2/4⟩, ⟨3/4⟩ · 가분수 ⟨4/4⟩, ⟨5/4⟩, ⟨6/4⟩","correct":true},{"t":"진분수 ⟨1/4⟩, ⟨2/4⟩, ⟨3/4⟩, ⟨4/4⟩ · 가분수 ⟨5/4⟩, ⟨6/4⟩","mis":"M3-2-u4-X08"},{"t":"진분수 ⟨1/4⟩, ⟨2/4⟩, ⟨3/4⟩ · 가분수 ⟨5/4⟩, ⟨6/4⟩","mis":"M3-2-u4-X24"},{"t":"진분수 ⟨4/4⟩, ⟨5/4⟩, ⟨6/4⟩ · 가분수 ⟨1/4⟩, ⟨2/4⟩, ⟨3/4⟩","mis":"M3-2-u4-X20"}],"explanation":["주사위에서 나올 수 있는 수는 1부터 6까지예요.","분자가 분모 4보다 작으면 진분수 — ⟨1/4⟩, ⟨2/4⟩, ⟨3/4⟩이에요.","분자가 4와 같거나 크면 가분수 — ⟨4/4⟩, ⟨5/4⟩, ⟨6/4⟩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_a#12','math',3,2,'u4','','tb_g3_2_math_u4_review_a','unit_review','M3-2-u4-C7',2,'mc','auto','「이 단원 학습을 마치고」 색 테이프가 1 m와 ⟨1/2⟩ m만큼 있어요. 이 길이를 대분수와 가분수로 바르게 나타낸 것은 무엇인가요?',ARRAY['M3-2-u4-X10','M3-2-u4-X12','M3-2-u4-X21']::text[],false,'{"seq":12,"concept":"M3-2-u4-C7","difficulty":2,"kind":"mc","stem":"「이 단원 학습을 마치고」 색 테이프가 1 m와 ⟨1/2⟩ m만큼 있어요. 이 길이를 대분수와 가분수로 바르게 나타낸 것은 무엇인가요?","options":[{"t":"⟨1 1/2⟩ m, ⟨3/2⟩ m","correct":true},{"t":"⟨1 1/2⟩ m, ⟨2/2⟩ m","mis":"M3-2-u4-X10"},{"t":"⟨1/2⟩ m, ⟨3/2⟩ m","mis":"M3-2-u4-X12"},{"t":"⟨2 1/2⟩ m, ⟨5/2⟩ m","mis":"M3-2-u4-X21"}],"explanation":["1 m와 ⟨1/2⟩ m는 자연수와 진분수 — 대분수 ⟨1 1/2⟩ m예요.","1은 ⟨1/2⟩이 2개 — ⟨1/2⟩이 모두 3개예요.","⟨1 1/2⟩ = ⟨3/2⟩ — 가분수 ⟨3/2⟩ m로도 나타낼 수 있어요."],"asset":{"type":"fbar","bars":[{"den":2,"num":2},{"den":2,"num":1}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_a#13','math',3,2,'u4','','tb_g3_2_math_u4_review_a','unit_review','M3-2-u4-C9',2,'mc','auto','「이 단원 학습을 마치고」 미술 작품을 붙일 간격 3 cm 5 mm는 몇 cm인지 소수로 나타내면 무엇인가요?',ARRAY['M3-2-u4-X17','M3-2-u4-X16']::text[],false,'{"seq":13,"concept":"M3-2-u4-C9","difficulty":2,"kind":"mc","stem":"「이 단원 학습을 마치고」 미술 작품을 붙일 간격 3 cm 5 mm는 몇 cm인지 소수로 나타내면 무엇인가요?","options":[{"t":"3.5 cm","correct":true},{"t":"3.05 cm","mis":"M3-2-u4-X17"},{"t":"5.3 cm","mis":"M3-2-u4-X16"},{"t":"35 cm","mis":"M3-2-u4-X17"}],"explanation":["5 mm는 1 cm를 똑같이 10으로 나눈 것 중의 5 — ⟨5/10⟩ cm = 0.5 cm예요.","3 cm 5 mm = ⟨3 5/10⟩ cm예요.","3 cm 5 mm = 3.5 cm — 「삼 점 오」라고 읽어요."],"asset":{"type":"mmruler","len":35,"label":"간격"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_a#14','math',3,2,'u4','','tb_g3_2_math_u4_review_a','unit_review','M3-2-u4-C7',2,'mc','auto','「익힘」 ⟨1 5/6⟩를 바르게 읽은 것은 무엇인가요?',ARRAY['M3-2-u4-X03','M3-2-u4-X16','M3-2-u4-X12']::text[],false,'{"seq":14,"concept":"M3-2-u4-C7","difficulty":2,"kind":"mc","stem":"「익힘」 ⟨1 5/6⟩를 바르게 읽은 것은 무엇인가요?","options":[{"t":"일과 육분의 오","correct":true},{"t":"일과 오분의 육","mis":"M3-2-u4-X03"},{"t":"일 점 오육","mis":"M3-2-u4-X16"},{"t":"육분의 오","mis":"M3-2-u4-X12"}],"explanation":["대분수는 자연수 부분을 먼저 읽고 「과(와)」를 붙여요.","분수 부분은 분모부터 「○분의 △」로 읽어요.","⟨1 5/6⟩는 「일과 육분의 오」라고 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_a#15','math',3,2,'u4','','tb_g3_2_math_u4_review_a','unit_review','M3-2-u4-C4',2,'sa','auto','「익힘」 은비는 12시간의 ⟨2/3⟩만큼 놀이공원에서 놀았어요. 은비는 놀이공원에서 몇 시간 놀았나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"M3-2-u4-C4","difficulty":2,"kind":"sa","stem":"「익힘」 은비는 12시간의 ⟨2/3⟩만큼 놀이공원에서 놀았어요. 은비는 놀이공원에서 몇 시간 놀았나요? 숫자로 쓰세요.","answer":["8"],"explanation":["12시간을 똑같이 3부분으로 나누면 한 부분이 4시간이에요 — 12 ÷ 3 = 4.","⟨2/3⟩는 ⟨1/3⟩이 2개 — 2부분이에요.","12시간의 ⟨2/3⟩만큼은 8시간이에요. 분자 2만 보고 답하지 않아요."],"asset":{"type":"fbar","bars":[{"den":3,"num":2,"label":"12시간"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_a#16','math',3,2,'u4','','tb_g3_2_math_u4_review_a','unit_review','M3-2-u4-C11',2,'mc','auto','두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨3 1/10⟩ ○ 3.6',ARRAY['M3-2-u4-X14','M3-2-u4-X22']::text[],false,'{"seq":16,"concept":"M3-2-u4-C11","difficulty":2,"kind":"mc","stem":"두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨3 1/10⟩ ○ 3.6","options":[{"t":"<","correct":true},{"t":">","mis":"M3-2-u4-X14"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["분모가 10인 분수는 소수로 나타내어 비교할 수 있어요.","⟨3 1/10⟩ = 3.1이에요.","자연수부터 비교하면 ⟨3 1/10⟩ < 3.6."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_a#17','math',3,2,'u4','','tb_g3_2_math_u4_review_a','unit_review','M3-2-u4-C8',3,'mc','auto','「스스로 마무리하기」 건우가 키우는 사슴벌레 수컷의 몸길이는 ⟨5 3/10⟩ cm이고, 암컷의 몸길이는 ⟨44/10⟩ cm예요. 몸길이가 더 긴 것은 어느 것인가요?',ARRAY['M3-2-u4-X14','M3-2-u4-X22']::text[],false,'{"seq":17,"concept":"M3-2-u4-C8","difficulty":3,"kind":"mc","stem":"「스스로 마무리하기」 건우가 키우는 사슴벌레 수컷의 몸길이는 ⟨5 3/10⟩ cm이고, 암컷의 몸길이는 ⟨44/10⟩ cm예요. 몸길이가 더 긴 것은 어느 것인가요?","options":[{"t":"수컷","correct":true},{"t":"암컷","mis":"M3-2-u4-X14"},{"t":"두 몸길이가 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["⟨44/10⟩를 대분수로 나타내면 ⟨4 4/10⟩예요.","⟨5 3/10⟩과 ⟨4 4/10⟩의 자연수를 비교하면 5 > 4예요.","⟨5 3/10⟩ > ⟨44/10⟩ — 수컷이 더 길어요. ⟨5 3/10⟩ = ⟨53/10⟩으로 바꾸어 견주어도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_a#18','math',3,2,'u4','','tb_g3_2_math_u4_review_a','unit_review','M3-2-u4-C2',3,'mc','auto','8개를 똑같이 2묶음으로 나누는 바른 방법은 무엇인가요?',ARRAY['M3-2-u4-X23','M3-2-u4-X26','M3-2-u4-X21']::text[],false,'{"seq":18,"concept":"M3-2-u4-C2","difficulty":3,"kind":"mc","stem":"8개를 똑같이 2묶음으로 나누는 바른 방법은 무엇인가요?","options":[{"t":"한 묶음에 4개씩 2묶음으로 나눈다","correct":true},{"t":"한 묶음에 2개씩 4묶음으로 나눈다","mis":"M3-2-u4-X23"},{"t":"8개를 하나씩 똑같이 반으로 자른다","mis":"M3-2-u4-X26"},{"t":"한 묶음에 2개씩 2묶음만 만든다","mis":"M3-2-u4-X21"}],"explanation":["「똑같이 2묶음」은 묶음의 수가 2개라는 뜻이에요.","8개를 2묶음에 똑같이 나누면 한 묶음에 4개예요.","2개씩 묶으면 4묶음이 되어 「2묶음으로 나누기」가 아니에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]]},{"p":[[1,0],[2,0],[2,1],[1,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[1,1],[2,1],[2,2],[1,2]]},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]]},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]},{"p":[[2.7,1],[3.7,1],[3.7,2],[2.7,2]]},{"p":[[3.7,1],[4.7,1],[4.7,2],[3.7,2]]}],"u":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_a#19','math',3,2,'u4','','tb_g3_2_math_u4_review_a','unit_review','M3-2-u4-C3',3,'ox','auto','도윤이는 「12의 ⟨1/3⟩은 3이고, 12의 ⟨2/3⟩는 6이야.」라고 했어요. 도윤이의 말이 옳은가요?',ARRAY['M3-2-u4-X23']::text[],false,'{"seq":19,"concept":"M3-2-u4-C3","difficulty":3,"kind":"ox","stem":"도윤이는 「12의 ⟨1/3⟩은 3이고, 12의 ⟨2/3⟩는 6이야.」라고 했어요. 도윤이의 말이 옳은가요?","answer":"X","reason_options":[{"t":"12를 똑같이 3묶음으로 나누면 한 묶음이 4라서","correct":true},{"t":"분모 3만큼씩 묶으면 되니까","mis":"M3-2-u4-X23"}],"mis":"M3-2-u4-X23","explanation":["12의 ⟨1/3⟩은 12를 똑같이 3묶음으로 나눈 것 중의 1묶음 — 4예요.","12의 ⟨2/3⟩는 4가 2묶음 — 8이에요.","도윤이는 분모를 한 묶음의 개수로 보았어요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]],"hi":true},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]]},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]},{"p":[[2.7,1],[3.7,1],[3.7,2],[2.7,2]]},{"p":[[3.7,1],[4.7,1],[4.7,2],[3.7,2]]},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]]},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]]},{"p":[[5.4,1],[6.4,1],[6.4,2],[5.4,2]]},{"p":[[6.4,1],[7.4,1],[7.4,2],[6.4,2]]}],"u":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_a#20','math',3,2,'u4','','tb_g3_2_math_u4_review_a','unit_review','M3-2-u4-C5',3,'ox','auto','건우는 「⟨4/4⟩는 1과 같으니까 가분수가 아니라 자연수야.」라고 했어요. 건우의 말이 옳은가요?',ARRAY['M3-2-u4-X24']::text[],false,'{"seq":20,"concept":"M3-2-u4-C5","difficulty":3,"kind":"ox","stem":"건우는 「⟨4/4⟩는 1과 같으니까 가분수가 아니라 자연수야.」라고 했어요. 건우의 말이 옳은가요?","answer":"X","reason_options":[{"t":"분자가 분모와 같은 분수는 가분수라서","correct":true},{"t":"1과 크기가 같으니까","mis":"M3-2-u4-X24"}],"mis":"M3-2-u4-X24","explanation":["⟨4/4⟩는 분자와 분모가 같은 분수예요.","분자가 분모와 같거나 크면 가분수예요.","⟨4/4⟩ = 1처럼 크기가 같아도 꼴은 가분수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_a#21','math',3,2,'u4','','tb_g3_2_math_u4_review_a','unit_review','M3-2-u4-C9',3,'sa','auto','2.9는 0.1이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M3-2-u4-C9","difficulty":3,"kind":"sa","stem":"2.9는 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["29"],"explanation":["2는 0.1이 20개예요 — 1은 0.1이 10개예요.","0.9는 0.1이 9개예요.","2.9는 0.1이 20 + 9 = 29개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_a#22','math',3,2,'u4','','tb_g3_2_math_u4_review_a','unit_review','M3-2-u4-C11',3,'sa','auto','자연수 1부터 9까지의 수 중에서 ⟨1 □/10⟩ > ⟨1 7/10⟩이 되도록 □에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":22,"concept":"M3-2-u4-C11","difficulty":3,"kind":"sa","stem":"자연수 1부터 9까지의 수 중에서 ⟨1 □/10⟩ > ⟨1 7/10⟩이 되도록 □에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["두 분수는 자연수가 1로 같아요.","진분수를 비교하면 □ > 7이어야 해요.","□에는 8, 9 — 모두 2개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_a#23','math',3,2,'u4','','tb_g3_2_math_u4_review_a','unit_review','M3-2-u4-C8',4,'essay','teacher','「스스로 마무리하기」 「서술형」 건우가 키우는 사슴벌레 수컷의 몸길이는 ⟨5 3/10⟩ cm이고, 암컷의 몸길이는 ⟨44/10⟩ cm예요. 몸길이가 더 긴 것은 어느 것인지 풀이 과정을 쓰고 답을 구해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M3-2-u4-C8","difficulty":4,"kind":"essay","stem":"「스스로 마무리하기」 「서술형」 건우가 키우는 사슴벌레 수컷의 몸길이는 ⟨5 3/10⟩ cm이고, 암컷의 몸길이는 ⟨44/10⟩ cm예요. 몸길이가 더 긴 것은 어느 것인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: ⟨44/10⟩를 대분수로 나타내면 ⟨4 4/10⟩이다. ⟨5 3/10⟩과 ⟨4 4/10⟩의 자연수의 크기를 비교하면 5 > 4이므로 ⟨5 3/10⟩ > ⟨4 4/10⟩이다. 따라서 몸길이가 더 긴 것은 수컷이다.","scoring_points":["⟨44/10⟩를 대분수로(또는 ⟨5 3/10⟩을 가분수로) 바꾸었는가","자연수(또는 분자)의 크기를 비교했는가","수컷이라고 답했는가"]},"explanation":["⟨44/10⟩ = ⟨4 4/10⟩예요.","5 > 4예요.","수컷이 더 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_a#24','math',3,2,'u4','','tb_g3_2_math_u4_review_a','unit_review','M3-2-u4-C3',4,'essay','teacher','「스스로 마무리하기」 도윤이는 연필 24자루의 ⟨5/6⟩만큼을 동생에게 주었어요. 동생에게 준 연필은 몇 자루인지 구하고, 그 방법을 묶음으로 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M3-2-u4-C3","difficulty":4,"kind":"essay","stem":"「스스로 마무리하기」 도윤이는 연필 24자루의 ⟨5/6⟩만큼을 동생에게 주었어요. 동생에게 준 연필은 몇 자루인지 구하고, 그 방법을 묶음으로 설명해 보세요.","answer_guide":{"answer":"예: 24자루를 분모 6만큼 똑같이 6묶음으로 나누면 한 묶음에 4자루이다. ⟨5/6⟩는 6묶음 중 5묶음이므로 4 × 5 = 20자루이다.","scoring_points":["6묶음으로 나누어 한 묶음 4자루를 구했는가","5묶음을 모았는가","20자루라고 답했는가"]},"explanation":["24 ÷ 6 = 4예요.","4 × 5 = 20이에요.","20자루예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]],"hi":true},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[2.7,1],[3.7,1],[3.7,2],[2.7,2]],"hi":true},{"p":[[3.7,1],[4.7,1],[4.7,2],[3.7,2]],"hi":true},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]],"hi":true},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]],"hi":true},{"p":[[5.4,1],[6.4,1],[6.4,2],[5.4,2]],"hi":true},{"p":[[6.4,1],[7.4,1],[7.4,2],[6.4,2]],"hi":true},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]],"hi":true},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]],"hi":true},{"p":[[8.1,1],[9.1,1],[9.1,2],[8.1,2]],"hi":true},{"p":[[9.1,1],[10.1,1],[10.1,2],[9.1,2]],"hi":true},{"p":[[10.8,0],[11.8,0],[11.8,1],[10.8,1]],"hi":true},{"p":[[11.8,0],[12.8,0],[12.8,1],[11.8,1]],"hi":true},{"p":[[10.8,1],[11.8,1],[11.8,2],[10.8,2]],"hi":true},{"p":[[11.8,1],[12.8,1],[12.8,2],[11.8,2]],"hi":true},{"p":[[13.5,0],[14.5,0],[14.5,1],[13.5,1]]},{"p":[[14.5,0],[15.5,0],[15.5,1],[14.5,1]]},{"p":[[13.5,1],[14.5,1],[14.5,2],[13.5,2]]},{"p":[[14.5,1],[15.5,1],[15.5,2],[14.5,2]]}],"u":19}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_a#25','math',3,2,'u4','','tb_g3_2_math_u4_review_a','unit_review','M3-2-u4-C11',4,'essay','teacher','분수 마을과 소수 마을에 모인 ⟨2 5/10⟩, ⟨3 1/10⟩, 3.6, 2.8 중에서 가장 큰 수를 구하고, 그 방법을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u4-C11","difficulty":4,"kind":"essay","stem":"분수 마을과 소수 마을에 모인 ⟨2 5/10⟩, ⟨3 1/10⟩, 3.6, 2.8 중에서 가장 큰 수를 구하고, 그 방법을 설명해 보세요.","answer_guide":{"answer":"예: 가장 큰 수는 3.6이다. 분수끼리 비교하면 ⟨3 1/10⟩이 크고 소수끼리 비교하면 3.6이 크다. ⟨3 1/10⟩을 소수로 나타내면 3.1이고 3.1 < 3.6이므로 가장 큰 수는 3.6이다.","scoring_points":["가장 큰 수를 3.6이라고 답했는가","분수끼리·소수끼리 먼저 비교했는가","분수를 소수로(또는 소수를 분수로) 바꾸어 비교했는가"]},"explanation":["⟨3 1/10⟩ > ⟨2 5/10⟩예요.","3.6 > 2.8이에요.","3.6이 가장 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_b#1','math',3,2,'u4','','tb_g3_2_math_u4_review_b','unit_review','M3-2-u4-C1',1,'mc','auto','「확인 문제」 하트 14개를 2개씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?',ARRAY['M3-2-u4-X01','M3-2-u4-X03','M3-2-u4-X02']::text[],false,'{"seq":1,"concept":"M3-2-u4-C1","difficulty":1,"kind":"mc","stem":"「확인 문제」 하트 14개를 2개씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?","options":[{"t":"⟨3/7⟩","correct":true},{"t":"⟨3/4⟩","mis":"M3-2-u4-X01"},{"t":"⟨7/3⟩","mis":"M3-2-u4-X03"},{"t":"⟨6/7⟩","mis":"M3-2-u4-X02"}],"explanation":["14를 2씩 묶으면 7묶음 — 전체 묶음의 수 7이 분모예요.","부분은 그중 3묶음 — 부분 묶음의 수 3이 분자예요.","6은 14의 ⟨3/7⟩ — 낱개의 수가 아니라 묶음의 수로 나타내요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]],"hi":true},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]],"hi":true},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]]},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]]},{"p":[[10.8,0],[11.8,0],[11.8,1],[10.8,1]]},{"p":[[11.8,0],[12.8,0],[12.8,1],[11.8,1]]},{"p":[[13.5,0],[14.5,0],[14.5,1],[13.5,1]]},{"p":[[14.5,0],[15.5,0],[15.5,1],[14.5,1]]},{"p":[[16.2,0],[17.2,0],[17.2,1],[16.2,1]]},{"p":[[17.2,0],[18.2,0],[18.2,1],[17.2,1]]}],"u":16}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_b#2','math',3,2,'u4','','tb_g3_2_math_u4_review_b','unit_review','M3-2-u4-C2',1,'mc','auto','검은 바둑돌 3개와 흰 바둑돌 4개가 있어요. 검은 바둑돌은 전체 바둑돌의 얼마인가요?',ARRAY['M3-2-u4-X01','M3-2-u4-X03','M3-2-u4-X20']::text[],false,'{"seq":2,"concept":"M3-2-u4-C2","difficulty":1,"kind":"mc","stem":"검은 바둑돌 3개와 흰 바둑돌 4개가 있어요. 검은 바둑돌은 전체 바둑돌의 얼마인가요?","options":[{"t":"⟨3/7⟩","correct":true},{"t":"⟨3/4⟩","mis":"M3-2-u4-X01"},{"t":"⟨7/3⟩","mis":"M3-2-u4-X03"},{"t":"⟨4/7⟩","mis":"M3-2-u4-X20"}],"explanation":["바둑돌은 모두 3 + 4 = 7개 — 이것이 전체예요.","검은 바둑돌 3개를 전체 7개와 견주어요.","검은 바둑돌은 전체의 ⟨3/7⟩이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[4,0],[5,0],[5,1],[4,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[1,1],[2,1],[2,2],[1,2]]}],"u":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_b#3','math',3,2,'u4','','tb_g3_2_math_u4_review_b','unit_review','M3-2-u4-C3',1,'sa','auto','10의 ⟨3/5⟩은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u4-C3","difficulty":1,"kind":"sa","stem":"10의 ⟨3/5⟩은 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["10을 똑같이 5묶음으로 나누면 한 묶음이 2예요 — 10 ÷ 5 = 2.","⟨3/5⟩은 ⟨1/5⟩이 3개 — 3묶음이에요.","10의 ⟨3/5⟩만큼은 6이에요. 분자 3만 보고 답하지 않아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]],"hi":true},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]],"hi":true},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]]},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]]},{"p":[[10.8,0],[11.8,0],[11.8,1],[10.8,1]]},{"p":[[11.8,0],[12.8,0],[12.8,1],[11.8,1]]}],"u":23}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_b#4','math',3,2,'u4','','tb_g3_2_math_u4_review_b','unit_review','M3-2-u4-C4',1,'sa','auto','색 테이프 6 m의 ⟨1/3⟩만큼은 몇 m인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M3-2-u4-C4","difficulty":1,"kind":"sa","stem":"색 테이프 6 m의 ⟨1/3⟩만큼은 몇 m인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["6 m를 똑같이 3부분으로 나누면 한 부분이 2 m예요 — 6 ÷ 3 = 2.","⟨1/3⟩은 그중 1부분이에요.","6 m의 ⟨1/3⟩만큼은 2 m예요."],"asset":{"type":"fbar","bars":[{"den":3,"num":1,"label":"색 테이프 6 m"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_b#5','math',3,2,'u4','','tb_g3_2_math_u4_review_b','unit_review','M3-2-u4-C5',1,'mc','auto','분수 ⟨13/12⟩은 진분수, 가분수, 대분수, 자연수 중 무엇인가요?',ARRAY['M3-2-u4-X08']::text[],false,'{"seq":5,"concept":"M3-2-u4-C5","difficulty":1,"kind":"mc","stem":"분수 ⟨13/12⟩은 진분수, 가분수, 대분수, 자연수 중 무엇인가요?","options":[{"t":"가분수","correct":true},{"t":"진분수","mis":"M3-2-u4-X08"},{"t":"대분수","mis":"M3-2-u4-X08"},{"t":"자연수","mis":"M3-2-u4-X08"}],"explanation":["분자 13과 분모 12를 견주어요.","분자가 분모보다 커요.","⟨13/12⟩은 가분수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_b#6','math',3,2,'u4','','tb_g3_2_math_u4_review_b','unit_review','M3-2-u4-C8',1,'mc','auto','「스스로 마무리하기」 두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨5 2/3⟩ ○ ⟨7 1/3⟩',ARRAY['M3-2-u4-X13','M3-2-u4-X22']::text[],false,'{"seq":6,"concept":"M3-2-u4-C8","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨5 2/3⟩ ○ ⟨7 1/3⟩","options":[{"t":"<","correct":true},{"t":">","mis":"M3-2-u4-X13"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["분모가 같은 대분수는 먼저 자연수의 크기를 비교해요.","자연수의 크기가 같으면 진분수의 크기를 비교해요.","그래서 ⟨5 2/3⟩ < ⟨7 1/3⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_b#7','math',3,2,'u4','','tb_g3_2_math_u4_review_b','unit_review','M3-2-u4-C9',1,'mc','auto','「스스로 마무리하기」 빈칸을 채워요. ⟨2 6/10⟩을 소수로 쓰고 읽은 것으로 알맞은 것은 무엇인가요?',ARRAY['M3-2-u4-X16','M3-2-u4-X17']::text[],false,'{"seq":7,"concept":"M3-2-u4-C9","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 빈칸을 채워요. ⟨2 6/10⟩을 소수로 쓰고 읽은 것으로 알맞은 것은 무엇인가요?","options":[{"t":"2.6 — 이 점 육","correct":true},{"t":"6.2 — 육 점 이","mis":"M3-2-u4-X16"},{"t":"2.6 — 육 점 이","mis":"M3-2-u4-X16"},{"t":"0.26 — 영 점 이육","mis":"M3-2-u4-X17"}],"explanation":["⟨6/10⟩ = 0.6이에요.","⟨2 6/10⟩ = 2.6이에요.","2.6은 「이 점 육」이라고 읽어요."],"asset":{"type":"fbar","bars":[{"den":10,"num":10},{"den":10,"num":10},{"den":10,"num":6}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_b#8','math',3,2,'u4','','tb_g3_2_math_u4_review_b','unit_review','M3-2-u4-C10',1,'mc','auto','「스스로 마무리하기」 두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  1.2 ○ 1.5',ARRAY['M3-2-u4-X20','M3-2-u4-X22']::text[],false,'{"seq":8,"concept":"M3-2-u4-C10","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  1.2 ○ 1.5","options":[{"t":"<","correct":true},{"t":">","mis":"M3-2-u4-X20"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["1.2는 0.1이 12개, 1.5는 0.1이 15개예요.","자연수의 크기를 먼저 비교하고, 같으면 소수점 오른쪽 수의 크기를 비교해요.","그래서 1.2 < 1.5."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_b#9','math',3,2,'u4','','tb_g3_2_math_u4_review_b','unit_review','M3-2-u4-C3',2,'mc','auto','「익힘」 건우는 약과 12개의 ⟨2/4⟩만큼을 먹었어요. 건우가 먹은 약과는 몇 개인가요?',ARRAY['M3-2-u4-X04','M3-2-u4-X05']::text[],false,'{"seq":9,"concept":"M3-2-u4-C3","difficulty":2,"kind":"mc","stem":"「익힘」 건우는 약과 12개의 ⟨2/4⟩만큼을 먹었어요. 건우가 먹은 약과는 몇 개인가요?","options":[{"t":"6개","correct":true},{"t":"2개","mis":"M3-2-u4-X04"},{"t":"3개","mis":"M3-2-u4-X05"}],"explanation":["12개를 똑같이 4묶음으로 나누면 한 묶음이 3개예요 — 12 ÷ 4 = 3.","⟨2/4⟩는 ⟨1/4⟩이 2개 — 2묶음이에요.","12개의 ⟨2/4⟩만큼은 6개예요. 분자 2만 보고 답하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_b#10','math',3,2,'u4','','tb_g3_2_math_u4_review_b','unit_review','M3-2-u4-C10',2,'mc','auto','초록색 리본의 길이는 1.8 m, 분홍색 리본의 길이는 2.3 m예요. 어느 색 리본이 더 긴가요?',ARRAY['M3-2-u4-X18','M3-2-u4-X22']::text[],false,'{"seq":10,"concept":"M3-2-u4-C10","difficulty":2,"kind":"mc","stem":"초록색 리본의 길이는 1.8 m, 분홍색 리본의 길이는 2.3 m예요. 어느 색 리본이 더 긴가요?","options":[{"t":"분홍색 리본","correct":true},{"t":"초록색 리본","mis":"M3-2-u4-X18"},{"t":"두 리본의 길이가 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수의 크기를 비교하면 1 < 2예요.","1.8 < 2.3이에요.","분홍색 리본이 더 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_b#11','math',3,2,'u4','','tb_g3_2_math_u4_review_b','unit_review','M3-2-u4-C5',2,'sa','auto','「익힘」 ⟨8/7⟩, ⟨4/4⟩, 4, ⟨7/8⟩, ⟨3/9⟩ 중에서 가분수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"M3-2-u4-C5","difficulty":2,"kind":"sa","stem":"「익힘」 ⟨8/7⟩, ⟨4/4⟩, 4, ⟨7/8⟩, ⟨3/9⟩ 중에서 가분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["진분수는 분자가 분모보다 작은 분수, 가분수는 분자가 분모와 같거나 큰 분수예요.","가분수: ⟨8/7⟩, ⟨4/4⟩.","모두 2개 — 분자와 분모가 같은 분수도 가분수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_b#12','math',3,2,'u4','','tb_g3_2_math_u4_review_b','unit_review','M3-2-u4-C7',2,'mc','auto','「확인 문제」 은비는 냄비에 물을 ⟨2 3/4⟩컵 넣었어요. 은비가 넣은 물은 몇 컵인지 가분수로 나타내면 무엇인가요?',ARRAY['M3-2-u4-X10','M3-2-u4-X03']::text[],false,'{"seq":12,"concept":"M3-2-u4-C7","difficulty":2,"kind":"mc","stem":"「확인 문제」 은비는 냄비에 물을 ⟨2 3/4⟩컵 넣었어요. 은비가 넣은 물은 몇 컵인지 가분수로 나타내면 무엇인가요?","options":[{"t":"⟨11/4⟩","correct":true},{"t":"⟨7/4⟩","mis":"M3-2-u4-X10"},{"t":"⟨5/4⟩","mis":"M3-2-u4-X10"},{"t":"⟨4/11⟩","mis":"M3-2-u4-X03"}],"explanation":["자연수 2는 ⟨1/4⟩이 8개예요.","⟨3/4⟩은 ⟨1/4⟩이 3개 — 모두 8 + 3 = 11개예요.","⟨2 3/4⟩ = ⟨11/4⟩ — 분모는 그대로 두고 단위분수의 개수를 세어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_b#13','math',3,2,'u4','','tb_g3_2_math_u4_review_b','unit_review','M3-2-u4-C9',2,'mc','auto','46 mm는 몇 cm인지 소수로 나타내면 무엇인가요?',ARRAY['M3-2-u4-X17','M3-2-u4-X16']::text[],false,'{"seq":13,"concept":"M3-2-u4-C9","difficulty":2,"kind":"mc","stem":"46 mm는 몇 cm인지 소수로 나타내면 무엇인가요?","options":[{"t":"4.6 cm","correct":true},{"t":"46 cm","mis":"M3-2-u4-X17"},{"t":"0.46 cm","mis":"M3-2-u4-X17"},{"t":"6.4 cm","mis":"M3-2-u4-X16"}],"explanation":["10 mm = 1 cm예요.","46 mm는 4 cm 6 mm — 4 cm와 ⟨6/10⟩ cm예요.","46 mm = 4.6 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_b#14','math',3,2,'u4','','tb_g3_2_math_u4_review_b','unit_review','M3-2-u4-C7',2,'mc','auto','「익힘」 ⟨2 3/5⟩을 바르게 읽은 것은 무엇인가요?',ARRAY['M3-2-u4-X03','M3-2-u4-X16','M3-2-u4-X12']::text[],false,'{"seq":14,"concept":"M3-2-u4-C7","difficulty":2,"kind":"mc","stem":"「익힘」 ⟨2 3/5⟩을 바르게 읽은 것은 무엇인가요?","options":[{"t":"이와 오분의 삼","correct":true},{"t":"이와 삼분의 오","mis":"M3-2-u4-X03"},{"t":"이 점 삼오","mis":"M3-2-u4-X16"},{"t":"오분의 삼","mis":"M3-2-u4-X12"}],"explanation":["대분수는 자연수 부분을 먼저 읽고 「과(와)」를 붙여요.","분수 부분은 분모부터 「○분의 △」로 읽어요.","⟨2 3/5⟩은 「이와 오분의 삼」이라고 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_b#15','math',3,2,'u4','','tb_g3_2_math_u4_review_b','unit_review','M3-2-u4-C4',2,'sa','auto','「익힘」 채원이는 하루의 ⟨6/24⟩만큼 학교에 있었어요. 하루는 24시간이에요. 학교에 있었던 시간은 몇 시간인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"M3-2-u4-C4","difficulty":2,"kind":"sa","stem":"「익힘」 채원이는 하루의 ⟨6/24⟩만큼 학교에 있었어요. 하루는 24시간이에요. 학교에 있었던 시간은 몇 시간인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["24시간을 똑같이 24부분으로 나누면 한 부분이 1시간이에요 — 24 ÷ 24 = 1.","⟨6/24⟩은 ⟨1/24⟩이 6개 — 6부분이에요.","24시간의 ⟨6/24⟩만큼은 6시간이에요. 분자 6만 보고 답하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_b#16','math',3,2,'u4','','tb_g3_2_math_u4_review_b','unit_review','M3-2-u4-C11',2,'mc','auto','「익힘」 두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨8 5/10⟩ ○ 8.8',ARRAY['M3-2-u4-X14','M3-2-u4-X22']::text[],false,'{"seq":16,"concept":"M3-2-u4-C11","difficulty":2,"kind":"mc","stem":"「익힘」 두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨8 5/10⟩ ○ 8.8","options":[{"t":"<","correct":true},{"t":">","mis":"M3-2-u4-X14"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["분모가 10인 분수는 소수로 나타내어 비교할 수 있어요.","⟨8 5/10⟩ = 8.5예요.","자연수부터 비교하면 ⟨8 5/10⟩ < 8.8."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_b#17','math',3,2,'u4','','tb_g3_2_math_u4_review_b','unit_review','M3-2-u4-C8',3,'mc','auto','「익힘」 채원이는 우유 ⟨8/3⟩컵을, 건우는 우유 ⟨1 1/3⟩컵을 사용했어요. 컵의 크기가 같을 때 우유를 더 많이 사용한 사람은 누구인가요?',ARRAY['M3-2-u4-X14','M3-2-u4-X22']::text[],false,'{"seq":17,"concept":"M3-2-u4-C8","difficulty":3,"kind":"mc","stem":"「익힘」 채원이는 우유 ⟨8/3⟩컵을, 건우는 우유 ⟨1 1/3⟩컵을 사용했어요. 컵의 크기가 같을 때 우유를 더 많이 사용한 사람은 누구인가요?","options":[{"t":"채원","correct":true},{"t":"건우","mis":"M3-2-u4-X14"},{"t":"두 사람이 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["⟨8/3⟩ = ⟨2 2/3⟩예요.","⟨2 2/3⟩와 ⟨1 1/3⟩의 자연수를 비교하면 2 > 1이에요.","⟨8/3⟩ > ⟨1 1/3⟩ — 채원이가 더 많이 사용했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_b#18','math',3,2,'u4','','tb_g3_2_math_u4_review_b','unit_review','M3-2-u4-C2',3,'mc','auto','와플 4개를 똑같이 2묶음으로 나누었을 때 와플 2개를 1보다 작은 분수 ⟨1/2⟩로 나타낼 수 있는 까닭은 무엇인가요?',ARRAY['M3-2-u4-X26','M3-2-u4-X23','M3-2-u4-X07']::text[],false,'{"seq":18,"concept":"M3-2-u4-C2","difficulty":3,"kind":"mc","stem":"와플 4개를 똑같이 2묶음으로 나누었을 때 와플 2개를 1보다 작은 분수 ⟨1/2⟩로 나타낼 수 있는 까닭은 무엇인가요?","options":[{"t":"전체가 와플 4개이기 때문에","correct":true},{"t":"와플 1개를 반으로 자른 것과 같아서","mis":"M3-2-u4-X26"},{"t":"한 묶음에 와플이 2개씩이라서","mis":"M3-2-u4-X23"},{"t":"묶음이 2개뿐이라서","mis":"M3-2-u4-X07"}],"explanation":["분수는 전체와 부분의 관계를 나타내는 수예요.","전체가 와플 4개이고, 와플 2개는 그중 1묶음이에요.","그래서 와플 2개는 전체의 ⟨1/2⟩ — 1보다 작은 분수예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]]},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]}],"u":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_b#19','math',3,2,'u4','','tb_g3_2_math_u4_review_b','unit_review','M3-2-u4-C3',3,'ox','auto','건우는 「도토리 12개의 ⟨3/4⟩만큼은 3개야.」라고 했어요. 건우의 말이 옳은가요?',ARRAY['M3-2-u4-X04']::text[],false,'{"seq":19,"concept":"M3-2-u4-C3","difficulty":3,"kind":"ox","stem":"건우는 「도토리 12개의 ⟨3/4⟩만큼은 3개야.」라고 했어요. 건우의 말이 옳은가요?","answer":"X","reason_options":[{"t":"12를 똑같이 4묶음으로 나누면 3묶음이 9개라서","correct":true},{"t":"분자가 3이니까","mis":"M3-2-u4-X04"}],"mis":"M3-2-u4-X04","explanation":["도토리 12개를 똑같이 4묶음으로 나누면 한 묶음에 3개예요.","⟨3/4⟩은 4묶음 중 3묶음이에요.","도토리 12개의 ⟨3/4⟩만큼은 9개예요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[4.7,0],[5.7,0],[5.7,1],[4.7,1]],"hi":true},{"p":[[5.7,0],[6.7,0],[6.7,1],[5.7,1]],"hi":true},{"p":[[7.4,0],[8.4,0],[8.4,1],[7.4,1]],"hi":true},{"p":[[8.4,0],[9.4,0],[9.4,1],[8.4,1]],"hi":true},{"p":[[9.4,0],[10.4,0],[10.4,1],[9.4,1]],"hi":true},{"p":[[11.1,0],[12.1,0],[12.1,1],[11.1,1]]},{"p":[[12.1,0],[13.1,0],[13.1,1],[12.1,1]]},{"p":[[13.1,0],[14.1,0],[14.1,1],[13.1,1]]}],"u":21}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_b#20','math',3,2,'u4','','tb_g3_2_math_u4_review_b','unit_review','M3-2-u4-C5',3,'error','auto','진분수, 가분수, 자연수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u4-X24','M3-2-u4-X20']::text[],false,'{"seq":20,"concept":"M3-2-u4-C5","difficulty":3,"kind":"error","stem":"진분수, 가분수, 자연수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서준 — 「⟨8/8⟩은 1과 같으니까 자연수야」","correct":true,"mis_target":"M3-2-u4-X24"},{"t":"채원 — 「1은 ⟨4/4⟩와 같아」","mis":"M3-2-u4-X20"},{"t":"도윤 — 「2는 ⟨8/4⟩로 나타낼 수 있어」","mis":"M3-2-u4-X20"}],"explanation":["1 = ⟨4/4⟩, 2 = ⟨8/4⟩이에요.","⟨8/8⟩은 1과 크기가 같은 가분수예요.","서준이는 크기가 같은 가분수를 자연수라고 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_b#21','math',3,2,'u4','','tb_g3_2_math_u4_review_b','unit_review','M3-2-u4-C9',3,'sa','auto','「익힘」 어제 52 mm의 비가 내렸어요. 비의 양을 cm로 나타내면 0.1 cm가 몇 개인 길이인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M3-2-u4-C9","difficulty":3,"kind":"sa","stem":"「익힘」 어제 52 mm의 비가 내렸어요. 비의 양을 cm로 나타내면 0.1 cm가 몇 개인 길이인가요? 숫자로 쓰세요.","answer":["52"],"explanation":["1 mm = 0.1 cm예요.","52 mm = 5.2 cm예요.","5.2는 0.1이 52개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_b#22','math',3,2,'u4','','tb_g3_2_math_u4_review_b','unit_review','M3-2-u4-C11',3,'sa','auto','자연수 1부터 9까지의 수 중에서 1.□ > 1.6이 되도록 □에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":22,"concept":"M3-2-u4-C11","difficulty":3,"kind":"sa","stem":"자연수 1부터 9까지의 수 중에서 1.□ > 1.6이 되도록 □에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["두 소수는 자연수가 1로 같아요.","□ > 6이어야 해요.","□에는 7, 8, 9 — 모두 3개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_b#23','math',3,2,'u4','','tb_g3_2_math_u4_review_b','unit_review','M3-2-u4-C2',4,'essay','teacher','검은 바둑돌 3개와 흰 바둑돌 4개가 있어요. 친구가 「검은 바둑돌은 ⟨3/4⟩이야.」라고 했어요. 검은 바둑돌은 전체의 얼마인지 쓰고, 친구의 생각에서 무엇이 잘못되었는지 설명해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M3-2-u4-C2","difficulty":4,"kind":"essay","stem":"검은 바둑돌 3개와 흰 바둑돌 4개가 있어요. 친구가 「검은 바둑돌은 ⟨3/4⟩이야.」라고 했어요. 검은 바둑돌은 전체의 얼마인지 쓰고, 친구의 생각에서 무엇이 잘못되었는지 설명해 보세요.","answer_guide":{"answer":"예: 검은 바둑돌은 전체 7개 중 3개이므로 전체의 ⟨3/7⟩이다. 친구는 전체가 아니라 흰 바둑돌과 견주었다. 분수로 나타낼 때는 먼저 전체를 정하고 부분을 전체와 견주어야 한다.","scoring_points":["⟨3/7⟩이라고 답했는가","흰 바둑돌과 견준 것이 잘못이라고 썼는가","전체를 먼저 정해야 한다고 썼는가"]},"explanation":["바둑돌은 모두 7개예요.","검은 바둑돌은 전체의 ⟨3/7⟩이에요.","부분끼리 견주지 않아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[4,0],[5,0],[5,1],[4,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[1,1],[2,1],[2,2],[1,2]]}],"u":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_b#24','math',3,2,'u4','','tb_g3_2_math_u4_review_b','unit_review','M3-2-u4-C3',4,'essay','teacher','12의 ⟨1/3⟩과 12의 ⟨2/3⟩를 구하고, 구한 방법을 묶음으로 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M3-2-u4-C3","difficulty":4,"kind":"essay","stem":"12의 ⟨1/3⟩과 12의 ⟨2/3⟩를 구하고, 구한 방법을 묶음으로 설명해 보세요.","answer_guide":{"answer":"예: 12를 분모 3만큼 똑같이 3묶음으로 나누면 한 묶음에 4이다. 12의 ⟨1/3⟩은 1묶음이므로 4이고, 12의 ⟨2/3⟩는 2묶음이므로 8이다.","scoring_points":["12의 ⟨1/3⟩을 4라고 구했는가","12의 ⟨2/3⟩를 8이라고 구했는가","분모만큼 나누고 분자만큼 센다고 설명했는가"]},"explanation":["12 ÷ 3 = 4예요.","12의 ⟨2/3⟩는 8이에요.","3개씩 묶어 3이라 하지 않아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]],"hi":true},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[2.7,1],[3.7,1],[3.7,2],[2.7,2]],"hi":true},{"p":[[3.7,1],[4.7,1],[4.7,2],[3.7,2]],"hi":true},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]]},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]]},{"p":[[5.4,1],[6.4,1],[6.4,2],[5.4,2]]},{"p":[[6.4,1],[7.4,1],[7.4,2],[6.4,2]]}],"u":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_b#25','math',3,2,'u4','','tb_g3_2_math_u4_review_b','unit_review','M3-2-u4-C10',4,'essay','teacher','3.5와 2.6의 크기를 비교하고, 그 방법을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u4-C10","difficulty":4,"kind":"essay","stem":"3.5와 2.6의 크기를 비교하고, 그 방법을 설명해 보세요.","answer_guide":{"answer":"예: 3.5 > 2.6이다. 자연수의 크기를 먼저 비교하면 3 > 2이므로 3.5가 더 크다. 0.1의 개수로 보면 3.5는 0.1이 35개, 2.6은 0.1이 26개이므로 35 > 26이다.","scoring_points":["3.5 > 2.6이라고 답했는가","자연수의 크기를 먼저 비교했는가","0.1의 개수나 수직선으로 확인했는가"]},"explanation":["자연수 3 > 2예요.","0.1이 35개 > 26개예요.","3.5가 더 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_c#1','math',3,2,'u4','','tb_g3_2_math_u4_review_c','unit_review','M3-2-u4-C1',1,'mc','auto','15를 3씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?',ARRAY['M3-2-u4-X01','M3-2-u4-X03','M3-2-u4-X02']::text[],false,'{"seq":1,"concept":"M3-2-u4-C1","difficulty":1,"kind":"mc","stem":"15를 3씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?","options":[{"t":"⟨3/5⟩","correct":true},{"t":"⟨3/2⟩","mis":"M3-2-u4-X01"},{"t":"⟨5/3⟩","mis":"M3-2-u4-X03"},{"t":"⟨9/5⟩","mis":"M3-2-u4-X02"}],"explanation":["15를 3씩 묶으면 5묶음 — 전체 묶음의 수 5가 분모예요.","부분은 그중 3묶음 — 부분 묶음의 수 3이 분자예요.","9는 15의 ⟨3/5⟩ — 낱개의 수가 아니라 묶음의 수로 나타내요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[4.7,0],[5.7,0],[5.7,1],[4.7,1]],"hi":true},{"p":[[5.7,0],[6.7,0],[6.7,1],[5.7,1]],"hi":true},{"p":[[7.4,0],[8.4,0],[8.4,1],[7.4,1]],"hi":true},{"p":[[8.4,0],[9.4,0],[9.4,1],[8.4,1]],"hi":true},{"p":[[9.4,0],[10.4,0],[10.4,1],[9.4,1]],"hi":true},{"p":[[11.1,0],[12.1,0],[12.1,1],[11.1,1]]},{"p":[[12.1,0],[13.1,0],[13.1,1],[12.1,1]]},{"p":[[13.1,0],[14.1,0],[14.1,1],[13.1,1]]},{"p":[[14.8,0],[15.8,0],[15.8,1],[14.8,1]]},{"p":[[15.8,0],[16.8,0],[16.8,1],[15.8,1]]},{"p":[[16.8,0],[17.8,0],[17.8,1],[16.8,1]]}],"u":16}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_c#2','math',3,2,'u4','','tb_g3_2_math_u4_review_c','unit_review','M3-2-u4-C2',1,'mc','auto','「확인 문제」 딸기 16개를 4개씩 묶었더니 색칠한 딸기가 12개였어요. 12는 16의 얼마인가요?',ARRAY['M3-2-u4-X03','M3-2-u4-X02']::text[],false,'{"seq":2,"concept":"M3-2-u4-C2","difficulty":1,"kind":"mc","stem":"「확인 문제」 딸기 16개를 4개씩 묶었더니 색칠한 딸기가 12개였어요. 12는 16의 얼마인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨4/3⟩","mis":"M3-2-u4-X03"},{"t":"⟨12/4⟩","mis":"M3-2-u4-X02"},{"t":"⟨3/16⟩","mis":"M3-2-u4-X02"}],"explanation":["16을 4씩 묶으면 4묶음 — 전체 묶음의 수 4가 분모예요.","부분은 그중 3묶음 — 부분 묶음의 수 3이 분자예요.","12는 16의 ⟨3/4⟩ — 낱개의 수가 아니라 묶음의 수로 나타내요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]],"hi":true},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[2.7,1],[3.7,1],[3.7,2],[2.7,2]],"hi":true},{"p":[[3.7,1],[4.7,1],[4.7,2],[3.7,2]],"hi":true},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]],"hi":true},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]],"hi":true},{"p":[[5.4,1],[6.4,1],[6.4,2],[5.4,2]],"hi":true},{"p":[[6.4,1],[7.4,1],[7.4,2],[6.4,2]],"hi":true},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]]},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]]},{"p":[[8.1,1],[9.1,1],[9.1,2],[8.1,2]]},{"p":[[9.1,1],[10.1,1],[10.1,2],[9.1,2]]}],"u":29}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_c#3','math',3,2,'u4','','tb_g3_2_math_u4_review_c','unit_review','M3-2-u4-C3',1,'sa','auto','12의 ⟨2/3⟩는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u4-C3","difficulty":1,"kind":"sa","stem":"12의 ⟨2/3⟩는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["12를 똑같이 3묶음으로 나누면 한 묶음이 4예요 — 12 ÷ 3 = 4.","⟨2/3⟩는 ⟨1/3⟩이 2개 — 2묶음이에요.","12의 ⟨2/3⟩만큼은 8이에요. 분자 2만 보고 답하지 않아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]],"hi":true},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[2.7,1],[3.7,1],[3.7,2],[2.7,2]],"hi":true},{"p":[[3.7,1],[4.7,1],[4.7,2],[3.7,2]],"hi":true},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]]},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]]},{"p":[[5.4,1],[6.4,1],[6.4,2],[5.4,2]]},{"p":[[6.4,1],[7.4,1],[7.4,2],[6.4,2]]}],"u":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_c#4','math',3,2,'u4','','tb_g3_2_math_u4_review_c','unit_review','M3-2-u4-C4',1,'sa','auto','25의 ⟨4/5⟩는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M3-2-u4-C4","difficulty":1,"kind":"sa","stem":"25의 ⟨4/5⟩는 얼마인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["25를 똑같이 5부분으로 나누면 한 부분이 5예요 — 25 ÷ 5 = 5.","⟨4/5⟩는 ⟨1/5⟩이 4개 — 4부분이에요.","25의 ⟨4/5⟩만큼은 20이에요. 분자 4만 보고 답하지 않아요."],"asset":{"type":"fbar","bars":[{"den":5,"num":4,"label":"0부터 25까지"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_c#5','math',3,2,'u4','','tb_g3_2_math_u4_review_c','unit_review','M3-2-u4-C5',1,'mc','auto','「확인 문제」 분수 ⟨9/9⟩는 진분수, 가분수, 대분수, 자연수 중 무엇인가요?',ARRAY['M3-2-u4-X08','M3-2-u4-X24']::text[],false,'{"seq":5,"concept":"M3-2-u4-C5","difficulty":1,"kind":"mc","stem":"「확인 문제」 분수 ⟨9/9⟩는 진분수, 가분수, 대분수, 자연수 중 무엇인가요?","options":[{"t":"가분수","correct":true},{"t":"진분수","mis":"M3-2-u4-X08"},{"t":"대분수","mis":"M3-2-u4-X08"},{"t":"자연수","mis":"M3-2-u4-X24"}],"explanation":["분자 9와 분모 9를 견주어요.","분자가 분모보다 같아요.","⟨9/9⟩는 가분수예요. 1과 크기가 같아도 꼴은 가분수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_c#6','math',3,2,'u4','','tb_g3_2_math_u4_review_c','unit_review','M3-2-u4-C8',1,'mc','auto','두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨13/9⟩ ○ ⟨10/9⟩',ARRAY['M3-2-u4-X13','M3-2-u4-X22']::text[],false,'{"seq":6,"concept":"M3-2-u4-C8","difficulty":1,"kind":"mc","stem":"두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨13/9⟩ ○ ⟨10/9⟩","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u4-X13"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["분모가 같은 가분수는 분자의 크기를 비교해요.","⟨13/9⟩은 ⟨1/9⟩이 13개, ⟨10/9⟩은 10개예요.","그래서 ⟨13/9⟩ > ⟨10/9⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_c#7','math',3,2,'u4','','tb_g3_2_math_u4_review_c','unit_review','M3-2-u4-C9',1,'mc','auto','종이 빨대의 길이 4 cm 7 mm는 몇 cm인지 소수로 나타내면 무엇인가요?',ARRAY['M3-2-u4-X17','M3-2-u4-X16']::text[],false,'{"seq":7,"concept":"M3-2-u4-C9","difficulty":1,"kind":"mc","stem":"종이 빨대의 길이 4 cm 7 mm는 몇 cm인지 소수로 나타내면 무엇인가요?","options":[{"t":"4.7 cm","correct":true},{"t":"4.07 cm","mis":"M3-2-u4-X17"},{"t":"7.4 cm","mis":"M3-2-u4-X16"},{"t":"47 cm","mis":"M3-2-u4-X17"}],"explanation":["7 mm는 1 cm를 똑같이 10으로 나눈 것 중의 7 — ⟨7/10⟩ cm = 0.7 cm예요.","4 cm 7 mm = ⟨4 7/10⟩ cm예요.","4 cm 7 mm = 4.7 cm — 「사 점 칠」이라고 읽어요."],"asset":{"type":"mmruler","len":47,"label":"종이 빨대"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_c#8','math',3,2,'u4','','tb_g3_2_math_u4_review_c','unit_review','M3-2-u4-C10',1,'mc','auto','두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  3.5 ○ 2.6',ARRAY['M3-2-u4-X18','M3-2-u4-X22']::text[],false,'{"seq":8,"concept":"M3-2-u4-C10","difficulty":1,"kind":"mc","stem":"두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  3.5 ○ 2.6","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u4-X18"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["3.5는 0.1이 35개, 2.6은 0.1이 26개예요.","자연수의 크기를 먼저 비교하고, 같으면 소수점 오른쪽 수의 크기를 비교해요.","그래서 3.5 > 2.6."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_c#9','math',3,2,'u4','','tb_g3_2_math_u4_review_c','unit_review','M3-2-u4-C3',2,'mc','auto','「익힘」 은비는 약과 12개의 ⟨1/4⟩만큼을 먹었어요. 은비가 먹은 약과는 몇 개인가요?',ARRAY['M3-2-u4-X04','M3-2-u4-X23']::text[],false,'{"seq":9,"concept":"M3-2-u4-C3","difficulty":2,"kind":"mc","stem":"「익힘」 은비는 약과 12개의 ⟨1/4⟩만큼을 먹었어요. 은비가 먹은 약과는 몇 개인가요?","options":[{"t":"3개","correct":true},{"t":"1개","mis":"M3-2-u4-X04"},{"t":"4개","mis":"M3-2-u4-X23"}],"explanation":["12개를 똑같이 4묶음으로 나누면 한 묶음이 3개예요 — 12 ÷ 4 = 3.","⟨1/4⟩은 그중 1묶음이에요.","12개의 ⟨1/4⟩만큼은 3개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_c#10','math',3,2,'u4','','tb_g3_2_math_u4_review_c','unit_review','M3-2-u4-C10',2,'mc','auto','「익힘」 큐브 빨리 맞추기 대회에서 서준이는 7.3초, 건우는 6.7초, 도윤이는 6.5초가 걸렸어요. 가장 빨리 큐브를 맞춘 사람은 누구인가요?',ARRAY['M3-2-u4-X19','M3-2-u4-X20','M3-2-u4-X22']::text[],false,'{"seq":10,"concept":"M3-2-u4-C10","difficulty":2,"kind":"mc","stem":"「익힘」 큐브 빨리 맞추기 대회에서 서준이는 7.3초, 건우는 6.7초, 도윤이는 6.5초가 걸렸어요. 가장 빨리 큐브를 맞춘 사람은 누구인가요?","options":[{"t":"도윤","correct":true},{"t":"서준","mis":"M3-2-u4-X19"},{"t":"건우","mis":"M3-2-u4-X20"},{"t":"세 사람이 같아요","mis":"M3-2-u4-X22"}],"explanation":["7.3이 가장 큰 수예요.","6.7과 6.5는 자연수가 같고 7 > 5 — 가장 작은 수는 6.5예요.","걸린 시간이 가장 짧은 도윤이가 가장 빨라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_c#11','math',3,2,'u4','','tb_g3_2_math_u4_review_c','unit_review','M3-2-u4-C5',2,'sa','auto','「확인 문제」 ⟨6/13⟩, ⟨5/4⟩, ⟨6/8⟩, ⟨25/11⟩, ⟨9/9⟩, ⟨4/3⟩ 중에서 진분수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"M3-2-u4-C5","difficulty":2,"kind":"sa","stem":"「확인 문제」 ⟨6/13⟩, ⟨5/4⟩, ⟨6/8⟩, ⟨25/11⟩, ⟨9/9⟩, ⟨4/3⟩ 중에서 진분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["진분수는 분자가 분모보다 작은 분수, 가분수는 분자가 분모와 같거나 큰 분수예요.","진분수: ⟨6/13⟩, ⟨6/8⟩.","모두 2개 — 분자와 분모가 같은 분수도 가분수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_c#12','math',3,2,'u4','','tb_g3_2_math_u4_review_c','unit_review','M3-2-u4-C7',2,'mc','auto','⟨17/5⟩을 대분수로 나타낸 것은 무엇인가요?',ARRAY['M3-2-u4-X11','M3-2-u4-X12','M3-2-u4-X21']::text[],false,'{"seq":12,"concept":"M3-2-u4-C7","difficulty":2,"kind":"mc","stem":"⟨17/5⟩을 대분수로 나타낸 것은 무엇인가요?","options":[{"t":"⟨3 2/5⟩","correct":true},{"t":"⟨2 7/5⟩","mis":"M3-2-u4-X11"},{"t":"⟨2/5⟩","mis":"M3-2-u4-X12"},{"t":"⟨4 2/5⟩","mis":"M3-2-u4-X21"}],"explanation":["⟨17/5⟩은 ⟨1/5⟩이 17개예요.","⟨1/5⟩이 5개씩 모이면 1 — 자연수 3만큼 모으고 ⟨1/5⟩이 2개 남아요.","⟨17/5⟩ = ⟨3 2/5⟩ — 분수 부분은 진분수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_c#13','math',3,2,'u4','','tb_g3_2_math_u4_review_c','unit_review','M3-2-u4-C9',2,'mc','auto','0.1이 35개인 수를 소수로 나타내면 무엇인가요?',ARRAY['M3-2-u4-X17','M3-2-u4-X16']::text[],false,'{"seq":13,"concept":"M3-2-u4-C9","difficulty":2,"kind":"mc","stem":"0.1이 35개인 수를 소수로 나타내면 무엇인가요?","options":[{"t":"3.5","correct":true},{"t":"35","mis":"M3-2-u4-X17"},{"t":"0.35","mis":"M3-2-u4-X17"},{"t":"5.3","mis":"M3-2-u4-X16"}],"explanation":["0.1이 10개이면 1이에요.","0.1이 35개는 0.1이 30개(3)와 5개(0.5)예요.","0.1이 35개이면 3.5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_c#14','math',3,2,'u4','','tb_g3_2_math_u4_review_c','unit_review','M3-2-u4-C7',2,'mc','auto','⟨1 1/5⟩을 바르게 읽은 것은 무엇인가요?',ARRAY['M3-2-u4-X03','M3-2-u4-X16','M3-2-u4-X12']::text[],false,'{"seq":14,"concept":"M3-2-u4-C7","difficulty":2,"kind":"mc","stem":"⟨1 1/5⟩을 바르게 읽은 것은 무엇인가요?","options":[{"t":"일과 오분의 일","correct":true},{"t":"일과 일분의 오","mis":"M3-2-u4-X03"},{"t":"일 점 일오","mis":"M3-2-u4-X16"},{"t":"오분의 일","mis":"M3-2-u4-X12"}],"explanation":["대분수는 자연수 부분을 먼저 읽고 「과(와)」를 붙여요.","분수 부분은 분모부터 「○분의 △」로 읽어요.","⟨1 1/5⟩은 「일과 오분의 일」이라고 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_c#15','math',3,2,'u4','','tb_g3_2_math_u4_review_c','unit_review','M3-2-u4-C4',2,'sa','auto','「수학 되돌아보기」 서준이는 12시간의 ⟨6/12⟩만큼 친구와 함께 보냈어요. 친구와 함께한 시간은 몇 시간인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"M3-2-u4-C4","difficulty":2,"kind":"sa","stem":"「수학 되돌아보기」 서준이는 12시간의 ⟨6/12⟩만큼 친구와 함께 보냈어요. 친구와 함께한 시간은 몇 시간인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["12시간을 똑같이 12부분으로 나누면 한 부분이 1시간이에요 — 12 ÷ 12 = 1.","⟨6/12⟩은 ⟨1/12⟩이 6개 — 6부분이에요.","12시간의 ⟨6/12⟩만큼은 6시간이에요. 분자 6만 보고 답하지 않아요."],"asset":{"type":"fbar","bars":[{"den":12,"num":6,"label":"12시간"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_c#16','math',3,2,'u4','','tb_g3_2_math_u4_review_c','unit_review','M3-2-u4-C11',2,'mc','auto','두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  3.6 ○ ⟨2 5/10⟩',ARRAY['M3-2-u4-X14','M3-2-u4-X22']::text[],false,'{"seq":16,"concept":"M3-2-u4-C11","difficulty":2,"kind":"mc","stem":"두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  3.6 ○ ⟨2 5/10⟩","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u4-X14"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["분모가 10인 분수는 소수로 나타내어 비교할 수 있어요.","⟨2 5/10⟩ = 2.5예요.","자연수부터 비교하면 3.6 > ⟨2 5/10⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_c#17','math',3,2,'u4','','tb_g3_2_math_u4_review_c','unit_review','M3-2-u4-C8',3,'mc','auto','「확인 문제」 ⟨4 2/5⟩, 3, ⟨12/5⟩ 중에서 가장 작은 수는 무엇인가요?',ARRAY['M3-2-u4-X14','M3-2-u4-X20','M3-2-u4-X22']::text[],false,'{"seq":17,"concept":"M3-2-u4-C8","difficulty":3,"kind":"mc","stem":"「확인 문제」 ⟨4 2/5⟩, 3, ⟨12/5⟩ 중에서 가장 작은 수는 무엇인가요?","options":[{"t":"⟨12/5⟩","correct":true},{"t":"3","mis":"M3-2-u4-X14"},{"t":"⟨4 2/5⟩","mis":"M3-2-u4-X20"},{"t":"세 수가 모두 같아요","mis":"M3-2-u4-X22"}],"explanation":["⟨12/5⟩ = ⟨2 2/5⟩예요.","자연수 부분을 비교하면 2 < 3 < 4예요.","가장 작은 수는 ⟨12/5⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_c#18','math',3,2,'u4','','tb_g3_2_math_u4_review_c','unit_review','M3-2-u4-C2',3,'mc','auto','「익힘」 색칠한 부분이 전체의 ⟨2/4⟩가 아닌 것은 어느 것인가요?',ARRAY['M3-2-u4-X20','M3-2-u4-X23','M3-2-u4-X02']::text[],false,'{"seq":18,"concept":"M3-2-u4-C2","difficulty":3,"kind":"mc","stem":"「익힘」 색칠한 부분이 전체의 ⟨2/4⟩가 아닌 것은 어느 것인가요?","options":[{"t":"구슬 12개를 4개씩 묶은 것 중 2묶음을 색칠한 것","correct":true},{"t":"원을 똑같이 4로 나눈 것 중 2를 색칠한 것","mis":"M3-2-u4-X20"},{"t":"구슬 12개를 3개씩 묶은 것 중 2묶음을 색칠한 것","mis":"M3-2-u4-X23"},{"t":"구슬 8개를 2개씩 묶은 것 중 2묶음을 색칠한 것","mis":"M3-2-u4-X02"}],"explanation":["12개를 4개씩 묶으면 3묶음 — 2묶음은 전체의 ⟨2/3⟩예요.","12개를 3개씩 묶으면 4묶음, 8개를 2개씩 묶으면 4묶음 — 2묶음은 ⟨2/4⟩예요.","한 묶음의 개수가 아니라 묶음의 수가 분모예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_c#19','math',3,2,'u4','','tb_g3_2_math_u4_review_c','unit_review','M3-2-u4-C4',3,'ox','auto','지유는 「12의 ⟨1/4⟩은 4이고, 12의 ⟨3/4⟩은 12야.」라고 했어요. 지유의 말이 옳은가요?',ARRAY['M3-2-u4-X23']::text[],false,'{"seq":19,"concept":"M3-2-u4-C4","difficulty":3,"kind":"ox","stem":"지유는 「12의 ⟨1/4⟩은 4이고, 12의 ⟨3/4⟩은 12야.」라고 했어요. 지유의 말이 옳은가요?","answer":"X","reason_options":[{"t":"12를 똑같이 4부분으로 나누면 한 부분이 3이라서","correct":true},{"t":"분모 4가 한 부분의 크기라서","mis":"M3-2-u4-X23"}],"mis":"M3-2-u4-X23","explanation":["12의 ⟨1/4⟩은 12를 똑같이 4부분으로 나눈 1부분 — 3이에요.","12의 ⟨3/4⟩은 3이 3부분 — 9예요.","지유는 분모를 한 부분의 크기로 보았어요."],"asset":{"type":"fbar","bars":[{"den":12,"num":9,"grp":3,"label":"0부터 12까지"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_c#20','math',3,2,'u4','','tb_g3_2_math_u4_review_c','unit_review','M3-2-u4-C6',3,'sa','auto','「익힘」 ⟨10/5⟩은 자연수 얼마와 같나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":20,"concept":"M3-2-u4-C6","difficulty":3,"kind":"sa","stem":"「익힘」 ⟨10/5⟩은 자연수 얼마와 같나요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨5/5⟩ = 1이에요.","⟨10/5⟩은 ⟨1/5⟩이 10개 — 5개씩 2번이에요.","⟨10/5⟩ = 2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_c#21','math',3,2,'u4','','tb_g3_2_math_u4_review_c','unit_review','M3-2-u4-C9',3,'mc','auto','「익힘」 ⟨4 2/10⟩와 관계있는 소수는 무엇인가요?',ARRAY['M3-2-u4-X16','M3-2-u4-X17']::text[],false,'{"seq":21,"concept":"M3-2-u4-C9","difficulty":3,"kind":"mc","stem":"「익힘」 ⟨4 2/10⟩와 관계있는 소수는 무엇인가요?","options":[{"t":"4.2","correct":true},{"t":"2.4","mis":"M3-2-u4-X16"},{"t":"4.02","mis":"M3-2-u4-X17"},{"t":"42","mis":"M3-2-u4-X17"}],"explanation":["⟨2/10⟩ = 0.2예요.","⟨4 2/10⟩는 4와 0.2만큼이에요.","⟨4 2/10⟩ = 4.2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_c#22','math',3,2,'u4','','tb_g3_2_math_u4_review_c','unit_review','M3-2-u4-C11',3,'mc','auto','⟨1 □/10⟩과 1.△의 크기를 비교했더니 ⟨1 □/10⟩이 더 컸어요. □에는 8 또는 9, △에는 7, 8, 9 중 하나가 들어가요. □가 8일 때 △에 들어갈 수 있는 수를 모두 고른 것은 무엇인가요?',ARRAY['M3-2-u4-X21','M3-2-u4-X20']::text[],false,'{"seq":22,"concept":"M3-2-u4-C11","difficulty":3,"kind":"mc","stem":"⟨1 □/10⟩과 1.△의 크기를 비교했더니 ⟨1 □/10⟩이 더 컸어요. □에는 8 또는 9, △에는 7, 8, 9 중 하나가 들어가요. □가 8일 때 △에 들어갈 수 있는 수를 모두 고른 것은 무엇인가요?","options":[{"t":"7","correct":true},{"t":"7, 8","mis":"M3-2-u4-X21"},{"t":"8, 9","mis":"M3-2-u4-X20"},{"t":"9","mis":"M3-2-u4-X20"}],"explanation":["□가 8이면 ⟨1 8/10⟩ = 1.8이에요.","1.8 > 1.△이려면 △는 8보다 작아야 해요.","△에는 7만 들어갈 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_c#23','math',3,2,'u4','','tb_g3_2_math_u4_review_c','unit_review','M3-2-u4-C4',4,'essay','teacher','「6 m의 ⟨1/3⟩만큼」과 「⟨1/3⟩ m」는 같은 길이인지 쓰고, 그렇게 생각한 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M3-2-u4-C4","difficulty":4,"kind":"essay","stem":"「6 m의 ⟨1/3⟩만큼」과 「⟨1/3⟩ m」는 같은 길이인지 쓰고, 그렇게 생각한 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 같은 길이가 아니다. 6 m의 ⟨1/3⟩만큼은 6 m를 똑같이 3부분으로 나눈 것 중의 1부분이므로 2 m이다. ⟨1/3⟩ m는 1 m를 똑같이 3부분으로 나눈 것 중의 1부분이므로 1 m보다 짧다.","scoring_points":["같지 않다고 답했는가","6 m의 ⟨1/3⟩만큼이 2 m라고 구했는가","⟨1/3⟩ m는 1 m를 3부분으로 나눈 1부분이라고 설명했는가"]},"explanation":["6 m의 ⟨1/3⟩만큼은 2 m예요.","⟨1/3⟩ m는 1 m보다 짧아요.","전체가 무엇인지 보아요."],"asset":{"type":"fbar","bars":[{"den":3,"num":1,"label":"색 테이프 6 m"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_c#24','math',3,2,'u4','','tb_g3_2_math_u4_review_c','unit_review','M3-2-u4-C7',4,'essay','teacher','⟨2 3/4⟩을 가분수로, ⟨5/2⟩를 대분수로 나타내고, 각각의 방법을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M3-2-u4-C7","difficulty":4,"kind":"essay","stem":"⟨2 3/4⟩을 가분수로, ⟨5/2⟩를 대분수로 나타내고, 각각의 방법을 설명해 보세요.","answer_guide":{"answer":"예: 2는 ⟨1/4⟩이 8개이고 ⟨3/4⟩은 ⟨1/4⟩이 3개이므로 ⟨2 3/4⟩ = ⟨11/4⟩이다. ⟨5/2⟩는 ⟨4/2⟩와 ⟨1/2⟩이고 ⟨4/2⟩ = 2이므로 ⟨5/2⟩ = ⟨2 1/2⟩이다.","scoring_points":["⟨2 3/4⟩ = ⟨11/4⟩을 썼는가","⟨5/2⟩ = ⟨2 1/2⟩을 썼는가","단위분수의 개수·자연수로 나타낼 수 있는 부분으로 설명했는가"]},"explanation":["⟨2 3/4⟩ = ⟨11/4⟩이에요.","⟨5/2⟩ = ⟨2 1/2⟩이에요.","분수 부분은 진분수예요."],"asset":{"type":"fbar","bars":[{"den":4,"num":4},{"den":4,"num":4},{"den":4,"num":3}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_c#25','math',3,2,'u4','','tb_g3_2_math_u4_review_c','unit_review','M3-2-u4-C8',4,'essay','teacher','「익힘」 ⟨3 2/6⟩와 ⟨16/6⟩의 크기를 두 가지 방법으로 비교해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u4-C8","difficulty":4,"kind":"essay","stem":"「익힘」 ⟨3 2/6⟩와 ⟨16/6⟩의 크기를 두 가지 방법으로 비교해 보세요.","answer_guide":{"answer":"예: 방법 1 — ⟨3 2/6⟩ = ⟨20/6⟩이고 ⟨20/6⟩ > ⟨16/6⟩이므로 ⟨3 2/6⟩ > ⟨16/6⟩이다. 방법 2 — ⟨16/6⟩ = ⟨2 4/6⟩이고 자연수 3 > 2이므로 ⟨3 2/6⟩ > ⟨16/6⟩이다.","scoring_points":["대분수를 가분수로 바꾸어 비교했는가","가분수를 대분수로 바꾸어 비교했는가","⟨3 2/6⟩ > ⟨16/6⟩이라고 답했는가"]},"explanation":["⟨3 2/6⟩ = ⟨20/6⟩이에요.","⟨16/6⟩ = ⟨2 4/6⟩예요.","⟨3 2/6⟩가 더 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_d#1','math',3,2,'u4','','tb_g3_2_math_u4_review_d','unit_review','M3-2-u4-C1',1,'mc','auto','하트 6개를 2개씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?',ARRAY['M3-2-u4-X03','M3-2-u4-X02']::text[],false,'{"seq":1,"concept":"M3-2-u4-C1","difficulty":1,"kind":"mc","stem":"하트 6개를 2개씩 묶었어요. 색칠한 부분은 전체의 얼마인가요?","options":[{"t":"⟨2/3⟩","correct":true},{"t":"⟨3/2⟩","mis":"M3-2-u4-X03"},{"t":"⟨4/3⟩","mis":"M3-2-u4-X02"},{"t":"⟨2/6⟩","mis":"M3-2-u4-X02"}],"explanation":["6을 2씩 묶으면 3묶음 — 전체 묶음의 수 3이 분모예요.","부분은 그중 2묶음 — 부분 묶음의 수 2가 분자예요.","4는 6의 ⟨2/3⟩ — 낱개의 수가 아니라 묶음의 수로 나타내요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]]},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]]}],"u":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_d#2','math',3,2,'u4','','tb_g3_2_math_u4_review_d','unit_review','M3-2-u4-C2',1,'mc','auto','와플 4개를 똑같이 2묶음으로 나누었어요. 와플 1묶음은 전체의 얼마인가요?',ARRAY['M3-2-u4-X02','M3-2-u4-X03']::text[],false,'{"seq":2,"concept":"M3-2-u4-C2","difficulty":1,"kind":"mc","stem":"와플 4개를 똑같이 2묶음으로 나누었어요. 와플 1묶음은 전체의 얼마인가요?","options":[{"t":"⟨1/2⟩","correct":true},{"t":"⟨1/4⟩","mis":"M3-2-u4-X02"},{"t":"⟨4/2⟩","mis":"M3-2-u4-X03"}],"explanation":["전체는 와플 4개예요.","와플 1묶음은 2묶음 중의 1묶음이에요.","와플 1묶음은 전체의 ⟨1/2⟩이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]]},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]}],"u":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_d#3','math',3,2,'u4','','tb_g3_2_math_u4_review_d','unit_review','M3-2-u4-C3',1,'sa','auto','「확인 문제」 18의 ⟨2/3⟩는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u4-C3","difficulty":1,"kind":"sa","stem":"「확인 문제」 18의 ⟨2/3⟩는 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["18을 똑같이 3묶음으로 나누면 한 묶음이 6이에요 — 18 ÷ 3 = 6.","⟨2/3⟩는 ⟨1/3⟩이 2개 — 2묶음이에요.","18의 ⟨2/3⟩만큼은 12예요. 분자 2만 보고 답하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_d#4','math',3,2,'u4','','tb_g3_2_math_u4_review_d','unit_review','M3-2-u4-C4',1,'sa','auto','「익힘」 길이가 80 cm인 띠의 ⟨3/4⟩만큼은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M3-2-u4-C4","difficulty":1,"kind":"sa","stem":"「익힘」 길이가 80 cm인 띠의 ⟨3/4⟩만큼은 몇 cm인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["80 cm를 똑같이 4부분으로 나누면 한 부분이 20 cm예요 — 80 ÷ 4 = 20.","⟨3/4⟩은 ⟨1/4⟩이 3개 — 3부분이에요.","80 cm의 ⟨3/4⟩만큼은 60 cm예요. 분자 3만 보고 답하지 않아요."],"asset":{"type":"fbar","bars":[{"den":4,"num":3,"label":"띠 80 cm"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_d#5','math',3,2,'u4','','tb_g3_2_math_u4_review_d','unit_review','M3-2-u4-C5',1,'mc','auto','「확인 문제」 분수 ⟨6/13⟩은 진분수, 가분수, 대분수, 자연수 중 무엇인가요?',ARRAY['M3-2-u4-X08']::text[],false,'{"seq":5,"concept":"M3-2-u4-C5","difficulty":1,"kind":"mc","stem":"「확인 문제」 분수 ⟨6/13⟩은 진분수, 가분수, 대분수, 자연수 중 무엇인가요?","options":[{"t":"진분수","correct":true},{"t":"가분수","mis":"M3-2-u4-X08"},{"t":"대분수","mis":"M3-2-u4-X08"},{"t":"자연수","mis":"M3-2-u4-X08"}],"explanation":["분자 6과 분모 13을 견주어요.","분자가 분모보다 작아요.","⟨6/13⟩은 진분수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_d#6','math',3,2,'u4','','tb_g3_2_math_u4_review_d','unit_review','M3-2-u4-C8',1,'mc','auto','「확인 문제」 두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨1 7/9⟩ ○ ⟨3 1/9⟩',ARRAY['M3-2-u4-X13','M3-2-u4-X22']::text[],false,'{"seq":6,"concept":"M3-2-u4-C8","difficulty":1,"kind":"mc","stem":"「확인 문제」 두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨1 7/9⟩ ○ ⟨3 1/9⟩","options":[{"t":"<","correct":true},{"t":">","mis":"M3-2-u4-X13"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["분모가 같은 대분수는 먼저 자연수의 크기를 비교해요.","자연수의 크기가 같으면 진분수의 크기를 비교해요.","그래서 ⟨1 7/9⟩ < ⟨3 1/9⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_d#7','math',3,2,'u4','','tb_g3_2_math_u4_review_d','unit_review','M3-2-u4-C9',1,'mc','auto','「스스로 마무리하기」 수직선에 나타낸 부분을 대분수와 소수로 바르게 나타낸 것은 무엇인가요?',ARRAY['M3-2-u4-X16','M3-2-u4-X17','M3-2-u4-X15']::text[],false,'{"seq":7,"concept":"M3-2-u4-C9","difficulty":1,"kind":"mc","stem":"「스스로 마무리하기」 수직선에 나타낸 부분을 대분수와 소수로 바르게 나타낸 것은 무엇인가요?","options":[{"t":"⟨1 4/10⟩, 1.4","correct":true},{"t":"⟨4 1/10⟩, 4.1","mis":"M3-2-u4-X16"},{"t":"⟨1 4/10⟩, 1.04","mis":"M3-2-u4-X17"},{"t":"⟨4/10⟩, 0.4","mis":"M3-2-u4-X15"}],"explanation":["수직선에 나타낸 부분은 자연수 1과 진분수 ⟨4/10⟩만큼이에요.","⟨1 4/10⟩ — 「일과 십분의 사」라고 읽어요.","⟨1 4/10⟩ = 1.4 — 「일 점 사」라고 읽어요."],"asset":{"type":"fbar","bars":[{"den":10,"num":10},{"den":10,"num":4}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_d#8','math',3,2,'u4','','tb_g3_2_math_u4_review_d','unit_review','M3-2-u4-C10',1,'mc','auto','두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  0.7 ○ 1.2',ARRAY['M3-2-u4-X18','M3-2-u4-X22']::text[],false,'{"seq":8,"concept":"M3-2-u4-C10","difficulty":1,"kind":"mc","stem":"두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  0.7 ○ 1.2","options":[{"t":"<","correct":true},{"t":">","mis":"M3-2-u4-X18"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["0.7은 0.1이 7개, 1.2는 0.1이 12개예요.","자연수의 크기를 먼저 비교하고, 같으면 소수점 오른쪽 수의 크기를 비교해요.","그래서 0.7 < 1.2."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_d#9','math',3,2,'u4','','tb_g3_2_math_u4_review_d','unit_review','M3-2-u4-C3',2,'mc','auto','사탕 12개의 ⟨2/3⟩만큼은 몇 개인가요?',ARRAY['M3-2-u4-X04','M3-2-u4-X23']::text[],false,'{"seq":9,"concept":"M3-2-u4-C3","difficulty":2,"kind":"mc","stem":"사탕 12개의 ⟨2/3⟩만큼은 몇 개인가요?","options":[{"t":"8개","correct":true},{"t":"2개","mis":"M3-2-u4-X04"},{"t":"6개","mis":"M3-2-u4-X23"}],"explanation":["12개를 똑같이 3묶음으로 나누면 한 묶음이 4개예요 — 12 ÷ 3 = 4.","⟨2/3⟩는 ⟨1/3⟩이 2개 — 2묶음이에요.","12개의 ⟨2/3⟩만큼은 8개예요. 분자 2만 보고 답하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_d#10','math',3,2,'u4','','tb_g3_2_math_u4_review_d','unit_review','M3-2-u4-C10',2,'mc','auto','50 m 달리기 기록이 준우는 9.8초, 지훈이는 10.1초예요. 누가 더 빠른가요?',ARRAY['M3-2-u4-X19','M3-2-u4-X22']::text[],false,'{"seq":10,"concept":"M3-2-u4-C10","difficulty":2,"kind":"mc","stem":"50 m 달리기 기록이 준우는 9.8초, 지훈이는 10.1초예요. 누가 더 빠른가요?","options":[{"t":"준우","correct":true},{"t":"지훈","mis":"M3-2-u4-X19"},{"t":"두 사람이 같아요","mis":"M3-2-u4-X22"},{"t":"알 수 없어요","mis":"M3-2-u4-X22"}],"explanation":["자연수를 비교하면 9 < 10이므로 9.8 < 10.1이에요.","걸린 시간이 짧을수록 빨라요.","준우가 더 빨라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_d#11','math',3,2,'u4','','tb_g3_2_math_u4_review_d','unit_review','M3-2-u4-C6',2,'mc','auto','자연수 2를 분모가 4인 가분수로 바르게 나타낸 것은 무엇인가요?',ARRAY['M3-2-u4-X09','M3-2-u4-X03','M3-2-u4-X10']::text[],false,'{"seq":11,"concept":"M3-2-u4-C6","difficulty":2,"kind":"mc","stem":"자연수 2를 분모가 4인 가분수로 바르게 나타낸 것은 무엇인가요?","options":[{"t":"⟨8/4⟩","correct":true},{"t":"⟨2/4⟩","mis":"M3-2-u4-X09"},{"t":"⟨4/8⟩","mis":"M3-2-u4-X03"},{"t":"⟨6/4⟩","mis":"M3-2-u4-X10"}],"explanation":["⟨1/4⟩이 4개이면 1이에요 — 1 = ⟨4/4⟩.","2는 1이 2개 — ⟨1/4⟩이 4 × 2 = 8개예요.","2 = ⟨8/4⟩ — 자연수를 그대로 분자에 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_d#12','math',3,2,'u4','','tb_g3_2_math_u4_review_d','unit_review','M3-2-u4-C7',2,'mc','auto','「익힘」 레몬주스를 만드는 데 레몬즙이 ⟨1 5/7⟩컵 필요해요. 레몬즙의 양을 가분수로 나타내면 무엇인가요?',ARRAY['M3-2-u4-X10','M3-2-u4-X03','M3-2-u4-X21']::text[],false,'{"seq":12,"concept":"M3-2-u4-C7","difficulty":2,"kind":"mc","stem":"「익힘」 레몬주스를 만드는 데 레몬즙이 ⟨1 5/7⟩컵 필요해요. 레몬즙의 양을 가분수로 나타내면 무엇인가요?","options":[{"t":"⟨12/7⟩","correct":true},{"t":"⟨6/7⟩","mis":"M3-2-u4-X10"},{"t":"⟨7/12⟩","mis":"M3-2-u4-X03"},{"t":"⟨13/7⟩","mis":"M3-2-u4-X21"}],"explanation":["자연수 1은 ⟨1/7⟩이 7개예요.","⟨5/7⟩는 ⟨1/7⟩이 5개 — 모두 7 + 5 = 12개예요.","⟨1 5/7⟩ = ⟨12/7⟩ — 분모는 그대로 두고 단위분수의 개수를 세어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_d#13','math',3,2,'u4','','tb_g3_2_math_u4_review_d','unit_review','M3-2-u4-C9',2,'mc','auto','「익힘」 배추흰나비 애벌레의 길이 2 cm 8 mm는 몇 cm인지 소수로 나타내면 무엇인가요?',ARRAY['M3-2-u4-X17','M3-2-u4-X16']::text[],false,'{"seq":13,"concept":"M3-2-u4-C9","difficulty":2,"kind":"mc","stem":"「익힘」 배추흰나비 애벌레의 길이 2 cm 8 mm는 몇 cm인지 소수로 나타내면 무엇인가요?","options":[{"t":"2.8 cm","correct":true},{"t":"2.08 cm","mis":"M3-2-u4-X17"},{"t":"8.2 cm","mis":"M3-2-u4-X16"},{"t":"28 cm","mis":"M3-2-u4-X17"}],"explanation":["8 mm는 1 cm를 똑같이 10으로 나눈 것 중의 8 — ⟨8/10⟩ cm = 0.8 cm예요.","2 cm 8 mm = ⟨2 8/10⟩ cm예요.","2 cm 8 mm = 2.8 cm — 「이 점 팔」이라고 읽어요."],"asset":{"type":"mmruler","len":28,"label":"애벌레"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_d#14','math',3,2,'u4','','tb_g3_2_math_u4_review_d','unit_review','M3-2-u4-C7',2,'mc','auto','⟨1 2/3⟩를 바르게 읽은 것은 무엇인가요?',ARRAY['M3-2-u4-X03','M3-2-u4-X16','M3-2-u4-X12']::text[],false,'{"seq":14,"concept":"M3-2-u4-C7","difficulty":2,"kind":"mc","stem":"⟨1 2/3⟩를 바르게 읽은 것은 무엇인가요?","options":[{"t":"일과 삼분의 이","correct":true},{"t":"일과 이분의 삼","mis":"M3-2-u4-X03"},{"t":"일 점 이삼","mis":"M3-2-u4-X16"},{"t":"삼분의 이","mis":"M3-2-u4-X12"}],"explanation":["대분수는 자연수 부분을 먼저 읽고 「과(와)」를 붙여요.","분수 부분은 분모부터 「○분의 △」로 읽어요.","⟨1 2/3⟩는 「일과 삼분의 이」라고 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_d#15','math',3,2,'u4','','tb_g3_2_math_u4_review_d','unit_review','M3-2-u4-C4',2,'sa','auto','「익힘」 채원이는 하루의 ⟨2/24⟩만큼 독서를 했어요. 하루는 24시간이에요. 독서를 한 시간은 몇 시간인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"M3-2-u4-C4","difficulty":2,"kind":"sa","stem":"「익힘」 채원이는 하루의 ⟨2/24⟩만큼 독서를 했어요. 하루는 24시간이에요. 독서를 한 시간은 몇 시간인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["24시간을 똑같이 24부분으로 나누면 한 부분이 1시간이에요 — 24 ÷ 24 = 1.","⟨2/24⟩는 ⟨1/24⟩이 2개 — 2부분이에요.","24시간의 ⟨2/24⟩만큼은 2시간이에요. 분자 2만 보고 답하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_d#16','math',3,2,'u4','','tb_g3_2_math_u4_review_d','unit_review','M3-2-u4-C11',2,'mc','auto','두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨3 1/10⟩ ○ 2.8',ARRAY['M3-2-u4-X14','M3-2-u4-X22']::text[],false,'{"seq":16,"concept":"M3-2-u4-C11","difficulty":2,"kind":"mc","stem":"두 수의 크기를 비교하여 ○ 안에 >, =, < 중 알맞은 것을 고르세요.  ⟨3 1/10⟩ ○ 2.8","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u4-X14"},{"t":"=","mis":"M3-2-u4-X22"}],"explanation":["분모가 10인 분수는 소수로 나타내어 비교할 수 있어요.","⟨3 1/10⟩ = 3.1이에요.","자연수부터 비교하면 ⟨3 1/10⟩ > 2.8."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_d#17','math',3,2,'u4','','tb_g3_2_math_u4_review_d','unit_review','M3-2-u4-C8',3,'mc','auto','「익힘」 ⟨3 2/6⟩와 ⟨16/6⟩의 크기를 바르게 비교한 것은 무엇인가요?',ARRAY['M3-2-u4-X14','M3-2-u4-X10','M3-2-u4-X13']::text[],false,'{"seq":17,"concept":"M3-2-u4-C8","difficulty":3,"kind":"mc","stem":"「익힘」 ⟨3 2/6⟩와 ⟨16/6⟩의 크기를 바르게 비교한 것은 무엇인가요?","options":[{"t":"⟨3 2/6⟩ = ⟨20/6⟩이므로 ⟨3 2/6⟩ > ⟨16/6⟩","correct":true},{"t":"16 > 3이므로 ⟨16/6⟩이 더 커요","mis":"M3-2-u4-X14"},{"t":"⟨3 2/6⟩ = ⟨5/6⟩이므로 ⟨16/6⟩이 더 커요","mis":"M3-2-u4-X10"},{"t":"⟨2/6⟩ < ⟨4/6⟩이므로 ⟨3 2/6⟩ < ⟨16/6⟩","mis":"M3-2-u4-X13"}],"explanation":["⟨3 2/6⟩ = ⟨20/6⟩이에요.","분자를 비교하면 20 > 16이에요.","⟨16/6⟩ = ⟨2 4/6⟩로 바꾸어 자연수 3 > 2로 견주어도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_d#18','math',3,2,'u4','','tb_g3_2_math_u4_review_d','unit_review','M3-2-u4-C2',3,'mc','auto','8을 2씩 묶으면 4는 8의 ⟨2/4⟩이고, 8을 4씩 묶으면 4는 8의 ⟨1/2⟩이에요. 같은 4인데 분수가 다르게 나온 까닭은 무엇인가요?',ARRAY['M3-2-u4-X02','M3-2-u4-X22','M3-2-u4-X20']::text[],false,'{"seq":18,"concept":"M3-2-u4-C2","difficulty":3,"kind":"mc","stem":"8을 2씩 묶으면 4는 8의 ⟨2/4⟩이고, 8을 4씩 묶으면 4는 8의 ⟨1/2⟩이에요. 같은 4인데 분수가 다르게 나온 까닭은 무엇인가요?","options":[{"t":"묶는 방법이 달라 전체 묶음의 수가 달라져서","correct":true},{"t":"전체의 개수가 달라져서","mis":"M3-2-u4-X02"},{"t":"둘 중 하나는 잘못 나타낸 것이라서","mis":"M3-2-u4-X22"},{"t":"4는 8의 절반이 아니라서","mis":"M3-2-u4-X20"}],"explanation":["전체는 똑같이 8이에요.","2씩 묶으면 4묶음 중 2묶음, 4씩 묶으면 2묶음 중 1묶음이에요.","묶는 방법이 달라지면 분모와 분자가 달라져요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[0,1],[1,1],[1,2],[0,2]],"hi":true},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]]},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]]},{"p":[[2.7,1],[3.7,1],[3.7,2],[2.7,2]]},{"p":[[3.7,1],[4.7,1],[4.7,2],[3.7,2]]}],"u":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_d#19','math',3,2,'u4','','tb_g3_2_math_u4_review_d','unit_review','M3-2-u4-C3',3,'ox','auto','「익힘」 지아는 「나는 10개의 ⟨4/10⟩만큼, 서윤이는 10개의 ⟨1/2⟩만큼 넣었으니까 분자가 큰 내가 더 많이 넣었어.」라고 했어요. 지아의 말이 옳은가요?',ARRAY['M3-2-u4-X04']::text[],false,'{"seq":19,"concept":"M3-2-u4-C3","difficulty":3,"kind":"ox","stem":"「익힘」 지아는 「나는 10개의 ⟨4/10⟩만큼, 서윤이는 10개의 ⟨1/2⟩만큼 넣었으니까 분자가 큰 내가 더 많이 넣었어.」라고 했어요. 지아의 말이 옳은가요?","answer":"X","reason_options":[{"t":"10개의 ⟨1/2⟩만큼은 5개, ⟨4/10⟩만큼은 4개라서","correct":true},{"t":"분자 4가 1보다 크니까","mis":"M3-2-u4-X04"}],"mis":"M3-2-u4-X04","explanation":["10개의 ⟨1/2⟩만큼은 5개예요.","10개의 ⟨4/10⟩만큼은 4개예요.","5 > 4 — 서윤이가 더 많이 넣었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_d#20','math',3,2,'u4','','tb_g3_2_math_u4_review_d','unit_review','M3-2-u4-C5',3,'sa','auto','「익힘」 수 카드 4, 4, 5, 9 중에서 2장을 뽑아 한 번씩만 사용하여 가분수를 만들려고 해요. 만들 수 있는 가분수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":20,"concept":"M3-2-u4-C5","difficulty":3,"kind":"sa","stem":"「익힘」 수 카드 4, 4, 5, 9 중에서 2장을 뽑아 한 번씩만 사용하여 가분수를 만들려고 해요. 만들 수 있는 가분수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["가분수는 분자가 분모와 같거나 분모보다 커요.","⟨4/4⟩, ⟨5/4⟩, ⟨9/4⟩, ⟨9/5⟩예요.","모두 4개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_d#21','math',3,2,'u4','','tb_g3_2_math_u4_review_d','unit_review','M3-2-u4-C9',3,'mc','auto','1을 똑같이 10칸으로 나눈 띠 2개 중 14칸을 색칠했어요. 색칠한 부분을 분수로 나타낸 다음 소수로 바르게 쓴 것은 무엇인가요?',ARRAY['M3-2-u4-X15','M3-2-u4-X16','M3-2-u4-X17']::text[],false,'{"seq":21,"concept":"M3-2-u4-C9","difficulty":3,"kind":"mc","stem":"1을 똑같이 10칸으로 나눈 띠 2개 중 14칸을 색칠했어요. 색칠한 부분을 분수로 나타낸 다음 소수로 바르게 쓴 것은 무엇인가요?","options":[{"t":"⟨1 4/10⟩, 1.4","correct":true},{"t":"⟨4/10⟩, 0.4","mis":"M3-2-u4-X15"},{"t":"⟨1 4/10⟩, 4.1","mis":"M3-2-u4-X16"},{"t":"⟨1 4/10⟩, 1.04","mis":"M3-2-u4-X17"}],"explanation":["띠 하나가 통째로 색칠되어 자연수 1이에요.","남은 띠는 10칸 중 4칸 — ⟨4/10⟩ = 0.4예요.","⟨1 4/10⟩ = 1.4예요."],"asset":{"type":"fbar","bars":[{"den":10,"num":10},{"den":10,"num":4}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_d#22','math',3,2,'u4','','tb_g3_2_math_u4_review_d','unit_review','M3-2-u4-C11',3,'sa','auto','⟨1 □/10⟩과 1.△의 크기를 비교했더니 ⟨1 □/10⟩이 더 컸어요. □에는 8 또는 9, △에는 7, 8, 9 중 하나가 들어가요. □가 9일 때 △에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":22,"concept":"M3-2-u4-C11","difficulty":3,"kind":"sa","stem":"⟨1 □/10⟩과 1.△의 크기를 비교했더니 ⟨1 □/10⟩이 더 컸어요. □에는 8 또는 9, △에는 7, 8, 9 중 하나가 들어가요. □가 9일 때 △에 들어갈 수 있는 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["□가 9이면 ⟨1 9/10⟩ = 1.9예요.","△는 9보다 작아야 해요 — 7, 8이에요.","모두 2개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_d#23','math',3,2,'u4','','tb_g3_2_math_u4_review_d','unit_review','M3-2-u4-C2',4,'essay','teacher','8을 2씩 묶을 때와 4씩 묶을 때, 4는 각각 8의 얼마인지 분수로 쓰고 왜 분수가 다르게 나오는지 설명해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M3-2-u4-C2","difficulty":4,"kind":"essay","stem":"8을 2씩 묶을 때와 4씩 묶을 때, 4는 각각 8의 얼마인지 분수로 쓰고 왜 분수가 다르게 나오는지 설명해 보세요.","answer_guide":{"answer":"예: 2씩 묶으면 4묶음 중 2묶음이라 4는 8의 ⟨2/4⟩이고, 4씩 묶으면 2묶음 중 1묶음이라 4는 8의 ⟨1/2⟩이다. 묶는 방법이 달라지면 전체 묶음의 수와 부분 묶음의 수가 달라지기 때문이다.","scoring_points":["⟨2/4⟩를 썼는가","⟨1/2⟩을 썼는가","묶는 방법에 따라 묶음의 수가 달라진다고 설명했는가"]},"explanation":["2씩 → 4묶음 중 2묶음이에요.","4씩 → 2묶음 중 1묶음이에요.","묶는 방법이 다르면 분수도 달라요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2.7,0],[3.7,0],[3.7,1],[2.7,1]],"hi":true},{"p":[[3.7,0],[4.7,0],[4.7,1],[3.7,1]],"hi":true},{"p":[[5.4,0],[6.4,0],[6.4,1],[5.4,1]]},{"p":[[6.4,0],[7.4,0],[7.4,1],[6.4,1]]},{"p":[[8.1,0],[9.1,0],[9.1,1],[8.1,1]]},{"p":[[9.1,0],[10.1,0],[10.1,1],[9.1,1]]}],"u":29}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_d#24','math',3,2,'u4','','tb_g3_2_math_u4_review_d','unit_review','M3-2-u4-C6',4,'essay','teacher','자연수 1과 2를 분모가 4인 가분수로 나타내고, 그 방법을 이야기해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M3-2-u4-C6","difficulty":4,"kind":"essay","stem":"자연수 1과 2를 분모가 4인 가분수로 나타내고, 그 방법을 이야기해 보세요.","answer_guide":{"answer":"예: ⟨1/4⟩이 4개이면 1이므로 1 = ⟨4/4⟩이다. 2는 1이 2개이므로 ⟨1/4⟩이 8개이고 2 = ⟨8/4⟩이다.","scoring_points":["1 = ⟨4/4⟩를 썼는가","2 = ⟨8/4⟩을 썼는가","⟨1/4⟩의 개수를 분자로 쓴다고 설명했는가"]},"explanation":["1 = ⟨4/4⟩예요.","2 = ⟨8/4⟩이에요.","분모는 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u4_review_d#25','math',3,2,'u4','','tb_g3_2_math_u4_review_d','unit_review','M3-2-u4-C10',4,'essay','teacher','「익힘」 「서술형」 큐브 빨리 맞추기 대회에서 서준이는 7.3초, 건우는 6.7초, 도윤이는 6.5초가 걸렸어요. 가장 빨리 큐브를 맞춘 사람은 누구인지 풀이 과정을 쓰고 답을 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u4-C10","difficulty":4,"kind":"essay","stem":"「익힘」 「서술형」 큐브 빨리 맞추기 대회에서 서준이는 7.3초, 건우는 6.7초, 도윤이는 6.5초가 걸렸어요. 가장 빨리 큐브를 맞춘 사람은 누구인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 자연수의 크기를 비교하면 7.3이 가장 크다. 6.7과 6.5는 자연수가 같으므로 소수점 오른쪽 수를 비교하면 6.7 > 6.5이다. 걸린 시간이 가장 짧은 사람은 6.5초인 도윤이므로 가장 빨리 맞춘 사람은 도윤이다.","scoring_points":["자연수의 크기를 먼저 비교했는가","6.7 > 6.5를 비교했는가","도윤이라고 답했는가"]},"explanation":["7.3이 가장 커요.","6.7 > 6.5예요.","도윤이가 가장 빨라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
